-- 御朱印(spot_type='goshuin')の初期データ 全6584件
-- OSM Overpass(amenity=place_of_worship, religion=shinto/buddhist)でwikipedia/wikidataタグの
-- 付いた寺社を全国一括取得し、Wikipedia記事が存在するものに絞り込んだ上で、
-- 直近60日ページビュー数の相対順位でランクを機械的に区分した(観光地のランク基準とは別物、
-- A上位5%/B次15%/C次30%/D次30%/E残り20%。Wikipedia記事が見つからなかった一部はE固定)。
-- 座標・名称・説明文はOSM/Wikipedia由来。国土数値情報等の内容は含まない。
-- 都道府県はOSM座標と国土数値情報の都道府県境ポリゴンとの空間検索で機械的に判定した近似値。
insert into spots
  (spot_type_id, name, name_kana, prefecture, municipality, lat, lng, rank, category, description)
select t.id, v.name, v.name_kana, v.prefecture, v.municipality, v.lat, v.lng, v.rank, v.category, v.description
from spot_types t,
