    ('當麻寺', null, '奈良県', null, 34.5159946, 135.6944964, 'A', '寺院', '當麻寺（たいまでら、常用漢字体：当麻寺）は、奈良県葛城市當麻にある真言宗・浄土宗二宗の寺院。法号は禅林寺。'),
    ('三嶋大社', null, '静岡県', '三島市', 35.121854, 138.9190723, 'A', '神社', '三嶋大社（みしまたいしゃ、三島大社）は、静岡県三島市大宮町にある神社。式内社（名神大社）、伊豆国一宮、伊豆国総社。'),
    ('生國魂神社行宮', null, '大阪府', null, 34.6823424, 135.5112403, 'A', '神社', null),
    ('鞍馬寺', null, '京都府', null, 35.1178389, 135.7707261, 'A', '寺院', null),
    ('室生寺', null, '奈良県', null, 34.5379679, 136.0406198, 'A', '寺院', '室生寺（むろうじ）は、奈良県宇陀市室生にある真言宗室生寺派の大本山の寺院。山号は宀一山（べんいちさん）または檉生山（むろうさん）。'),
    ('二荒山神社', null, '栃木県', '日光市', 36.7583924, 139.5963813, 'A', '神社', '日光二荒山神社（にっこうふたらさんじんじゃ）は、栃木県日光市にある神社。式内社（名神大社）論社、下野国一宮。'),
    ('二荒山神社中宮祠', null, '栃木県', '日光市', 36.7416026, 139.4876546, 'A', '神社', null),
    ('大石寺', null, '静岡県', null, 35.2803961, 138.5844896, 'A', '寺院', '大石寺（たいせきじ）は、日蓮正宗総本山の寺院である。宗祖は日蓮。'),
    ('大峯山寺', null, '奈良県', null, 34.2534066, 135.9400235, 'A', '神社', '大峯山寺（おおみねさんじ）は、奈良県吉野郡天川村にある修験道の寺院である。大峯山山上ヶ岳の山頂に建つ。'),
    ('鷲宮神社', null, '埼玉県', '久喜市', 36.0999753, 139.6548687, 'A', '神社', null),
    ('籠神社', null, '京都府', null, 35.5825856, 135.1968627, 'A', '神社', null),
    ('霧島神宮', null, '鹿児島県', '霧島市', 31.8586127, 130.8712947, 'A', '神社', null),
    ('智積院', null, '京都府', null, 34.9879368, 135.7768287, 'A', '寺院', '智積院（ちしゃくいん）は、京都市東山区にある真言宗智山派の総本山の寺院。山号は五百佛山（いおぶさん）。'),
    ('相国寺', null, '京都府', null, 35.0325994, 135.761858, 'A', '寺院', '相国寺（しょうこくじ）は、京都市上京区相国寺門前町にある臨済宗相国寺派の大本山の寺院。山号は萬年山（まんねんざん）。'),
    ('輪王寺', null, '栃木県', null, 36.7548552, 139.6007723, 'A', '寺院', null),
    ('彌彦神社', null, '新潟県', null, 37.7069008, 138.8263409, 'A', '神社', '弥彦神社（やひこじんじゃ、旧字体: 彌彥神󠄀社󠄁）は、新潟県西蒲原郡弥彦村弥彦にある神社。式内社（名神大社）、越後国一宮。'),
    ('建長寺', null, '神奈川県', null, 35.3324309, 139.555963, 'A', '寺院', '建長寺（けんちょうじ）は、神奈川県鎌倉市山ノ内にある禅宗の寺院で、臨済宗建長寺派の大本山。正式には巨福山建長興国禅寺（こふくさんけんちょうこうこくぜんじ）と号する。'),
    ('サムハラ 神社', null, '大阪府', null, 34.6789515, 135.4909725, 'A', '神社', 'サムハラ神社（サムハラじんじゃ）は、大阪府大阪市西区立売堀（いたちぼり）にある神社である。'),
    ('豊川稲荷', null, '愛知県', null, 34.8257995, 137.3927463, 'A', '寺院', null),
    ('久遠寺', null, '山梨県', '身延町', 35.3812636, 138.4265599, 'A', '寺院', '久遠寺（くおんじ）は、山梨県南巨摩郡身延町にある、日蓮宗の総本山（祖山）。山号は身延山。'),
    ('円覚寺', null, '神奈川県', null, 35.3379538, 139.54828, 'A', '寺院', '円覚寺（えんがくじ）は、神奈川県鎌倉市山ノ内にある寺院。正式には瑞鹿山円覚興聖禅寺（ずいろくさんえんがくこうしょうぜんじ 山号: 瑞鹿山）と号する。'),
    ('回向院', null, '東京都', '墨田区', 35.6933386, 139.7920396, 'A', '寺院', '回向院（えこういん）は、東京都墨田区両国二丁目にある浄土宗の寺院、および過去にその別院であった東京都荒川区南千住五丁目にある寺院。'),
    ('上野東照宮', null, '東京都', null, 35.7153982, 139.7706324, 'A', '神社', '上野東照宮（うえのとうしょうぐう）は、東京都台東区上野恩賜公園内にある神社。旧社格は府社。'),
    ('護国寺', null, '東京都', '文京区', 35.7211012, 139.7268482, 'A', '寺院', null),
    ('萬福寺', null, '京都府', '宇治市', 34.9140148, 135.8068867, 'A', '寺院', null),
    ('茨城県護国神社', null, '茨城県', null, 36.3746259, 140.4474782, 'A', '神社', null),
    ('朝護孫子寺', null, '奈良県', null, 34.6090885, 135.6703389, 'A', '寺院', '朝護孫子寺（ちょうごそんしじ）は、奈良県生駒郡平群町信貴山にある信貴山真言宗の総本山の寺院。山号は信貴山。'),
    ('大覚寺', null, '京都府', null, 35.0286469, 135.6794868, 'A', '寺院', '大覚寺（だいかくじ）は、京都市右京区嵯峨大沢町にある真言宗大覚寺派の大本山の寺院。山号は嵯峨山。'),
    ('熊野速玉大社', null, '和歌山県', null, 33.7322611, 135.9836507, 'A', '神社', null),
    ('鎌原観音堂', null, '群馬県', null, 36.5161836, 138.5484, 'A', '寺院', null),
    ('玉置神社', null, '奈良県', null, 33.9248571, 135.8300095, 'A', '神社', '玉置神社（たまきじんじゃ）は、奈良県吉野郡十津川村にある神社。大峰山系の霊山の一つである玉置山の山頂直下の9合目に位置し、大峯奥駈道の靡（なびき）のひとつである。'),
    ('瑞巌寺', null, '宮城県', null, 38.3721758, 141.0595579, 'A', '寺院', null),
    ('吉備津神社', null, '岡山県', null, 34.6707449, 133.8506114, 'A', '神社', '吉備津神社（きびつじんじゃ）は、岡山県岡山市北区吉備津にある神社。式内社（名神大社）、備中国一宮。'),
    ('寶山寺', null, '奈良県', null, 34.6843892, 135.6864001, 'A', '寺院', '寳山寺（ほうざんじ）は、奈良県生駒市門前町にある真言律宗の大本山の寺院。山号は生駒山。'),
    ('東京大神宮', null, '東京都', null, 35.7000073, 139.7468581, 'A', '神社', '東京大神宮（とうきょうだいじんぐう）は、東京都千代田区富士見二丁目にある神社。天照皇大神・豊受大神を主祭神とする。'),
    ('青蓮院', null, '京都府', null, 35.0074835, 135.7833712, 'A', '寺院', null),
    ('秩父神社', null, '埼玉県', '秩父市', 35.9976288, 139.0842502, 'A', '神社', null),
    ('熊野那智大社', null, '和歌山県', null, 33.6684719, 135.890338, 'A', '神社', null),
    ('宇治上神社', null, '京都府', null, 34.8920436, 135.8114973, 'A', '神社', '宇治上神社（うじがみじんじゃ/うじかみじんじゃ）は、京都府宇治市宇治山田にある神社。式内社で、旧社格は村社。'),
    ('松岡山東慶寺', null, '神奈川県', '鎌倉市', 35.3344556, 139.5456041, 'A', '寺院', '東慶寺（とうけいじ）は、神奈川県鎌倉市山ノ内にある臨済宗円覚寺派の寺院である。山号は松岡山、寺号は東慶総持禅寺。'),
    ('北海道神宮', null, '北海道', null, 43.0545817, 141.3092301, 'A', '神社', '北海道神宮（ほっかいどうじんぐう）は、北海道札幌市中央区にある神社（神宮）。円山公園に隣接する。'),
    ('石山寺', null, '滋賀県', null, 34.9604102, 135.9054905, 'A', '寺院', '石山寺（いしやまでら）は、滋賀県大津市石山寺にある東寺真言宗の大本山の寺院。山号は石光山。'),
    ('三千院', null, '京都府', null, 35.1195241, 135.8350497, 'A', '寺院', '三千院（さんぜんいん）は、京都市左京区大原来迎院町にある天台宗の寺院。山号は魚山（ぎょざん）。'),
    ('真清田神社', null, '愛知県', null, 35.3075018, 136.8019814, 'A', '神社', null),
    ('明月院', null, '神奈川県', '鎌倉市', 35.3349178, 139.5516872, 'A', '寺院', '明月院（めいげついん）は、神奈川県鎌倉市山ノ内にある臨済宗建長寺派の寺院。正式には福源山明月院（ふくげんざめいげついん）と号する。'),
    ('鵜戸神宮', null, '宮崎県', '日南市', 31.6492649, 131.466212, 'A', '神社', null),
    ('熊野大社', null, '島根県', null, 35.3732128, 133.0705728, 'A', '神社', '熊野大社（くまのたいしゃ）は、島根県松江市八雲町熊野にある神社。式内社（名神大社）、出雲国一宮。'),
    ('川崎大師', null, '神奈川県', '川崎市', 35.5340918, 139.7294498, 'A', '寺院', '平間寺（へいけんじ）は、神奈川県川崎市川崎区にある、真言宗智山派の大本山。1128年（大治3年）建立。'),
    ('高台寺', null, '京都府', null, 35.0003229, 135.781354, 'A', '寺院', null),
    ('宇都宮二荒山神社', null, '栃木県', null, 36.5624338, 139.8853744, 'A', '神社', '宇都宮二荒山神社（うつのみやふたあらやまじんじゃ、-ふたらやまじんじゃ）は、栃木県宇都宮市にある神社。式内社（名神大社）論社、下野国一宮。'),
    ('槇尾山施福寺（槇尾寺）', null, '大阪府', null, 34.3929129, 135.5116081, 'A', '寺院', '施福寺（せふくじ）は、大阪府和泉市槙尾山町にある天台宗の寺院。山号は槇尾山。'),
    ('白峯神宮', null, '京都府', null, 35.0302768, 135.753149, 'A', '神社', '白峯神宮（しらみねじんぐう）は、京都市上京区東飛鳥井町にある神社。配流されてその地で歿した崇徳天皇・淳仁天皇を祀る。'),
    ('櫛田神社', null, '福岡県', null, 33.5930723, 130.4106976, 'A', '神社', '櫛田神社（くしだじんじゃ）は福岡県福岡市博多区上川端町にある神社。旧社格は県社。'),
    ('総本山 聖護院門跡', null, '京都府', null, 35.01908, 135.7806399, 'A', '寺院', null),
    ('愛宕神社', null, '京都府', '京都市', 35.0599954, 135.6344724, 'A', '神社', '愛宕神社（あたごじんじゃ）は、京都市右京区嵯峨愛宕町にある神社。旧称は阿多古神社。'),
    ('長谷寺', null, '神奈川県', '鎌倉市', 35.3123395, 139.5332494, 'A', '寺院', null),
    ('生田神社', null, '兵庫県', null, 34.6947669, 135.1904861, 'A', '神社', '生田神社（いくたじんじゃ）は、兵庫県神戸市中央区にある神社。式内社（名神大社）で、旧社格は官幣中社。'),
    ('丹生都比売神社', null, '和歌山県', 'かつらぎ町', 34.2630761, 135.5214845, 'A', '神社', '丹生都比売神社（にうつひめじんじゃ、にぶつひめじんじゃ、丹生都比賣神社）は、和歌山県伊都郡かつらぎ町上天野にある神社。式内社（名神大社）、紀伊国一宮。'),
    ('吉田神社', null, '京都府', null, 35.0243784, 135.7845746, 'A', '神社', '吉田神社（よしだじんじゃ）は、京都市左京区吉田神楽岡町にある神社。吉田山に位置する。'),
    ('柴又帝釈天', null, '東京都', '葛飾区', 35.7584204, 139.8787384, 'A', '寺院', '柴又帝釈天（しばまたたいしゃくてん）または、帝釈天 題経寺（たいしゃくてん だいきょうじ）は、東京都葛飾区柴又七丁目にある日蓮宗の寺院。'),
    ('廣田神社', null, '兵庫県', null, 34.7529338, 135.3400056, 'A', '神社', '廣田神社（ひろたじんじゃ、広田神社）は、兵庫県西宮市大社町にある神社。式内社（名神大社）、二十二社（下八社）の一社。'),
    ('豪徳寺', null, '東京都', '世田谷区', 35.648682, 139.6473095, 'A', '寺院', null),
    ('大安寺', null, '奈良県', null, 34.6679364, 135.8127455, 'A', '寺院', '大安寺（だいあんじ）は、奈良県奈良市大安寺二丁目にある高野山真言宗の寺院。山号はなし。'),
    ('本圀寺', null, '京都府', null, 34.9992115, 135.8073267, 'A', '寺院', '本圀寺（ほんこくじ）は、京都市山科区御陵大岩にある日蓮宗の大本山（霊跡寺院）の寺院。山号は大光山。'),
    ('覚王山日泰寺', null, '愛知県', null, 35.1715764, 136.9550206, 'A', '寺院', null),
    ('安房神社', null, '千葉県', '館山市', 34.922593, 139.8370142, 'A', '神社', '安房神社（あわじんじゃ）は、千葉県館山市大神宮にある神社。式内社（名神大社）、安房国一宮。'),
    ('修多羅寺', null, '茨城県', null, 36.4751657, 140.2850357, 'A', '寺院', '修多羅寺（しゅたらじ）は、茨城県東茨城郡城里町小勝にある日蓮宗の寺院。山号は長久山、旧本山は大本山法華経寺(中山門流)。'),
    ('乃木神社', null, '東京都', '港区', 35.668586, 139.727995, 'A', '神社', '乃木神社（のぎじんじゃ）は、東京都港区赤坂にある神社。明治期の軍人・乃木希典（乃木希典命）とその妻・乃木静子（乃木静子命）を祀る。'),
    ('小網神社', null, '東京都', null, 35.6841674, 139.7804475, 'A', '神社', '小網神社（こあみじんじゃ）は、東京都中央区日本橋小網町にある神社。「小網神社社殿及び神楽殿附棟札・造営関係資料」は中央区有形文化財となっている（1991年4月1日指定）。'),
    ('愛宕神社', null, '東京都', null, 35.6649257, 139.7488172, 'A', '神社', '愛宕神社（あたごじんじゃ）は、東京都港区愛宕一丁目にある神社。戦勝や防火に連なる愛宕権現を祀っており（愛宕信仰）、京都の愛宕神社が総本社である。'),
    ('鳥越神社', null, '東京都', null, 35.7019971, 139.7857711, 'A', '神社', null),
    ('多田神社', null, '兵庫県', null, 34.8608963, 135.402667, 'A', '神社', '多田神社（ただじんじゃ）は、兵庫県川西市多田院多田所町にある神社。旧社格は県社で、現在は神社本庁の別表神社。'),
    ('金戒光明寺', null, '京都府', null, 35.0194721, 135.7884216, 'A', '寺院', null),
    ('青岸渡寺', null, '和歌山県', null, 33.6693068, 135.8899207, 'A', '寺院', null),
    ('毛越寺', null, '岩手県', null, 38.9882247, 141.1073021, 'A', '寺院', '毛越寺（もうつうじ）は、岩手県西磐井郡平泉町（創建時は陸奥国磐井郡平泉）に所在する、天台宗の寺院。現在の本尊は薬師如来立像（平安時代後期の作。'),
    ('調神社', null, '埼玉県', 'さいたま市', 35.8534177, 139.6556849, 'A', '神社', '調神社（つきじんじゃ）は、埼玉県さいたま市浦和区岸町三丁目にある神社。式内社で、旧社格は県社。'),
    ('湯島天満宮', null, '東京都', '文京区', 35.7076842, 139.7678622, 'A', '神社', '湯島天満宮（ゆしまてんまんぐう）は、東京都文京区湯島三丁目にある天満宮で、菅原道真を含む二柱の祭神を祀る神社。通称は湯島天神（ゆしまてんじん）、旧称は湯島神社（ゆしまじんじゃ）。'),
    ('大阪天満宮', null, '大阪府', null, 34.6961478, 135.5127788, 'A', '神社', '大阪天満宮（おおさかてんまんぐう）は、大阪市北区天神橋にある神社。別名に天満天神・浪華菅廟・中島天満宮がある。'),
    ('伊勢神宮 外宮', null, '三重県', null, 34.4873236, 136.703365, 'A', '神社', null),
    ('神護寺', null, '京都府', null, 35.0544255, 135.6698692, 'A', '寺院', null),
    ('神魂神社', null, '島根県', null, 35.4255144, 133.084434, 'A', '神社', '神魂神社（かもすじんじゃ）は、島根県松江市大庭町にある神社である。旧社格は県社で、意宇六社の一社。'),
    ('高麗神社', null, '埼玉県', null, 35.8985741, 139.3227046, 'A', '神社', null),
    ('瑠璃光寺', null, '山口県', null, 34.1898401, 131.4717766, 'A', '寺院', '瑠璃光寺（るりこうじ）は、山口市香山町にある、仏教曹洞宗の寺院。国宝の五重塔を中心として、境内は香山公園と呼ばれ、桜や梅の名所にもなっている。'),
    ('箱根神社', null, '神奈川県', null, 35.2039578, 139.0255666, 'A', '神社', null),
    ('息栖神社', null, '茨城県', null, 35.8858155, 140.6251097, 'A', '神社', '息栖神社（いきすじんじゃ）は、茨城県神栖市息栖にある神社。国史見在社で、旧社格は県社。'),
    ('阿蘇神社', null, '熊本県', '阿蘇市', 32.9476916, 131.1160299, 'A', '神社', null),
    ('一心寺', null, '大阪府', null, 34.6527185, 135.5106576, 'A', '寺院', '一心寺（いっしんじ）は、大阪市天王寺区にある浄土宗の寺院。山号は坂松山（ばんしょうざん）。'),
    ('枚岡神社', null, '大阪府', null, 34.6698429, 135.6505061, 'A', '神社', '枚岡神社（ひらおかじんじゃ）は、大阪府東大阪市出雲井町（いずもいちょう）にある神社。式内社（名神大社）、河内国一宮。'),
    ('鑁阿寺', null, '栃木県', null, 36.3375432, 139.4521176, 'A', '寺院', null),
    ('木島坐天照御魂神社', null, '京都府', null, 35.014456, 135.7134253, 'A', '神社', '木嶋坐天照御魂神社（このしまにますあまてるみたまじんじゃ、木島坐天照御魂神社）は、京都市右京区太秦森ケ東町にある神社。式内社（名神大社）で、旧社格は郷社。'),
    ('西宮神社', null, '兵庫県', '西宮市', 34.7352092, 135.3346532, 'A', '神社', null),
    ('猿田彦神社', null, '三重県', null, 34.4673487, 136.720861, 'A', '神社', '猿田彦神社（さるたひこじんじゃ）は、三重県伊勢市の伊勢神宮内宮の近くにある神社である。猿田彦大神と、その子孫の大田命を祭神とする。'),
    ('金山神社', null, '神奈川県', null, 35.5345537, 139.7246453, 'A', '神社', null),
    ('大雄山最乗寺', null, '神奈川県', null, 35.3019559, 139.0754344, 'A', '寺院', null),
    ('西新井大師', null, '東京都', '足立区', 35.779756, 139.7806452, 'A', '寺院', null),
    ('安居神社', null, '大阪府', null, 34.6544824, 135.5109293, 'A', '神社', '安居神社（やすいじんじゃ）は、大阪市天王寺区にある神社。旧社格は村社。'),
    ('大樹寺', null, '愛知県', null, 34.9843176, 137.1652924, 'A', '寺院', '大樹寺（だいじゅじ / だいじゅうじ）は、愛知県岡崎市鴨田町にある浄土宗の寺院。徳川氏（松平氏）の菩提寺。'),
    ('神呪寺', null, '兵庫県', null, 34.7731861, 135.3298353, 'A', '寺院', '神呪寺（かんのうじ、神咒寺）は、兵庫県西宮市甲山町にある真言宗御室派の別格本山の寺院。山号は甲山。'),
    ('中山法華経寺', null, '千葉県', '市川市', 35.7202948, 139.9482157, 'A', '寺院', '法華経寺（ほけきょうじ）は、千葉県市川市中山二丁目にある日蓮宗大本山の寺院である。鎌倉時代の文応元年（1260年）創立。'),
    ('頂法寺', null, '京都府', null, 35.0076246, 135.7603754, 'A', '寺院', null),
    ('崇福寺', null, '福岡県', null, 33.6055059, 130.4139533, 'A', '寺院', '崇福寺（そうふくじ）は、福岡県福岡市博多区にある臨済宗大徳寺派の寺院。同派三道場の一つ。'),
    ('南宮大社', null, '岐阜県', null, 35.3606897, 136.5253565, 'A', '神社', '南宮大社（なんぐうたいしゃ）は、岐阜県不破郡垂井町にある神社。古くから「なんぐうさん」と呼ばれる。'),
    ('水無瀬神宮', null, '大阪府', null, 34.8850406, 135.6727538, 'A', '神社', '水無瀬神宮（みなせじんぐう）は、大阪府三島郡島本町にある神社。旧社格は官幣大社で、現在は神社本庁の別表神社。'),
    ('天河大弁財天社', null, '奈良県', null, 34.2234827, 135.8417126, 'A', '神社', '天河大弁財天社（てんかわだいべんざいてんしゃ、天河神社）は、奈良県吉野郡天川村坪内にある神社。旧社格は郷社。'),
    ('小野神社', null, '東京都', null, 35.6530699, 139.4419497, 'A', '神社', '小野神社（おのじんじゃ）は、東京都多摩市にある神社。式内社論社、武蔵国一宮を称する。'),
    ('露 天神社', null, '大阪府', null, 34.6991011, 135.5008272, 'A', '神社', null),
    ('平野神社', null, '京都府', null, 35.032364, 135.7325114, 'A', '神社', '平野神社（ひらのじんじゃ）は、京都市北区平野宮本町にある神社。式内社（名神大社）で、二十二社（上七社）の一社。'),
    ('傳通院', null, '東京都', null, 35.7124809, 139.746878, 'A', '寺院', '伝通院（でんづういん）は、東京都文京区小石川三丁目の高台にある浄土宗の寺。正式名称は、無量山 伝通院 寿経寺（むりょうざん・でんづういん・じゅきょうじ）。'),
    ('淡嶋神社', null, '和歌山県', null, 34.273696, 135.0666881, 'A', '神社', '淡嶋神社（あわしまじんじゃ）は、和歌山県和歌山市加太にある神社。式内社論社で、旧社格は郷社。'),
    ('大洗磯前神社', null, '茨城県', null, 36.3157434, 140.587729, 'A', '神社', '大洗磯前神社（おおあらいいそさきじんじゃ）は、茨城県東茨城郡大洗町にある、大己貴命と少彦名命を祀る神社。式内社（名神大社）。'),
    ('瑠璃光院', null, '京都府', '京都市', 35.0635691, 135.8086163, 'A', '寺院', '瑠璃光院（るりこういん）は、京都市左京区上高野にある寺院。岐阜市に本坊を置く「浄土真宗無量寿山光明寺」の支院で、本尊は阿弥陀如来。'),
    ('須磨寺', null, '兵庫県', null, 34.6491725, 135.1114723, 'A', '寺院', null),
    ('高山寺', null, '京都府', null, 35.0604829, 135.6777774, 'A', '寺院', '高山寺（こうざんじ、こうさんじ）は、京都市右京区梅ヶ畑栂尾町（とがのおちょう）にある真言宗系単立の寺院。山号は栂尾山。'),
    ('浅草神社', null, '東京都', null, 35.7149242, 139.797547, 'A', '神社', '浅草神社（あさくさじんじゃ）は、東京都台東区浅草に所在する浅草寺本堂の東隣りにある神社である。通称に三社権現（さんじゃごんげん）、三社様（さんじゃさま）。'),
    ('阿夫利神社本社', null, '神奈川県', '伊勢原市', 35.4406014, 139.2311081, 'A', '神社', '大山阿夫利神社（おおやまあふりじんじゃ）は、神奈川県伊勢原市の大山（別名: 雨降山〈あふりやま〉）にある神社である。'),
    ('鹿児島神宮', null, '鹿児島県', '霧島市', 31.7536248, 130.7380701, 'A', '神社', '鹿児島神宮（かごしまじんぐう）は、鹿児島県霧島市隼人町内（はやとちょううち）にある神社。式内大社（国幣大社）、大隅国一宮。'),
    ('橘寺', null, '奈良県', null, 34.469922, 135.8179167, 'A', '寺院', '橘寺（たちばなでら）は、奈良県高市郡明日香村橘にある天台宗の寺院。山号は仏頭山。'),
    ('紫雲山 中山寺', null, '兵庫県', null, 34.8212057, 135.3678039, 'A', '寺院', '中山寺（なかやまでら）は、兵庫県宝塚市中山寺にある真言宗中山寺派の大本山の寺院。山号は紫雲山。'),
    ('観心寺', null, '大阪府', '河内長野市', 34.4369378, 135.5985146, 'A', '寺院', null),
    ('龍光院', null, '京都府', null, 35.0421148, 135.7434513, 'A', '寺院', null),
    ('東本願寺', null, '東京都', null, 35.7117233, 139.7895232, 'A', '寺院', '東本願寺（ひがしほんがんじ）は、東京都台東区西浅草にある浄土真宗東本願寺派の本山である。本尊は阿弥陀如来。'),
    ('生島足島神社', null, '長野県', null, 36.3604632, 138.2180323, 'A', '神社', null),
    ('弘明寺', null, '神奈川県', '横浜市', 35.4242245, 139.5975361, 'A', '寺院', '弘明寺（ぐみょうじ）は、神奈川県横浜市南区弘明寺町にある高野山真言宗の寺院。瑞應山蓮華院と号し、横浜市内最古の寺院である。'),
    ('九品山 唯在念佛院 浄真寺', null, '東京都', null, 35.6084285, 139.6606912, 'A', '寺院', '九品仏浄真寺（くほんぶつじょうしんじ）は、東京都世田谷区奥沢七丁目にある浄土宗の寺である。山号は「九品山」、正式名称は「九品山唯在念佛院淨眞寺」。'),
    ('圓隆寺', null, '広島県', null, 34.389227, 132.4625932, 'A', '寺院', 'とうかさん（稲荷さん・稲荷山・稲荷参）は、広島県広島市中区三川町にある日蓮宗の寺院、福昌山 慈善院 圓隆寺（ふくしょうざん じぜんいん えんりゅうじ）のこと。'),
    ('瑞龍寺', null, '富山県', null, 36.7355981, 137.0105367, 'A', '寺院', '瑞龍寺（ずいりゅうじ）は、富山県高岡市にある曹洞宗の仏教寺院。山号は高岡山（こうこうざん）。'),
    ('喜多院', null, '埼玉県', null, 35.9178006, 139.488985, 'A', '寺院', '喜多院（きたいん）は、埼玉県川越市にある天台宗の寺院。山号は星野山（せいやさん）。'),
    ('伊勢山皇大神宮', null, '神奈川県', null, 35.4503736, 139.6262336, 'A', '神社', '伊勢山皇大神宮（いせやまこうたいじんぐう）は、神奈川県横浜市西区宮崎町にある神社。
天照皇大神を祭神とし、桜の花が社紋である。'),
    ('根津神社', null, '東京都', '文京区', 35.7200041, 139.7607627, 'A', '神社', '根津神社（ねづじんじゃ）は、東京都文京区根津にある神社。旧社格は府社で、元准勅祭社（東京十社）。'),
    ('平塚八幡宮', null, '神奈川県', '平塚市', 35.3336368, 139.3490446, 'A', '神社', '平塚八幡宮（ひらつかはちまんぐう）は、神奈川県平塚市浅間町（せんげんちょう）にある神社。旧社格は県社で、現在は神社本庁の別表神社。'),
    ('清浄光寺', null, '神奈川県', null, 35.3480792, 139.4883602, 'A', '寺院', '清浄光寺（しょうじょうこうじ）は、神奈川県藤沢市にある時宗総本山の寺院。藤沢山無量光院清浄光寺と号す。'),
    ('鳥海山大物忌神社', null, '山形県', null, 39.0977038, 140.048707, 'A', '神社', null),
    ('秋葉山本宮秋葉神社上社', null, '静岡県', null, 34.9811091, 137.8656319, 'A', '神社', null),
    ('中宮寺', null, '奈良県', '斑鳩町', 34.6149294, 135.739858, 'A', '寺院', '中宮寺（ちゅうぐうじ）は、奈良県生駒郡斑鳩町法隆寺北にある聖徳宗の寺院。山号は法興山。'),
    ('上御霊神社', null, '京都府', null, 35.0365172, 135.7614034, 'A', '神社', '上御霊神社（かみごりょうじんじゃ）は、京都市上京区上御霊竪町にある神社。旧社格は府社。'),
    ('甲斐善光寺', null, '山梨県', null, 35.6659552, 138.5929174, 'A', '寺院', '善光寺（ぜんこうじ）は、山梨県甲府市善光寺にある浄土宗の寺院。山号は定額山（じょうがくざん）。'),
    ('宮崎神宮', null, '宮崎県', null, 31.9383583, 131.4235103, 'A', '神社', '宮﨑神宮（みやざきじんぐう）は、宮崎県宮崎市神宮にある神社である。旧社格は官幣大社で、現在は神社本庁の別表神社。'),
    ('三室戸寺', null, '京都府', null, 34.8997569, 135.8183283, 'A', '寺院', '三室戸寺（みむろとじ）は、京都府宇治市にある本山修験宗の別格本山の寺院。山号は明星山。'),
    ('大鳥大社', null, '大阪府', '大阪市', 34.5364001, 135.4604746, 'A', '神社', '大鳥大社（おおとりたいしゃ）は、大阪府堺市西区鳳北町にある神社。和泉国大鳥郡の式内社（名神大社）で、和泉国一宮。'),
    ('西芳寺', null, '京都府', null, 34.9923225, 135.6836028, 'A', '寺院', null),
    ('最上稲荷山 妙教寺', null, '岡山県', '岡山市', 34.7099921, 133.8321428, 'A', '寺院', '最上稲荷（さいじょういなり）は、岡山県岡山市北区にある日蓮宗の寺である。正式名称は最上稲荷山妙教寺。'),
    ('神泉苑', null, '京都府', null, 35.0114436, 135.7481264, 'A', '寺院', '神泉苑（しんせんえん）は、京都市中京区門前町にある東寺真言宗の寺院。本尊は聖観音。'),
    ('法華寺', null, '奈良県', '奈良市', 34.6921886, 135.8044572, 'A', '寺院', '法華寺（ほっけじ）は、奈良県奈良市法華寺町にある光明宗の本山の寺院。山号はなし。'),
    ('成願寺', null, '東京都', null, 35.6940522, 139.6817876, 'A', '寺院', '成願寺（じょうがんじ）は、東京都中野区本町二丁目にある曹洞宗の寺院。山号は多宝山（たほうざん）。'),
    ('玉前神社', null, '千葉県', null, 35.3761992, 140.3605288, 'A', '神社', '玉前神社（たまさきじんじゃ）は、千葉県長生郡一宮町一宮にある神社。式内社（名神大社）、上総国一宮。'),
    ('白鬚神社', null, '滋賀県', null, 35.2745838, 136.0110627, 'A', '神社', null),
    ('吉祥寺', null, '東京都', '文京区', 35.7278356, 139.7545071, 'A', '寺院', '吉祥寺（きちじょうじ）は、東京都文京区本駒込三丁目にある曹洞宗の寺院。山号は諏訪山。'),
    ('宝厳寺', null, '滋賀県', null, 35.4210688, 136.1434294, 'A', '寺院', '宝厳寺（ほうごんじ）は、滋賀県長浜市の竹生島にある真言宗豊山派の寺院。山号は巌金山（がんこんさん）。'),
    ('清凉寺', null, '京都府', null, 35.0235725, 135.6744762, 'A', '寺院', '清凉寺（せいりょうじ）は、京都市右京区嵯峨釈迦堂藤ノ木町にある浄土宗の寺院。山号は五台山（ごだいさん）。'),
    ('六道珍皇寺', null, '京都府', null, 34.998384, 135.7754064, 'A', '寺院', '六道珍皇寺（ろくどうちんのうじ、ろくどうちんこうじ）は、京都市東山区小松町にある臨済宗建仁寺派の寺院。山号は大椿山。'),
    ('都久夫須麻神社', null, '滋賀県', null, 35.4205104, 136.1442493, 'A', '神社', null),
    ('真源寺 入谷鬼子母神', null, '東京都', null, 35.719879, 139.7827173, 'A', '寺院', null),
    ('不動院', null, '広島県', null, 34.4270315, 132.4711145, 'A', '寺院', '不動院（ふどういん）は、広島県広島市東区にある真言宗別格本山（広島県真言宗教団）の寺院。'),
    ('太山寺', null, '兵庫県', null, 34.6966355, 135.0674475, 'A', '寺院', '太山寺（たいさんじ）は、兵庫県神戸市西区にある天台宗の寺院。山号は三身山（さんしんざん）。'),
    ('松陰神社', null, '東京都', null, 35.6471805, 139.6561244, 'A', '神社', null),
    ('美保神社', null, '島根県', null, 35.5622806, 133.3066667, 'A', '神社', null),
    ('耕三寺', null, '広島県', null, 34.3039622, 133.0898242, 'A', '寺院', null),
    ('日御碕神社', null, '島根県', null, 35.4295631, 132.6297468, 'A', '神社', '日御碕神社（ひのみさきじんじゃ）は島根県出雲市の日御碕に鎮座する神社。通称、みさきさん。'),
    ('東峰神社', null, '千葉県', null, 35.784907, 140.3932153, 'A', '神社', '東峰神社（とうほうじんじゃ）は、千葉県成田市東峰にある神社。'),
    ('妻沼聖天山', null, '埼玉県', null, 36.2281887, 139.3746748, 'A', '神社', '歓喜院（かんぎいん）は、埼玉県熊谷市妻沼（めぬま）にある高野山真言宗の仏教寺院である。日本三大聖天の一つとされる。'),
    ('英彦山神社', null, '大分県', null, 33.4779478, 130.9262449, 'A', '神社', null),
    ('極楽寺', null, '神奈川県', '鎌倉市', 35.3101158, 139.5288013, 'A', '寺院', '極楽寺（ごくらくじ）は、神奈川県鎌倉市極楽寺にある真言律宗の寺院である。霊鷲山感応院極楽律寺（りゅうじゅさん かんのういん ごくらくりつじ）と号する。'),
    ('寂光院', null, '京都府', null, 35.12399, 135.820763, 'A', '寺院', '寂光院（じゃっこういん）は、京都市左京区大原にある天台宗の寺院（尼寺）。山号は清香山。'),
    ('水間観音', null, '大阪府', null, 34.3988311, 135.3861089, 'A', '寺院', '水間寺（みずまでら）は、大阪府貝塚市水間にある天台宗の別格本山の寺院。山号は龍谷山。'),
    ('高尾山薬王院', null, '東京都', null, 35.6259769, 139.2497267, 'A', '寺院', '高尾山薬王院（たかおさんやくおういん）は、東京都八王子市の高尾山にある寺院。真言宗智山派の関東三大本山の一つ。'),
    ('大雲院 (京都市)', null, '京都府', null, 35.0021092, 135.7800589, 'A', '寺院', '大雲院（だいうんいん）は、京都市東山区祇園町にある浄土宗系単立の寺院。山号は龍池山。'),
    ('穂高神社', null, '長野県', null, 36.3386217, 137.8843104, 'A', '神社', null),
    ('築土神社', null, '東京都', null, 35.6960609, 139.7499766, 'A', '神社', null),
    ('伊佐須美神社', null, '福島県', null, 37.4564105, 139.8404408, 'A', '神社', '伊佐須美神社（いさすみじんじゃ）は、福島県大沼郡会津美里町宮林にある神社。式内社（名神大社）、陸奥国二宮。'),
    ('法観寺', null, '京都府', null, 34.9985414, 135.7793482, 'A', '寺院', '法観寺（ほうかんじ）は、京都市東山区八坂上町にある臨済宗建仁寺派の寺院。山号は霊応山。'),
    ('來宮神社', null, '静岡県', '熱海市', 35.1002237, 139.067798, 'A', '神社', '來宮神社（きのみやじんじゃ）は、静岡県熱海市にある神社である。社格は旧村社。'),
    ('東長寺', null, '福岡県', null, 33.5951689, 130.4139072, 'A', '寺院', '東長寺（とうちょうじ）は、福岡県福岡市博多区にある真言宗の寺院。九州における真言宗九州教団の拠点寺院（別格本山）である。'),
    ('目黒不動', null, '東京都', null, 35.6282261, 139.7085663, 'A', '寺院', '瀧泉寺（りゅうせんじ）は、東京都目黒区下目黒に所在する天台宗の寺院。山号は泰叡山（たいえいざん）。'),
    ('浄瑠璃寺', null, '京都府', null, 34.7156696, 135.8730764, 'A', '寺院', '浄瑠璃寺（じょうるりじ）は、京都府木津川市加茂町西小字札場（にしお あざ ふたば）にある真言律宗の寺院。山号は小田原山。'),
    ('豊国神社', null, '大阪府', null, 34.6843094, 135.5264155, 'A', '神社', null),
    ('興正寺', null, '京都府', null, 34.9897313, 135.7524615, 'A', '寺院', null),
    ('善福寺', null, '東京都', null, 35.6535644, 139.7328718, 'A', '寺院', '善福寺（ぜんぷくじ）は、東京都港区元麻布一丁目にある浄土真宗本願寺派の寺院。山号は麻布山（あざぶさん）。'),
    ('長谷寺', null, '東京都', '港区', 35.6609025, 139.7190197, 'A', '寺院', null),
    ('武田神社', null, '山梨県', '甲府市', 35.6866895, 138.5773898, 'A', '神社', '武田神社（たけだじんじゃ）は、山梨県甲府市古府中町にある神社。躑躅ヶ崎館の跡地（武田氏館跡）に建てられており、武田信玄を祭神とする。'),
    ('一乗寺', null, '兵庫県', null, 34.8593676, 134.818857, 'A', '寺院', '一乗寺（いちじょうじ）は、兵庫県加西市にある天台宗の寺院。山号は法華山。'),
    ('氷川女体神社', null, '埼玉県', null, 35.8869208, 139.6937649, 'A', '神社', '氷川女体神社（ひかわにょたいじんじゃ）は、埼玉県さいたま市緑区にある神社。登記上の宗教法人名称は旧字体の氷川女體神社である。'),
    ('月読神社 本殿', null, '京都府', null, 34.9965339, 135.6860518, 'A', '神社', '月読神社（つきよみじんじゃ、月讀神社）は、京都市西京区にある神社。式内社（名神大社）で、現在は松尾大社摂社。'),
    ('寿福寺', null, '神奈川県', '鎌倉市', 35.3243223, 139.5501094, 'A', '寺院', '寿福寺（じゅふくじ）は、神奈川県鎌倉市扇ガ谷にある臨済宗建長寺派の寺院である。正式には亀谷山寿福金剛禅寺（きこくさん じゅふくきんごうぜんじ）と号する。'),
    ('壬生寺', null, '京都府', null, 35.0018382, 135.7435526, 'A', '寺院', '壬生寺（みぶでら）は、京都市中京区壬生梛ノ宮町にある律宗の大本山の寺院。山号はなし。'),
    ('笠間稲荷神社', null, '茨城県', null, 36.3854725, 140.2543843, 'A', '神社', null),
    ('大杉神社', null, '茨城県', null, 35.9522474, 140.3826995, 'A', '神社', '大杉神社（おおすぎじんじゃ）は、茨城県稲敷市阿波（あば）にある神社。豪奢な社殿を擁することから「茨城の日光東照宮」の異名がある。'),
    ('昇仙峡', null, '山梨県', null, 35.7458956, 138.5674863, 'A', '神社', '昇仙峡（しょうせんきょう）は、山梨県甲府市、甲府盆地北側、荒川上流に位置する渓谷である。特別名勝に指定されており、国内有数の景勝地である。'),
    ('荒神社', null, '奈良県', null, 34.1575318, 135.6563827, 'A', '神社', '立里荒神社（たてりこうじんしゃ）は、奈良県吉野郡野迫川村大字池津川にある神社である。空海が高野山を開創する際に祀ったと伝わる。'),
    ('雄山神社峰本社', null, '富山県', null, 36.5732195, 137.6178679, 'A', '神社', null),
    ('道明寺', null, '大阪府', null, 34.5688393, 135.6160097, 'A', '寺院', null),
    ('瑞龍寺', null, '滋賀県', null, 35.1442784, 136.0824889, 'A', '寺院', '瑞龍寺（ずいりゅうじ）は、滋賀県近江八幡市宮内町にある日蓮宗の本山（由緒寺院）。山号はなく御所号「村雲御所」を冠する。'),
    ('西國06番 紫雲山 葛井寺（藤井寺）', null, '大阪府', null, 34.5700444, 135.5965987, 'A', '寺院', null),
    ('清荒神清澄寺', null, '兵庫県', null, 34.8220172, 135.3527391, 'A', '寺院', null),
    ('叡福寺', null, '大阪府', '太子町', 34.5187985, 135.6391072, 'A', '寺院', '叡福寺（えいふくじ）は、大阪府南河内郡太子町太子にある太子宗の本山の寺院。山号は磯長山（しながさん）。'),
    ('深川不動尊', null, '東京都', null, 35.6730119, 139.7983051, 'A', '寺院', '成田山 東京別院 深川不動堂（なりたさん とうきょうべついん ふかがわふどうどう）は、東京都江東区富岡にある真言宗智山派の寺院であり、千葉県成田市にある成田山新勝寺の東京別院...'),
    ('藤森神社', null, '京都府', null, 34.9503499, 135.7714799, 'A', '神社', '藤森神社（ふじのもりじんじゃ）は、京都市伏見区深草にある神社。旧社格は府社。'),
    ('麻賀多神社', null, '千葉県', null, 35.7707427, 140.2763125, 'A', '神社', null),
    ('古峯神社', null, '栃木県', null, 36.6548173, 139.5271523, 'A', '神社', '古峯神社（ふるみねじんじゃ）は、栃木県鹿沼市草久（くさぎゅう）にある神社。祭神は日本武尊。'),
    ('新薬師寺', null, '奈良県', null, 34.6758346, 135.8458855, 'A', '寺院', '新薬師寺（しんやくしじ）は、奈良県奈良市高畑町にある華厳宗の寺院。山号は日輪山。'),
    ('身曾岐神社', null, '山梨県', '北杜市', 35.862162, 138.3365381, 'A', '神社', null),
    ('吉備津彦神社', null, '岡山県', null, 34.6765715, 133.8635129, 'A', '神社', '吉備津彦神社（きびつひこじんじゃ）は、岡山県岡山市北区一宮にある神社。備前国一宮。'),
    ('高幡不動尊', null, '東京都', null, 35.6622183, 139.4108786, 'A', '寺院', null),
    ('圓照寺', null, '奈良県', null, 34.6439119, 135.8453895, 'A', '寺院', '圓照寺（えんしょうじ、円照寺）は、奈良市山町にある臨済宗妙心寺派の尼寺。山号は普門山（ふもんざん）。'),
    ('御岩神社', null, '茨城県', null, 36.6361366, 140.5851586, 'A', '神社', '御岩神社（おいわじんじゃ）は、茨城県日立市入四間町にある神社。社格は村社。'),
    ('大甕神社', null, '茨城県', null, 36.5140348, 140.6128827, 'A', '神社', '大甕神社（おおみかじんじゃ）は、茨城県日立市大みか町にある神社。'),
    ('養源院', null, '京都府', null, 34.9879493, 135.7731487, 'A', '寺院', null),
    ('勝手神社', null, '奈良県', '吉野町', 34.3645908, 135.8625968, 'A', '神社', '勝手神社（かつてじんじゃ）とは奈良県吉野郡吉野町にある神社。祭神は『和漢三才図会』に「勝手社 祭神一座 愛鬘命（うけりのみこと／うけのりのみこと）」とある。'),
    ('浄閑寺', null, '東京都', null, 35.7307451, 139.7927922, 'A', '寺院', '浄閑寺（じょうかんじ）は東京都荒川区南千住にある浄土宗の寺院。山号は栄法山。'),
    ('鎌倉宮', null, '神奈川県', null, 35.3258941, 139.5667848, 'A', '神社', null),
    ('杭全神社', null, '大阪府', null, 34.6286767, 135.5548792, 'A', '神社', '杭全神社（くまたじんじゃ）は大阪市平野区平野宮町にある神社。旧社格は府社。'),
    ('北口本宮冨士浅間神社', null, '山梨県', null, 35.4710185, 138.7926872, 'A', '神社', '北口本宮冨士浅間神社（きたぐちほんぐうふじせんげんじんじゃ）は、山梨県富士吉田市上吉田にある神社。旧社格は県社で、現在は神社本庁の別表神社。'),
    ('法起寺', null, '奈良県', '斑鳩町', 34.6227775, 135.7460229, 'A', '寺院', '法起寺（ほっきじ、ほうきじ）は、奈良県生駒郡斑鳩町岡本にある聖徳宗の寺院。山号は岡本山。'),
    ('今宮神社', null, '京都府', null, 35.0456879, 135.7420947, 'A', '神社', '今宮神社（いまみやじんじゃ）は、京都市北区紫野今宮町にある神社。社格は旧府社。'),
    ('花の窟神社', null, '三重県', null, 33.8798309, 136.0933864, 'A', '神社', null),
    ('金地院', null, '京都府', null, 35.0103662, 135.7905, 'A', '寺院', null),
    ('称名寺', null, '神奈川県', null, 35.3436312, 139.6300425, 'A', '寺院', '称名寺（しょうみょうじ）は、神奈川県横浜市金沢区金沢町にある真言律宗別格本山の寺院。山号は金沢山（きんたくさん）。'),
    ('上杉神社', null, '山形県', null, 37.9092747, 140.1040578, 'A', '神社', '上杉神社（うえすぎじんじゃ）は、山形県米沢市にある神社。松が岬公園（米沢城址）に位置し、上杉謙信を祀る。'),
    ('六甲比命神社', null, '兵庫県', null, 34.7661647, 135.2395453, 'A', '神社', '六甲比命大善神社（ろっこうひめだいぜんじんじゃ）は、兵庫県神戸市灘区六甲山町にある、荘厳な磐座をご神体とする神社である。'),
    ('青松寺', null, '東京都', null, 35.662854, 139.7484226, 'A', '寺院', null),
    ('佛光寺', null, '京都府', '下京区', 35.0007264, 135.7622696, 'A', '寺院', '佛光寺（ぶっこうじ）は、京都市下京区高倉通仏光寺下ル新開町にある真宗佛光寺派の本山の寺院。山号は渋谷山（汁谷山）。'),
    ('金鑚神社', null, '埼玉県', null, 36.1808388, 139.0731325, 'A', '神社', null),
    ('鶴林寺', null, '兵庫県', null, 34.7522463, 134.8328727, 'A', '寺院', null),
    ('千葉神社', null, '千葉県', '千葉市', 35.6117558, 140.1237789, 'A', '神社', '千葉神社（ちばじんじゃ）は、千葉県千葉市中央区にある神社。旧社格は県社。'),
    ('真正極楽寺', null, '京都府', null, 35.0213287, 135.7892854, 'A', '寺院', null),
    ('日牟禮八幡宮', null, '滋賀県', null, 35.1409512, 136.0897235, 'A', '神社', '日牟禮八幡宮（ひむれはちまんぐう）は、滋賀県近江八幡市宮内町にある神社。旧社格は県社で、現在は神社本庁の別表神社。'),
    ('飛騨一宮水無神社', null, '岐阜県', null, 36.0853732, 137.2518072, 'A', '神社', null),
    ('円光寺', null, '神奈川県', null, 35.4189174, 139.3465422, 'A', '寺院', '円光寺（えんこうじ）は神奈川県厚木市愛甲にある臨済宗建長寺派の寺院。山号は西嶺山で「円光禅寺」とも称す。'),
    ('可睡斎', null, '静岡県', null, 34.7747985, 137.9198959, 'A', '寺院', '可睡斎（かすいさい）は、静岡県袋井市久能にある曹洞宗の仏教寺院。山号は萬松山（ばんしょうざん）。'),
    ('伊豆山神社', null, '静岡県', null, 35.1155083, 139.0824723, 'A', '神社', '伊豆山神社（いずさんじんじゃ又はいずやまじんじゃ）は、静岡県熱海市伊豆山にある神社。'),
    ('伊和神社', null, '兵庫県', null, 35.0875846, 134.5864874, 'A', '神社', '伊和神社（いわじんじゃ）は、兵庫県宍粟市一宮町須行名にある神社。式内社（名神大社）、播磨国一宮。'),
    ('洲崎神社', null, '千葉県', null, 34.9680853, 139.7576847, 'A', '神社', '洲崎神社（すさきじんじゃ/すのさきじんじゃ）は、千葉県館山市洲崎にある神社。式内社（大社）論社で、江戸時代に安房国一宮とされた。'),
    ('阿遅速遅神社', null, '大阪府', null, 34.6887895, 135.5650147, 'A', '神社', null),
    ('芝大神宮', null, '東京都', null, 35.657597, 139.7530699, 'A', '神社', null),
    ('御上神社', null, '滋賀県', null, 35.049466, 136.0268824, 'A', '神社', '御上神社（みかみじんじゃ）は、滋賀県野洲市三上にある神社。式内社（名神大社）で、旧社格は官幣中社。'),
    ('元乃隅神社', null, '山口県', '長門市油谷津黄498', 34.4201143, 131.0629369, 'A', '神社', '元乃隅神社（もとのすみじんじゃ）は、山口県長門市油谷津黄にある神社。旧称は元乃隅稲成神社（もとのすみいなりじんじゃ）。'),
    ('善峯寺', null, '京都府', null, 34.9384086, 135.64429, 'A', '寺院', '善峯寺（よしみねでら）は、京都市西京区にある善峰観音宗の本山の寺院。山号は西山。'),
    ('白山神社', null, '東京都', null, 35.7218967, 139.7505773, 'A', '神社', '白山神社（はくさんじんじゃ）は、東京都文京区白山にある神社である。旧称白山権現社。'),
    ('常陸国 出雲大社', null, '茨城県', null, 36.3541444, 140.1842832, 'B', '神社', '常陸国出雲大社（ひたちのくにいずもたいしゃ）は、茨城県笠間市に存在する縁結びで有名な神社。元は出雲大社教の分祠だったが、2014年に独立した。'),
    ('四柱神社', null, '長野県', null, 36.2348983, 137.9703559, 'B', '神社', '四柱神社（よはしらじんじゃ）は、長野県松本市大手に鎮座する神社である。地元では、10月の例祭「神道祭」から「しんとう（神道）さん」と呼ばれる。'),
    ('御釜神社', null, '宮城県', null, 38.3160871, 141.0179079, 'B', '神社', '御釜神社（おかまじんじゃ）は、宮城県塩竈市本町にある神社。現在は鹽竈神社の境外末社。'),
    ('東郷神社', null, '東京都', null, 35.6715348, 139.7062357, 'B', '神社', '東郷神社（とうごうじんじゃ）は、東京都渋谷区神宮前一丁目に鎮座する神社。東郷平八郎元帥を祀る。'),
    ('田村神社', null, '香川県', '高松市', 34.2860209, 134.0275641, 'B', '神社', '田村神社（たむらじんじゃ）は、香川県高松市一宮町にある神社。式内社（名神大社）、讃岐国一宮。'),
    ('護王神社', null, '京都府', null, 35.0222097, 135.7588335, 'B', '神社', null),
    ('大念佛寺', null, '大阪府', null, 34.6273421, 135.5505362, 'B', '寺院', '大念仏寺（だいねんぶつじ）は、大阪府大阪市平野区にある融通念仏宗の総本山の寺院。山号は大源山。'),
    ('尾山神社', null, '石川県', null, 36.5660146, 136.6554033, 'B', '神社', '尾山神社（おやまじんじゃ）は、石川県金沢市にある神社。江戸時代後期から明治時代初期に流行した藩祖を祀った神社のひとつ。'),
    ('恩智神社', null, '大阪府', null, 34.6065143, 135.6386261, 'B', '神社', '恩智神社（おんじじんじゃ/おんぢじんじゃ/おんちじんじゃ）は、大阪府八尾市恩智中町にある神社。式内社（名神大社）で、河内国二宮と伝わる。'),
    ('南法華寺', null, '奈良県', null, 34.4261313, 135.809663, 'B', '寺院', '南法華寺（みなみほっけじ）は、奈良県高市郡高取町壺阪にある真言宗系単立の寺院。山号は壺阪山。'),
    ('百済寺', null, '滋賀県', '東近江市', 35.1268273, 136.2915122, 'B', '寺院', '百済寺（ひゃくさいじ）は、滋賀県東近江市百済寺町にある天台宗の寺院。山号は釈迦山。'),
    ('神野寺', null, '千葉県', '君津市', 35.2547912, 139.9632039, 'B', '寺院', null),
    ('保久良神社', null, '兵庫県', null, 34.7355537, 135.2780358, 'B', '神社', '保久良神社（ほくらじんじゃ）は、兵庫県神戸市東灘区本山町の保久良山（金鳥山中腹）に鎮座する神社である。式内社で、旧社格は郷社。'),
    ('実相院', null, '京都府', null, 35.0790218, 135.7815034, 'B', '寺院', '実相院（じっそういん）は、京都市左京区岩倉上蔵町にある天台宗系単立の寺院。山号は岩倉山。'),
    ('廣瀬大社', null, '奈良県', '河合町', 34.5899886, 135.7482912, 'B', '神社', '廣瀬大社（ひろせたいしゃ、広瀬大社）は、奈良県北葛城郡河合町川合にある神社。式内社（名神大社）、二十二社（中七社）の一社。'),
    ('岩木山神社', null, '青森県', null, 40.6209206, 140.3416668, 'B', '神社', '岩木山神社（いわきやまじんじゃ）は、青森県弘前市百沢の岩木山の南東麓にある神社。別称、「お岩木さま」「お山」「奥日光」。'),
    ('大崎八幡宮', null, '宮城県', null, 38.2716699, 140.844874, 'B', '神社', '大崎八幡宮（おおさきはちまんぐう）は、宮城県仙台市青葉区八幡にある神社である。旧社格は村社。'),
    ('豊国神社', null, '愛知県', null, 35.1742565, 136.8545361, 'B', '神社', null),
    ('布多天神社', null, '東京都', '調布市', 35.6567297, 139.545429, 'B', '神社', '布多天神社（ふだてんじんしゃ）は、東京都調布市調布ケ丘にある神社。式内社で、旧社格は郷社。'),
    ('越木岩神社', null, '兵庫県', '西宮市', 34.758459, 135.3221319, 'B', '神社', null),
    ('穴八幡宮', null, '東京都', '新宿区', 35.7071143, 139.7177016, 'B', '神社', null),
    ('観世音寺', null, '福岡県', null, 33.5146915, 130.5218, 'B', '寺院', null),
    ('柳谷観音', null, '京都府', null, 34.9142293, 135.6528366, 'B', '寺院', '楊谷寺（ようこくじ）は、京都府長岡京市浄土谷にある西山浄土宗の寺院。山号は立願山。'),
    ('大宮八幡宮', null, '東京都', '杉並区', 35.682388, 139.6411499, 'B', '神社', '大宮八幡宮（おおみや はちまんぐう）は、日本の南関東、東京都杉並区大宮に所在する神社である。'),
    ('一休寺', null, '京都府', '京田辺市', 34.8206513, 135.7575625, 'B', '寺院', null),
    ('不動院岩屋堂', null, '鳥取県', null, 35.3003347, 134.4303666, 'B', '寺院', '不動院岩屋堂（ふどういんいわやどう）は鳥取県八頭郡若桜町にある修験道寺院の建築である。国の重要文化財。'),
    ('霊山寺', null, '奈良県', null, 34.6741025, 135.7437426, 'B', '寺院', null),
    ('麻羅観音', null, '山口県', null, 34.2961598, 131.0967345, 'B', '寺院', null),
    ('高源寺', null, '埼玉県', null, 36.1341616, 139.4629653, 'B', '寺院', null),
    ('伊太祁曽神社', null, '和歌山県', null, 34.2017081, 135.2500369, 'B', '神社', '伊太祁󠄀曽神社（いたきそじんじゃ）は、和歌山県和歌山市伊太祈曽にある神社。旧称は山東宮。'),
    ('大縣神社', null, '愛知県', null, 35.330152, 136.9669995, 'B', '神社', '大縣神社（おおあがたじんじゃ）は、愛知県犬山市にある神社である。旧社格は、式内社（名神大社）・尾張国二宮・旧国幣中社・別表神社。'),
    ('瀧原宮', null, '三重県', null, 34.3669624, 136.424161, 'B', '神社', '瀧原宮（たきはらのみや）は、三重県度会郡大紀町滝原にある神社であり、内宮（皇大神宮）の別宮である。祭神は天照坐皇大御神御魂（あまてらしますすめおおみかみのみたま）。'),
    ('平林寺', null, '埼玉県', '新座市', 35.789753, 139.5606511, 'B', '寺院', '平林寺（へいりんじ）は、埼玉県新座市野火止にある臨済宗妙心寺派の寺院で、野火止台地に約40ヘクタールの広大な境内を有する。
山号は「金鳳山」である。'),
    ('品川神社', null, '東京都', null, 35.6184327, 139.7399916, 'B', '神社', '品川神社（しながわじんじゃ）は、東京都品川区北品川三丁目にある神社。元准勅祭社として東京十社のひとつでもある。'),
    ('伊奈波神社', null, '岐阜県', null, 35.4275953, 136.7697873, 'B', '神社', '伊奈波神社（いなばじんじゃ）は、岐阜県岐阜市伊奈波通りにある神社。式内社論社、美濃国三宮で、旧社格は国幣小社。'),
    ('豊川稲荷東京別院', null, '東京都', null, 35.6765229, 139.7328114, 'B', '寺院', null),
    ('砥鹿神社', null, '愛知県', null, 34.8476763, 137.421195, 'B', '神社', '砥鹿神社（とがじんじゃ）は、愛知県豊川市にある神社。式内小社、三河国一宮。'),
    ('亀戸天神社', null, '東京都', '江東区', 35.7027062, 139.8209159, 'B', '神社', '亀戸天神社（かめいどてんじんしゃ）は、東京都江東区亀戸にある神社（天満宮）である。天満大神、すなわち菅原道真を祀り、受験生などを中心に学問の神として親しまれている。'),
    ('太郎坊宮 (阿賀神社)', null, '滋賀県', null, 35.1181636, 136.1823366, 'B', '神社', null),
    ('廣峯神社', null, '兵庫県', null, 34.8739138, 134.7003454, 'B', '神社', '広峯神社（ひろみねじんじゃ）は、兵庫県姫路市の広峰山山頂にある神社である。
全国にある牛頭天王の総本宮（ただし、八坂神社も牛頭天王総本宮を主張している）。'),
    ('京都霊山護國神社', null, '京都府', null, 34.9994983, 135.7832131, 'B', '神社', '京都霊山護国神社（きょうとりょうぜんごこくじんじゃ）は、京都市東山区清閑寺霊山町にある神社（護国神社）。現在は神社本庁の管理を離れた別表神社。'),
    ('意富比神社', null, '千葉県', '船橋市', 35.6957451, 139.9931241, 'B', '神社', '意富比神社（おおひじんじゃ）は、千葉県船橋市にある神社。式内社で、旧社格は県社。'),
    ('永観堂 禅林寺', null, '京都府', null, 35.0140953, 135.7949741, 'B', '寺院', '禅林寺（ぜんりんじ）は、京都市左京区永観堂町にある浄土宗西山禅林寺派の総本山の寺院。山号は聖衆来迎山（しょうじゅらいごうさん）。'),
    ('少彦名神社', null, '大阪府', null, 34.6888082, 135.5060348, 'B', '神社', '少彦名神社（すくなひこなじんじゃ）は、大阪市中央区道修町にある神社。旧社格は無格社。'),
    ('円通寺', null, '東京都', null, 35.7339946, 139.792883, 'B', '寺院', '円通寺（えんつうじ）は、東京都荒川区南千住にある曹洞宗の寺院。山号は補陀山。'),
    ('葛城一言主神社', null, '奈良県', null, 34.4453942, 135.7119223, 'B', '神社', null),
    ('天野山金剛寺', null, '大阪府', null, 34.4293773, 135.5291084, 'B', '寺院', null),
    ('林泉寺', null, '新潟県', null, 37.1506629, 138.2130529, 'B', '寺院', '林泉寺（りんせんじ）は、新潟県上越市にある曹洞宗の寺院である。山号は春日山（かすがさん）。'),
    ('蓮華寺', null, '東京都', null, 35.7244396, 139.6738922, 'B', '寺院', null),
    ('誓願寺', null, '京都府', '桜之町', 35.0073476, 135.7676864, 'B', '寺院', null),
    ('臨済寺', null, '静岡県', null, 34.9930073, 138.3758427, 'B', '寺院', null),
    ('宝仙寺', null, '東京都', null, 35.6987247, 139.6795587, 'B', '寺院', '宝仙寺（ほうせんじ）は、東京都中野区中央二丁目にある真言宗豊山派の寺院。
中野区でも屈指の広大な寺院で、千年近くの歴史を誇る古刹である。'),
    ('清澄寺', null, '千葉県', '鴨川市', 35.160979, 140.1514035, 'B', '寺院', '清澄寺（せいちょうじ）は、千葉県鴨川市清澄にある日蓮宗の大本山。山号は千光山。'),
    ('田縣神社', null, '愛知県', null, 35.3157242, 136.9413397, 'B', '神社', '田縣神社（たがたじんじゃ）は、愛知県小牧市にある神社である。『延喜式神名帳』の尾張国丹羽郡「田縣神社」に比定されている。'),
    ('竹駒神社', null, '宮城県', null, 38.1051086, 140.8625463, 'B', '神社', null),
    ('鎌ヶ谷大仏', null, '千葉県', null, 35.7589284, 140.0132364, 'B', '寺院', null),
    ('證誠寺', null, '千葉県', '木更津市', 35.3798984, 139.921245, 'B', '寺院', null),
    ('大報恩寺', null, '京都府', null, 35.0317093, 135.7397851, 'B', '寺院', '大報恩寺（だいほうおんじ）は、京都市上京区にある真言宗智山派の寺院。山号は瑞応山（ずいおうざん）。'),
    ('誉田八幡宮', null, '大阪府', null, 34.5591419, 135.6104944, 'B', '神社', null),
    ('知立神社', null, '愛知県', null, 35.0128077, 137.0410792, 'B', '神社', null),
    ('禅林寺', null, '東京都', null, 35.6943549, 139.5599009, 'B', '寺院', '禅林寺（ぜんりんじ）は、東京都三鷹市にある黄檗宗の寺院である。山号は霊泉山。'),
    ('元善光寺', null, '長野県', null, 35.5340389, 137.8565378, 'B', '寺院', '元善光寺（もとぜんこうじ）は、長野県飯田市座光寺にある天台宗の仏教寺院。元善光寺と名付けられる前は如来寺（にょらいじ）と呼ばれていた。'),
    ('高津宮', null, '大阪府', '中央区', 34.6686688, 135.5138971, 'B', '神社', null),
    ('物部神社', null, '島根県', null, 35.1547152, 132.5132087, 'B', '神社', '物部神社（もののべじんじゃ）は、島根県大田市にある神社。式内社、石見国一宮。'),
    ('城南宮', null, '京都府', '京都市', 34.9505991, 135.7469902, 'B', '神社', '城南宮（じょうなんぐう）は、京都市伏見区にある神社。旧社格は府社。'),
    ('銭洗弁天 宇賀福神社', null, '神奈川県', '鎌倉市', 35.325711, 139.5421784, 'B', '神社', null),
    ('化野念仏寺', null, '京都府', null, 35.026916, 135.664627, 'B', '寺院', '化野念仏寺（あだしのねんぶつじ）は、京都市右京区嵯峨鳥居本化野町にある浄土宗の寺院。山号は華西山。'),
    ('大原野神社', null, '京都府', null, 34.9592814, 135.6560768, 'B', '神社', '大原野神社（おおはらのじんじゃ）は、京都市西京区大原野南春日町にある神社。二十二社（中七社）の一社。'),
    ('氷川神社', null, '埼玉県', null, 35.9275595, 139.4885515, 'B', '神社', '氷川神社（ひかわじんじゃ）は、埼玉県川越市宮下町にある神社。埼玉県さいたま市大宮区の氷川神社と区別するため、川越氷川神社と称されることもある。'),
    ('第51番札所 石手寺', null, '愛媛県', null, 33.8474782, 132.7971145, 'B', '寺院', null),
    ('蛇窪神社', null, '東京都', null, 35.6025704, 139.7153777, 'B', '神社', null),
    ('御金神社', null, '京都府', null, 35.0118266, 135.7549788, 'B', '神社', '御金神社（みかねじんじゃ）は、京都市中京区にある神社。'),
    ('東海寺', null, '東京都', null, 35.6163643, 139.7391202, 'B', '寺院', '東海寺（とうかいじ）は、東京都品川区北品川三丁目にある臨済宗大徳寺派の寺院。山号は万松山。'),
    ('氷上姉子神社', null, '愛知県', null, 35.0615281, 136.9302787, 'B', '神社', '氷上姉子神社（ひかみあねごじんじゃ）は、愛知県名古屋市緑区大高町字火上山にある神社。『延喜式神名帳』に尾張国愛智郡「火上姉子神社」として記載がある式内社で、熱田神宮の境外摂社。'),
    ('大光院', null, '京都府', null, 35.0415771, 135.7435476, 'B', '寺院', '大光院（だいこういん）は、京都市北区紫野大徳寺町にある臨済宗大徳寺派の寺院。大本山大徳寺の塔頭。'),
    ('吉水神社', null, '奈良県', '吉野郡吉野町', 34.3672763, 135.8619316, 'B', '神社', '吉水神社、𠮷水神社（よしみずじんじゃ）は、奈良県吉野郡吉野町にある神社。旧社格は村社。'),
    ('川原寺', null, '奈良県', null, 34.4722013, 135.8173091, 'B', '寺院', '川原寺（かわらでら）は、飛鳥（現・奈良県高市郡明日香村川原）にあった仏教寺院。跡地は国の史跡に指定されている。'),
    ('赤城神社', null, '群馬県', null, 36.5526698, 139.1834805, 'B', '神社', null),
    ('勝鬘院・愛染堂', null, '大阪府', null, 34.6573891, 135.5125862, 'B', '寺院', '勝鬘院（しょうまんいん）は、大阪市天王寺区にある和宗の寺院。山号は荒陵山。'),
    ('宇治神社', null, '京都府', null, 34.8908801, 135.8104621, 'B', '神社', '宇治神社（うじじんじゃ）は、京都府宇治市宇治山田にある神社。式内社で、旧社格は府社。'),
    ('妙本寺', null, '神奈川県', '鎌倉市', 35.3171792, 139.5572259, 'B', '寺院', '妙本寺（みょうほんじ）は、神奈川県鎌倉市大町にある日蓮宗の本山（霊跡寺院）。山号は長興山。'),
    ('海神神社', null, '長崎県', null, 34.4642379, 129.2832937, 'B', '神社', '海神神社（わたつみじんじゃ、通称、かいじんじんじゃ）は、長崎県対馬市峰町木坂にある神社。式内社（名神大社）論社、対馬国一宮。'),
    ('土津神社', null, '福島県', null, 37.5703735, 140.1006415, 'B', '神社', '土津神社（はにつじんじゃ）は、福島県耶麻郡猪苗代町にある神社である。陸奥会津藩初代藩主・保科正之を祀っている。'),
    ('千代保稲荷神社', null, '岐阜県', '海津市', 35.2635496, 136.6464653, 'B', '神社', '千代保稲荷神社（ちよほいなりじんじゃ）は、岐阜県海津市平田町三郷1980にある稲荷神社である。おちょぼさんと呼び親しまれる。'),
    ('毘沙門堂', null, '京都府', null, 35.0011925, 135.8189182, 'B', '寺院', '毘沙門堂（びしゃもんどう）は、京都市山科区にある天台宗の寺院。山号は護法山。'),
    ('土佐稲荷神社', null, '大阪府', null, 34.6749646, 135.4851845, 'B', '神社', '土佐稲荷神社（とさいなりじんじゃ）は、大阪市西区にある神社。旧社格は郷社。'),
    ('王子稲荷神社', null, '東京都', '北区', 35.7560784, 139.7333424, 'B', '神社', '王子稲荷神社（おうじいなりじんじゃ）は、東京都北区岸町にある神社である。東国三十三国稲荷総司との伝承を持ち、民話『王子の狐火』や落語『王子の狐』でも有名。'),
    ('斑鳩寺', null, '兵庫県', null, 34.8373984, 134.5756173, 'B', '寺院', '斑鳩寺（いかるがでら）は、兵庫県揖保郡太子町鵤（いかるが）にある天台宗の寺院。山号はなし。'),
    ('光明寺', null, '京都府', null, 34.9384453, 135.6763879, 'B', '寺院', '光明寺（こうみょうじ）は、京都府長岡京市粟生西条ノ内にある西山浄土宗の総本山の寺院。山号は報国山。'),
    ('般若寺', null, '奈良県', null, 34.7001747, 135.8360535, 'B', '寺院', null),
