    ('八重垣神社', null, '島根県', null, 35.4290249, 133.0737244, 'B', '神社', '八重垣神社（やえがきじんじゃ）は、島根県松江市にある神社である。旧称佐久佐神社（さくさじんじゃ）。'),
    ('成田山 大阪別院', null, '大阪府', null, 34.7802801, 135.6387582, 'B', '寺院', '成田山大阪別院明王院（なりたさんおおさかべついんみょうおういん）は、大阪府寝屋川市成田西町にある真言宗智山派の寺院。山号は成田山。'),
    ('神倉神社', null, '和歌山県', null, 33.7243184, 135.9841214, 'B', '神社', '神倉神社（かみくらじんじゃ、かんのくらじんじゃ）は和歌山県新宮市の神社。熊野三山の一山である熊野速玉大社の摂社。'),
    ('赤坂氷川神社', null, '東京都', null, 35.6681231, 139.7359316, 'B', '神社', '氷川神社（ひかわじんじゃ）は、東京都港区赤坂六丁目にある神社。'),
    ('西大寺観音院', null, '岡山県', null, 34.6536065, 134.0379419, 'B', '寺院', null),
