    ('鰐淵寺', null, '島根県', null, 35.4240094, 132.7488313, 'B', '寺院', null),
    ('仙台東照宮', null, '宮城県', null, 38.2802178, 140.8851128, 'B', '神社', '仙台東照宮（せんだいとうしょうぐう）は、宮城県仙台市青葉区東照宮にある徳川家康をまつる神社。承応3年（1654年）に仙台藩2代藩主伊達忠宗が創建。'),
    ('国泰寺', null, '広島県', null, 34.4144372, 132.4106524, 'B', '寺院', '国泰寺（こくたいじ）は、広島県広島市西区己斐上の大茶臼山西麓にある曹洞宗の寺院である。山号は蓬萊山。'),
    ('売布神社', null, '兵庫県', null, 34.817214, 135.3582955, 'B', '神社', '売布神社（めふじんじゃ、賣布神社）は、兵庫県宝塚市売布山手町にある神社。式内社で、旧社格は郷社。'),
    ('白兎神社', null, '鳥取県', '鳥取市', 35.5242558, 134.1147194, 'B', '神社', '白兎神社（はくと じんじゃ）は、鳥取県鳥取市に所在する神社。旧社格は村社。'),
    ('広島護国神社', null, '広島県', null, 34.4011, 132.4588682, 'B', '神社', '廣島護國神社（ひろしまごこくじんじゃ）は、広島県広島市中区にある護国神社。'),
    ('真宗大谷派名古屋別院', null, '愛知県', null, 35.151987, 136.9021257, 'B', '寺院', '真宗大谷派名古屋別院（しんしゅうおおたにはなごやべついん）は、愛知県名古屋市中区にある真宗大谷派の寺院である。同派の別院。'),
    ('地主神社', null, '京都府', null, 34.9951735, 135.7849639, 'B', '神社', '地主神社（じしゅじんじゃ）と呼ばれる神社は、以下に大別される。

神社や寺院が建立される際に、その土地の地主神を祀るために建立された神社。'),
    ('第38番札所 金剛福寺', null, '高知県', '土佐清水市', 32.7257338, 133.0184172, 'B', '寺院', null),
    ('法善寺', null, '大阪府', null, 34.6678706, 135.5026027, 'B', '寺院', '法善寺（ほうぜんじ）は、大阪府大阪市中央区難波にある浄土宗の寺院。山号は天龍山。'),
    ('雲厳寺', null, '栃木県', null, 36.8529216, 140.2096816, 'B', '寺院', null),
