    ('恵比寿神社', null, '東京都', null, 35.6472232, 139.7077849, 'B', '神社', '恵比寿神社（えびすじんじゃ）は東京都渋谷区恵比寿西、JR恵比寿駅の西約60mの市街地にある神社である。'),
    ('盛岡八幡宮', null, '岩手県', null, 39.695347, 141.1641103, 'B', '神社', null),
    ('寶登山神社', null, '埼玉県', null, 36.0932559, 139.1030646, 'B', '神社', '寳登山神社（ほどさんじんじゃ、常用漢字体：宝登山神社）は、埼玉県秩父郡長瀞町の宝登山山麓にある神社。旧社格は県社で、現在は神社本庁の別表神社。'),
    ('揖夜神社', null, '島根県', null, 35.4307624, 133.1536433, 'B', '神社', '揖夜神社（いやじんじゃ、いふやじんじゃ）は島根県松江市東出雲町揖屋に鎮座する神社である。意宇六社の一つ。'),
    ('射水神社', null, '富山県', null, 36.7486823, 137.0213303, 'B', '神社', '射水神社（いみずじんじゃ）は、富山県高岡市の高岡古城公園内にある神社。登記上の宗教法人名称は越中総鎮守射水神社（えっちゅうそうちんじゅいみずじんじゃ）。'),
    ('義仲寺', null, '滋賀県', null, 35.0029983, 135.8801242, 'B', '寺院', null),
    ('小國神社', null, '静岡県', null, 34.8471739, 137.8994585, 'B', '神社', '小國神社（おくにじんじゃ、小国神社）は、静岡県周智郡森町一宮にある神社。式内社、遠江国一宮。'),
    ('龍潭寺', null, '静岡県', '浜松市', 34.8286004, 137.6679167, 'B', '寺院', null),
    ('新田神社', null, '東京都', '大田区', 35.5658066, 139.6913235, 'B', '神社', '新田神社（にったじんじゃ）は、東京都大田区矢口にある神社である。創建は南北朝時代正平・延文年間。'),
    ('法多山尊永寺', null, '静岡県', null, 34.7376754, 137.9772843, 'B', '寺院', '法多山尊永寺（はったさんそんえいじ）は、静岡県袋井市にある高野山真言宗別格本山の寺院。寺号の「尊永寺」よりも山号の「法多山」の名で広く知られている。'),
    ('西山本門寺', null, '静岡県', null, 35.2371936, 138.5644815, 'B', '寺院', null),
    ('三嶋神社', null, '愛媛県', null, 33.8961263, 133.10725, 'B', '神社', '三島神社、三嶋神社、三嶌神社（みしまじんじゃ）、あるいは三島社（みしましゃ）は、「三島」を社名とする、三島・大山祇信仰の神社。'),
    ('三ツ石神社', null, '岩手県', null, 39.7090125, 141.1543577, 'B', '神社', '三ツ石神社（みついしじんじゃ）は、岩手県盛岡市にある神社。三石神社ともいう。'),
    ('天王寺', null, '東京都', null, 35.7266164, 139.7714235, 'B', '寺院', '天王寺（てんのうじ）は、東京都台東区谷中にある、天台宗の寺院。正式名称は護国山尊重院天王寺である。'),
    ('高円寺', null, '東京都', '杉並区', 35.7037235, 139.652943, 'B', '寺院', null),
    ('鳳来寺', null, '愛知県', null, 34.9787856, 137.5862576, 'B', '寺院', null),
    ('愛宕念仏寺', null, '京都府', null, 35.0310873, 135.6612389, 'B', '寺院', '愛宕念仏寺（おたぎねんぶつじ）は、京都市右京区嵯峨にある天台宗の寺院。山号は等覚山。'),
    ('浄智寺', null, '神奈川県', '鎌倉市', 35.3334817, 139.5463287, 'B', '寺院', '浄智寺（じょうちじ）は、神奈川県鎌倉市山ノ内にある禅宗の寺院。臨済宗円覚寺派に属する。'),
    ('建中寺', null, '愛知県', null, 35.1792303, 136.9269256, 'B', '寺院', '建中寺（けんちゅうじ）は、愛知県名古屋市東区筒井にある浄土宗の寺院。山号は徳興山。'),
    ('阿弥陀寺', null, '京都府', null, 35.0336905, 135.7664412, 'B', '寺院', null),
    ('忌宮神社', null, '山口県', null, 33.9990008, 130.9876241, 'B', '神社', '忌宮神社（いみのみやじんじゃ）は、山口県下関市にある神社。長府（城下町エリア）のほぼ中心に位置し、仲哀天皇が熊襲平定の際に滞在した行宮である豊浦宮の跡とされる。'),
    ('義重山大光院新田寺(大光院)吞龍様', null, '群馬県', '太田市', 36.3059965, 139.3705678, 'B', '寺院', '大光院（だいこういん）は、群馬県太田市金山町にある浄土宗の寺院である。山号は義重山。'),
    ('宝積寺', null, '京都府', null, 34.8953025, 135.6783264, 'B', '寺院', '宝積寺（ほうしゃくじ）は、京都府乙訓郡大山崎町大山崎にある真言宗智山派の寺院。山号は天王山（古くは補陀洛山）。'),
    ('成相寺', null, '京都府', null, 35.5948315, 135.1873657, 'B', '寺院', '成相寺（なりあいじ）は、京都府宮津市成相寺にある橋立真言宗の寺院。山号は成相山。'),
    ('田無神社', null, '東京都', null, 35.7298951, 139.5440509, 'B', '神社', '田無神社（たなしじんじゃ）は、東京都西東京市田無町三丁目にある神社。'),
    ('意賀美神社', null, '大阪府', null, 34.8135253, 135.6437723, 'B', '神社', '意賀美神社（おかみじんじゃ）は、大阪府枚方市にある神社。式内社で、旧社格は村社。'),
    ('縣神社', null, '京都府', null, 34.888515, 135.8057786, 'B', '神社', null),
    ('離宮八幡宮', null, '京都府', null, 34.891651, 135.6796129, 'B', '神社', null),
    ('光前寺', null, '長野県', null, 35.7355573, 137.8966141, 'B', '神社', '光前寺（こうぜんじ）は、長野県駒ヶ根市赤穂にある天台宗の別格本山の寺院である。山号は宝積山（ほうしゃくさん）。'),
    ('比売許曽神社', null, '大阪府', null, 34.666922, 135.5341418, 'B', '神社', '比売許曽神社（ひめこそじんじゃ）は、大阪市東成区にある神社。旧社格は村社。'),
    ('穴太寺', null, '京都府', null, 35.0065725, 135.5491608, 'B', '寺院', null),
    ('とげぬき地蔵尊 高岩寺', null, '東京都', null, 35.7357516, 139.7354944, 'B', '寺院', '高岩寺（こうがんじ）は、東京都豊島区巣鴨にある曹洞宗の寺院。
山号は萬頂山。'),
    ('北畠神社', null, '三重県', null, 34.5190057, 136.2989286, 'B', '神社', '北畠神社（きたばたけじんじゃ）は、三重県津市美杉町上多気にある神社。国の史跡「多気北畠氏城館跡」に鎮座し、初代伊勢国司として南朝奉護に尽くした北畠顕能を主祭神とする。'),
    ('乗蓮寺', null, '東京都', '板橋区', 35.7819486, 139.644452, 'B', '寺院', '乗蓮寺（じょうれんじ）は、東京都板橋区赤塚にある浄土宗別格本山の寺院。東京大仏があることで知られている。'),
    ('志々伎神社', null, '長崎県', null, 33.1789379, 129.3690319, 'B', '神社', '志々伎神社（しじきじんじゃ）は、長崎県平戸市野子町にある神社。志志伎神社あるいは志自伎神社とも表記する。'),
    ('素盞雄神社', null, '東京都', null, 35.7370764, 139.7961243, 'B', '神社', '素盞雄神社（すさのおじんじゃ）は、東京都荒川区南千住にある神社である。地元では千住素盞雄神社や南千住素盞雄神社、お天王様(おてんのうさま)と呼ばれている。'),
    ('善宝寺', null, '山形県', '鶴岡市', 38.772437, 139.767813, 'B', '寺院', '善寳寺（ぜんぽうじ）は、山形県鶴岡市にある曹洞宗の寺院。山号は龍澤山（りゅうたくさん）。'),
    ('総見院', null, '京都府', null, 35.0441543, 135.7445396, 'B', '寺院', '総見院（そうけんいん）は、京都市北区紫野大徳寺町にある臨済宗大徳寺派の寺院。大本山大徳寺の塔頭。'),
    ('志明院', null, '京都府', null, 35.13602, 135.7093425, 'B', '寺院', '志明院（しみょういん）は、京都市北区にある岩屋山不動教の本山の寺院。山号は岩屋山。'),
    ('佐太神社', null, '島根県', null, 35.5089132, 133.0064139, 'B', '神社', '佐太神社（さだじんじゃ）は、島根県松江市鹿島町佐陀宮内にある神社。出雲国二宮、旧社格は国幣小社。'),
    ('阿智神社前宮', null, '長野県', '阿智村', 35.4571601, 137.7165264, 'B', '神社', null),
    ('瑞泉寺', null, '神奈川県', '鎌倉市', 35.3273106, 139.5746838, 'B', '寺院', null),
    ('大中寺', null, '栃木県', null, 36.359688, 139.688778, 'B', '寺院', '大中寺（だいちゅうじ）は、栃木県栃木市大平町西山田にある曹洞宗の寺院で関三刹の1つ。山号は太平山。'),
    ('如意輪寺', null, '奈良県', null, 34.3646638, 135.8675632, 'B', '寺院', '如意輪寺（にょいりんじ）は、奈良県吉野郡吉野町吉野山にある浄土宗の寺院。山号は塔尾山（とうのおさん）。'),
    ('枚聞神社', null, '鹿児島県', null, 31.2078923, 130.5398447, 'B', '神社', '枚聞神社（ひらききじんじゃ）は、鹿児島県指宿市開聞十町にある神社。式内社、薩摩国一宮。'),
    ('國王神社', null, '茨城県', '岩井市', 36.0621464, 139.8897208, 'B', '神社', '国王神社（こくおうじんじゃ）は、茨城県坂東市にある神社。平将門を、その終焉の地に祀る神社である。'),
    ('中山神社', null, '埼玉県', 'さいたま市', 35.9001935, 139.6639862, 'B', '神社', '中山神社（なかやまじんじゃ）は、埼玉県さいたま市見沼区中川にある神社。旧社格は村社。'),
    ('高天彦神社', null, '奈良県', null, 34.4181138, 135.6959341, 'B', '神社', null),
    ('能福寺', null, '兵庫県', null, 34.6679292, 135.1715447, 'B', '寺院', null),
    ('北向観音', null, '長野県', null, 36.3498913, 138.1564174, 'B', '寺院', '北向観音（きたむきかんのん）は、長野県上田市の別所温泉にある天台宗の寺院。近隣にある天台宗常楽寺が本坊であり、その伽藍の一部として同寺が所有・管理する。'),
    ('法住寺', null, '京都府', null, 34.9874175, 135.7727661, 'B', '寺院', '法住寺（ほうじゅうじ）は、京都市東山区三十三間堂廻り町にある天台宗の寺院。本尊は不動明王。'),
    ('那谷寺 華王殿', null, '石川県', null, 36.31318, 136.4205048, 'B', '寺院', null),
    ('五百羅漢寺', null, '東京都', null, 35.6290162, 139.7094319, 'B', '寺院', '五百羅漢寺（ごひゃくらかんじ）は東京都目黒区下目黒にある寺院。宗派はかつて黄檗宗だったが現在は浄土宗系の単立。'),
    ('陸奥国分寺薬師堂', null, '宮城県', null, 38.2512954, 140.9028351, 'B', '寺院', null),
    ('長岡天満宮', null, '京都府', null, 34.9231349, 135.6874113, 'B', '神社', null),
    ('難波神社', null, '大阪府', null, 34.6788167, 135.4999715, 'B', '神社', null),
    ('東照宮', null, '茨城県', null, 36.3726307, 140.4733604, 'B', '神社', '水戸東照宮（みととうしょうぐう）は、茨城県水戸市にある神社である。旧社格は県社で、現在は神社本庁の別表神社。'),
    ('新潟総鎮守 白山神社', null, '新潟県', null, 37.9155007, 139.0377511, 'B', '神社', '白山神社（はくさんじんじゃ）は、新潟県新潟市中央区一番堀通町に鎮座する神社である。彌彦神社、新潟縣護國神社と並び、「新潟の総鎮守」として新潟県を代表する神社の一つである。'),
    ('中禅寺', null, '栃木県', '日光市', 36.7311255, 139.4918125, 'B', '寺院', '中禅寺（ちゅうぜんじ）は栃木県日光市の中禅寺湖畔・歌ヶ浜にある天台宗の寺院である。'),
    ('常光寺', null, '大阪府', null, 34.6302503, 135.5982771, 'B', '寺院', '常光寺（じょうこうじ）は、大阪府八尾市本町にある臨済宗南禅寺派の寺院。南禅寺塔頭金地院（以心崇伝が住持を務めた）の末寺で、山号は初日山。'),
    ('箭弓稲荷神社', null, '埼玉県', null, 36.0344934, 139.3983793, 'B', '神社', null),
    ('光明寺', null, '神奈川県', null, 35.3033692, 139.554529, 'B', '寺院', '光明寺（こうみょうじ）は、神奈川県鎌倉市材木座にある浄土宗の寺院である。寺格は大本山。'),
    ('法界寺', null, '京都府', null, 34.9341695, 135.8148884, 'B', '寺院', '法界寺（ほうかいじ）は、京都市伏見区日野西大道町にある真言宗醍醐派の別格本山の寺院。山号は東光山。'),
    ('万治の石仏', null, '長野県', null, 36.0829236, 138.0819468, 'B', '寺院', '万治の石仏（まんじのせきぶつ）は、長野県諏訪郡下諏訪町東山田字石仏にある、江戸時代前期の1660年（万治3年）に造られた石仏。'),
    ('海住山寺', null, '京都府', null, 34.777012, 135.8616989, 'B', '寺院', '海住山寺（かいじゅうせんじ）は、京都府木津川市加茂町例幣海住山にある真言宗智山派の寺院。山号は補陀洛山（ふだらくさん）。'),
    ('備中国分寺', null, '岡山県', null, 34.6665369, 133.7818173, 'B', '寺院', '備中国分寺（びっちゅうこくぶんじ）は、岡山県総社市にある真言宗御室派の寺院。山号は日照山。'),
    ('第21番札所 太龍寺', null, '徳島県', '阿南市', 33.8825075, 134.5217889, 'B', '寺院', '太龍寺（たいりゅうじ）は、徳島県阿南市加茂町にある高野山真言宗の寺院。舎心山（しゃしんざん）、常住院（じょうじゅういん）と号す。'),
    ('赤城神社', null, '東京都', null, 35.704607, 139.7360988, 'B', '神社', null),
    ('新田神社', null, '鹿児島県', null, 31.82766, 130.2927595, 'B', '神社', '新田神社（にったじんじゃ/にいたじんじゃ）は、鹿児島県薩摩川内市宮内町にある神社。薩摩国一宮。'),
    ('覚林寺', null, '東京都', null, 35.6396629, 139.7316527, 'B', '寺院', null),
    ('川勾神社', null, '神奈川県', null, 35.3001512, 139.2380524, 'B', '神社', '川勾神社（かわわじんじゃ）は、神奈川県中郡二宮町山西にある神社。延長5年（927年）の『延喜式神名帳』に記載されている相模国の延喜式内社十三社の内の一社（小社）とされる。'),
    ('率川神社', null, '奈良県', null, 34.681317, 135.8256561, 'B', '神社', null),
    ('行願寺', null, '京都府', null, 35.0162818, 135.7676705, 'B', '寺院', null),
    ('服部天神宮', null, '大阪府', null, 34.762991, 135.4760247, 'B', '神社', '服部天神宮（はっとりてんじんぐう）は、大阪府豊中市服部元町にある神社。旧社格は村社。'),
    ('榊神社', null, '東京都', '台東区', 35.7001528, 139.7891832, 'B', '神社', null),
    ('恐山菩提寺', null, '青森県', null, 41.3272193, 141.0901213, 'B', '寺院', null),
    ('清見寺', null, '静岡県', null, 35.0476083, 138.5129709, 'B', '寺院', '清見寺（せいけんじ）は、静岡市清水区興津清見寺町にある臨済宗妙心寺派の寺院。'),
    ('多治速比売神社', null, '大阪府', null, 34.5024515, 135.4972964, 'B', '神社', '多治速比売神社（たじはやひめじんじゃ）は、大阪府堺市南区宮山台にある神社。延喜式神名帳に記載されている和泉国大鳥郡の式内社である。'),
    ('宇倍神社', null, '鳥取県', null, 35.4809391, 134.2687545, 'B', '神社', '宇倍神社（うべじんじゃ）は、鳥取県鳥取市国府町宮下にある神社。式内社（名神大社）、因幡国一宮。'),
    ('崇禅寺', null, '大阪府', null, 34.7339078, 135.5085406, 'B', '寺院', '崇禅寺（そうぜんじ）は、大阪市東淀川区にある曹洞宗の寺院。山号は凌雲山。'),
    ('願成就院', null, '静岡県', '伊豆の国市', 35.045674, 138.939896, 'B', '寺院', null),
    ('田島神社', null, '佐賀県', '唐津市', 33.5558076, 129.8904978, 'B', '神社', null),
    ('溝咋神社', null, '大阪府', null, 34.8129786, 135.5886513, 'B', '神社', '溝咋神社（みぞくいじんじゃ）は、大阪府茨木市にある神社。式内社で、旧社格は府社。'),
    ('笠森寺', null, '千葉県', '長南町', 35.3995594, 140.1989312, 'B', '寺院', '笠森寺（かさもりじ）は、千葉県長生郡長南町笠森にある天台宗別格大本山の寺院。本尊は十一面観世音菩薩であり、坂東三十三観音第31番札所となっている。'),
    ('古四王神社', null, '秋田県', null, 39.7363131, 140.0832171, 'B', '神社', '古四王神社（こしおうじんじゃ）は、秋田県秋田市にある神社である。'),
    ('御霊神社', null, '大阪府', null, 34.6873536, 135.4993177, 'B', '神社', '御霊神社（ごりょうじんじゃ）は、大阪市中央区淡路町にある神社。旧社格は府社。'),
