    ('慈尊院', null, '和歌山県', null, 34.2951647, 135.5499064, 'B', '寺院', '慈尊院（じそんいん）は、和歌山県伊都郡九度山町慈尊院にある高野山真言宗の寺院。山号は万年山。'),
    ('四條畷神社', null, '大阪府', null, 34.7319835, 135.6487107, 'B', '神社', '四條畷神社（しじょうなわてじんじゃ）は、大阪府四條畷市にある神社。旧社格は別格官幣社で、現在は神社本庁の別表神社。'),
    ('玉祖神社', null, '山口県', null, 34.0576772, 131.5336557, 'B', '神社', '玉祖神社（たまのおやじんじゃ）は、山口県防府市大崎にある神社。式内社、周防国一宮。'),
    ('慈恩寺', null, '埼玉県', null, 35.9794779, 139.7107972, 'B', '寺院', '慈恩寺（じおんじ）は、埼玉県さいたま市岩槻区大字慈恩寺にある天台宗の寺院である。山号は華林山。'),
    ('瑞聖寺', null, '東京都', null, 35.6372576, 139.7269955, 'B', '寺院', null),
    ('水鏡天満宮', null, '福岡県', null, 33.592535, 130.4018417, 'B', '神社', '水鏡天満宮（すいきょうてんまんぐう）は、福岡県福岡市中央区天神一丁目にある天満宮の1つである。社格は村社。'),
    ('瀧谷不動明王寺', null, '大阪府', null, 34.4758897, 135.596174, 'B', '寺院', '瀧谷不動明王寺（たきだにふどうみょうおうじ）は、大阪府富田林市彼方（おちかた）にある真言宗智山派の寺院。山号は瀧谷山。'),
    ('三島鴨神社', null, '大阪府', null, 34.8029059, 135.6107108, 'B', '神社', '三島鴨神社（みしまかもじんじゃ）は、大阪府高槻市にある神社。式内社論社で、旧社格は郷社。'),
    ('永代寺', null, '東京都', null, 35.6720166, 139.7980954, 'B', '寺院', '永代寺（えいたいじ）は、東京都江東区富岡にある高野山真言宗の寺院。'),
    ('城山八幡宮', null, '愛知県', null, 35.1676303, 136.9596186, 'B', '神社', '城山八幡宮（しろやまはちまんぐう）は、愛知県名古屋市千種区城山町にある神社。当地は戦国時代の織田氏の末森城の跡地であり、空堀が残っている。'),
    ('今戸神社', null, '東京都', null, 35.7191691, 139.8035554, 'B', '神社', '今戸神社（いまどじんじゃ）は、東京都台東区今戸一丁目にある神社。'),
    ('五大堂', null, '宮城県', null, 38.3697199, 141.0642082, 'B', '寺院', '五大堂（ごだいどう）は、宮城県宮城郡松島町の景勝地松島にある仏堂。同町にある臨済宗妙心寺派の寺院・瑞巌寺の境外仏堂である。'),
    ('信松院', null, '東京都', null, 35.6562069, 139.3219203, 'B', '寺院', '信松院（しんしょういん）は、東京都八王子市台町三丁目にある曹洞宗の寺院。山号は金龍山。'),
    ('柞原八幡宮', null, '大分県', null, 33.2382905, 131.5508628, 'B', '神社', '柞原八幡宮（ゆすはらはちまんぐう）は、大分県大分市にある神社。豊後国一宮。'),
    ('青井阿蘇神社', null, '熊本県', '人吉市', 32.2133805, 130.7530453, 'B', '神社', null),
    ('長光山 妙蓮寺', null, '神奈川県', null, 35.4982903, 139.6340838, 'B', '寺院', '妙蓮寺（みょうれんじ）は、神奈川県横浜市港北区にある日蓮宗の寺院。通称、菊名妙蓮寺。'),
    ('愛宕神社', null, '新潟県', null, 37.9161102, 139.040868, 'B', '神社', '古町愛宕神社（ふるまちあたごじんじゃ）は、新潟県新潟市中央区古町通にある神社。越後長岡藩主からの信仰も篤く『愛宕さま』として親しまれてきた。'),
    ('注連寺', null, '山形県', null, 38.6026741, 139.8870577, 'B', '寺院', '注連寺（ちゅうれんじ）は、山形県鶴岡市大網にある真言宗智山派（新義真言宗系）の寺院。戦後、一時的に新義真言宗湯殿山派の大本山として独立していた時期もある。'),
    ('草薙神社', null, '静岡県', null, 34.9944892, 138.4528921, 'B', '神社', null),
    ('西明寺', null, '滋賀県', '甲良町', 35.1833643, 136.2847047, 'B', '寺院', null),
