    ('酒見寺', null, '兵庫県', null, 34.9352874, 134.8293049, 'B', '寺院', null),
    ('片埜神社', null, '大阪府', null, 34.8417662, 135.6678405, 'B', '神社', '片埜神社（かたのじんじゃ）は、大阪府枚方市にある神社。式内社で、旧社格は郷社。'),
    ('本住吉神社', null, '兵庫県', null, 34.7185613, 135.2600242, 'B', '神社', '本住吉神社（もとすみよしじんじゃ）は、兵庫県神戸市東灘区にある神社である。旧社格は県社。'),
    ('普天満宮', null, '沖縄県', null, 26.2927597, 127.7772328, 'B', '神社', '普天満宮（ふてんまぐう）は、沖縄県宜野湾市普天間にある神社。宜野湾市で唯一の神社でもある。'),
    ('賢崇寺', null, '東京都', null, 35.6544071, 139.7333663, 'B', '寺院', null),
