    ('所澤神明社', null, '埼玉県', null, 35.7941698, 139.4633727, 'B', '神社', '所澤神明社（ところさわしんめいしゃ）は、埼玉県所沢市宮本町にある神社である。所澤総鎮守であり「武蔵国（むさしのくに）のお伊勢さま」としても知られる。'),
    ('三寳寺', null, '東京都', null, 35.7361152, 139.5973944, 'B', '寺院', '三宝寺（さんぼうじ、公式表記：三寳寺）は、東京都練馬区石神井台にある真言宗智山派の寺院である。山号は亀頂山(きちょうざん)。'),
    ('大水上神社', null, '香川県', null, 34.1480617, 133.7552202, 'B', '神社', '大水上神社（おおみなかみじんじゃ）は、香川県三豊市高瀬町にある神社である。式内社で、旧社格は県社。'),
    ('百済王神社', null, '大阪府', null, 34.815274, 135.6602695, 'B', '神社', '百濟王神社（くだらおうじんじゃ）は、大阪府枚方市中宮西之町にある神社。旧社格は村社。'),
    ('気多神社', null, '富山県', null, 36.800035, 137.0449698, 'B', '神社', '気多神社（けたじんじゃ）は、富山県高岡市伏木一宮にある神社。式内社（名神大社または小社）、越中国一宮。'),
    ('興福院', null, '奈良県', null, 34.6942732, 135.8223288, 'B', '寺院', null),
