    ('英勝寺', null, '神奈川県', '鎌倉市', 35.3251108, 139.5498364, 'B', '寺院', null),
    ('稲毛浅間神社', null, '千葉県', '千葉市', 35.6365088, 140.0822689, 'B', '神社', '稻毛浅間神社（いなげせんげんじんじゃ）は、千葉県千葉市稲毛区稲毛にある浅間神社。旧社格は村社。'),
    ('第44番札所 大宝寺 (Daihō-ji)', null, '愛媛県', null, 33.6612356, 132.9115866, 'B', '寺院', '大寶寺（だいほうじ）は、愛媛県上浮穴郡久万高原町にある真言宗豊山派の寺院。菅生山（すごうざん）、大覚院（だいかくいん）と号す。'),
    ('安楽寺', null, '長野県', null, 36.3521426, 138.1531466, 'B', '寺院', '安楽寺（あんらくじ）は長野県上田市別所温泉にある曹洞宗の寺院。山号を崇福山と称する。'),
    ('源光庵', null, '京都府', null, 35.0547677, 135.7317934, 'B', '寺院', '源光庵（げんこうあん）は、京都市北区鷹峯にある曹洞宗の寺院。山号は鷹峰山。'),
    ('聖神社', null, '埼玉県', null, 36.0501051, 139.1025932, 'B', '神社', null),
    ('大神山神社', null, '鳥取県', null, 35.3889999, 133.5382995, 'B', '神社', '大神山神社（おおがみやまじんじゃ）は、鳥取県にある神社である。式内社、伯耆国二宮で、旧社格は国幣小社。'),
    ('信濃国分寺', null, '長野県', null, 36.3827785, 138.2710819, 'B', '寺院', '信濃国分寺（しなのこくぶんじ）は、長野県上田市国分(こくぶ)にある天台宗の寺院。本尊は薬師如来。'),
    ('蓮教寺', null, '愛知県', null, 35.1564805, 137.0119059, 'B', '寺院', '蓮教寺（れんきょうじ）は、愛知県名古屋市名東区高針四丁目にある真宗高田派の寺院である。山号は法雲山。'),
    ('二宮神社', null, '千葉県', null, 35.7018602, 140.05233, 'B', '神社', '二宮神社（にのみやじんじゃ）は、千葉県船橋市三山にある神社。式内社論社で、下総国二宮と伝える。'),
    ('玉林寺', null, '東京都', null, 35.7199778, 139.766985, 'B', '寺院', '玉林寺（ぎょくりんじ）は、東京都台東区にある曹洞宗の寺院。'),
    ('白神社', null, '広島県', null, 34.3903305, 132.4563479, 'B', '神社', '白神社（しらかみしゃ）は、広島市中区中町に鎮座する神社。市民から「しらかみさん」と称されて、親しまれている旧郷社。'),
    ('関帝廟', null, '神奈川県', null, 35.442453, 139.6452218, 'B', '寺院', '横浜関帝廟（よこはまかんていびょう）は、神奈川県横浜市中区の横浜中華街にある関帝廟。関帝（神格化された関羽）を祀っており、主に商売人の守り神として崇敬を集めている。'),
    ('桃太郎神社', null, '愛知県', null, 35.4052849, 136.9662459, 'B', '神社', '桃太郎神社（ももたろうじんじゃ）は、愛知県犬山市栗栖（くりす）にある神社。'),
    ('氷室神社', null, '奈良県', null, 34.6842972, 135.8378775, 'B', '神社', '氷室神社（ひむろじんじゃ）は、奈良県奈良市にある神社。式内小社（論社）、旧社格は村社。'),
    ('添御県坐 神社', null, '奈良県', null, 34.6875457, 135.7394746, 'B', '神社', '添御県坐神社（そうのみあがたにいますじんじゃ）は、奈良県奈良市三碓（みつがらす）三丁目にある神社である。式内大社論社。'),
    ('能仁寺', null, '埼玉県', null, 35.8605741, 139.3097449, 'B', '寺院', null),
    ('愛染院', null, '東京都', null, 35.753269, 139.6397255, 'B', '寺院', '練月山 愛染院 観音寺（れんげつさん あいぜんいん かんのんじ）は、東京都練馬区春日町四丁目にある真言宗豊山派の寺院。参道には、昭和15年に建てられた練馬大根碑がある。'),
    ('須賀神社', null, '東京都', '新宿区', 35.6853643, 139.7225902, 'B', '神社', null),
    ('第33番札所 雪渓寺', null, '高知県', '高知市', 33.5008563, 133.5431302, 'B', '寺院', null),
    ('清水寺', null, '大阪府', null, 34.6554476, 135.5116325, 'B', '寺院', null),
    ('小室浅間神社', null, '山梨県', null, 35.4948598, 138.8031488, 'B', '神社', '冨士山下宮小室浅間神社（ふじさんしもみやおむろせんげんじんじゃ）は、山梨県富士吉田市にある神社。旧社格は郷社で、現在は神社本庁の別表神社。'),
    ('海晏寺', null, '東京都', null, 35.6076846, 139.742459, 'B', '寺院', '海晏寺（かいあんじ）は、東京都品川区南品川五丁目にある単立寺院で、近年まで曹洞宗の寺院だった。
建長3年（1251年）開山。'),
    ('太宗寺', null, '東京都', '新宿区', 35.689693, 139.70923, 'B', '寺院', '太宗寺（たいそうじ）は、東京都新宿区新宿二丁目にある浄土宗の寺院である。山号は霞関山、院号は本覚院。'),
    ('十二社熊野神社', null, '東京都', null, 35.6902395, 139.688332, 'B', '神社', '熊野神社（くまのじんじゃ）は、東京都新宿区西新宿二丁目にある神社。花園神社と並んで新宿の鎮守社。'),
    ('品川寺', null, '東京都', null, 35.6095834, 139.7437744, 'B', '寺院', '品川寺（ほんせんじ）は、東京都品川区南品川三丁目にある真言宗醍醐派の寺院である。山号は海照山。'),
    ('景徳院', null, '山梨県', null, 35.6410545, 138.803545, 'B', '寺院', '景徳院（けいとくいん）は、山梨県甲州市にある曹洞宗の寺院。山号は天童山、本尊は釈迦如来。'),
    ('壺井八幡宮', null, '大阪府', null, 34.5308338, 135.6259351, 'B', '神社', '壺井八幡宮（つぼいはちまんぐう）は、大阪府羽曳野市壺井にある神社。旧社格は村社。'),
    ('浄光明寺', null, '神奈川県', null, 35.3264324, 139.5511764, 'B', '寺院', '浄光明寺（じょうこうみょうじ）は、神奈川県鎌倉市扇ガ谷（おうぎがやつ）にある真言宗泉涌寺派の寺院。山号は泉谷山（せんこくざん）。'),
    ('許波多神社', null, '京都府', null, 34.9267627, 135.7985618, 'B', '神社', null),
    ('杵築神社', null, '東京都', null, 35.6998027, 139.5464574, 'B', '神社', '杵築大社（きづきたいしゃ）は、東京都武蔵野市境南町にある神社。大國主大神（だいこく）と事代主大神（えびす）の二神を祀っており、武蔵野吉祥七福神の寺社の一つである。'),
    ('等彌神社', null, '奈良県', null, 34.5062035, 135.8540974, 'B', '神社', null),
    ('都波岐神社・奈加等神社', null, '三重県', null, 34.9014862, 136.6012788, 'B', '神社', null),
    ('大仙院', null, '京都府', null, 35.0445842, 135.7458169, 'B', '寺院', '大仙院（だいせんいん）は、京都府京都市北区にある臨済宗の大徳寺内にある塔頭寺院。'),
    ('石都々古和気神社', null, '福島県', null, 37.1450494, 140.4510393, 'B', '神社', null),
    ('第24番札所 最御崎寺', null, '高知県', '室戸市', 33.2490846, 134.1759439, 'B', '寺院', '最御崎寺（ほつみさきじ）は、高知県室戸市室戸岬町にある真言宗豊山派の寺院。室戸山（むろとざん）、明星院（みょうじょういん）と号す。'),
    ('日比谷神社', null, '東京都', null, 35.6633987, 139.7582964, 'B', '神社', '日比谷神社（ひびやじんじゃ）は、東京都港区東新橋にある神社である。
豊受大神（稲荷神）・祓戸四柱大神（瀬織津比売大神・速開都比売大神・気吹戸主大神・速佐須良比売大神）を祀る。'),
    ('普門寺', null, '大阪府', null, 34.830158, 135.5928637, 'B', '寺院', '普門寺（ふもんじ）は、大阪府高槻市富田町にある臨済宗妙心寺派の寺院。山号は慈雲山。'),
    ('明王院', null, '広島県', null, 34.4784197, 133.3463352, 'B', '寺院', '明王院（みょうおういん）は、広島県福山市草戸町にある真言宗大覚寺派の仏教寺院である。空海が開基と伝わる。'),
    ('井草八幡宮', null, '東京都', '杉並区', 35.7159432, 139.5963728, 'B', '神社', '井草八幡宮（いぐさはちまんぐう）は、東京都杉並区善福寺にある八幡神社である。別表神社。'),
    ('了法寺', null, '東京都', null, 35.6605838, 139.3161885, 'B', '寺院', '了法寺（りょうほうじ）は、東京都八王子市日吉町に所在する寺院。宗派は日蓮宗。'),
    ('興正寺', null, '愛知県', null, 35.1401865, 136.9624637, 'B', '寺院', null),
    ('元慶寺', null, '京都府', '京都市', 34.9886162, 135.8011578, 'B', '寺院', '元慶寺（がんけいじ、古くは「がんぎょうじ」）は、京都市山科区北花山河原町にある天台宗の寺院。山号は華頂山。'),
    ('願泉寺', null, '大阪府', null, 34.448581, 135.3574826, 'B', '寺院', null),
    ('高座結御子神社', null, '愛知県', null, 35.1354087, 136.9044778, 'B', '神社', null),
    ('相模国分寺', null, '神奈川県', '海老名市', 35.4526733, 139.399237, 'B', '寺院', '相模国分寺（さがみこくぶんじ）は、神奈川県海老名市国分にある高野山真言宗の寺院。山号は東光山。'),
    ('大阪護國神社', null, '大阪府', null, 34.6098522, 135.4739303, 'B', '神社', '大阪護國神社（おおさかごこくじんじゃ）は、大阪市住之江区にある神社（護国神社）。'),
    ('金櫻神社', null, '山梨県', null, 35.7694402, 138.5561097, 'B', '神社', null),
    ('大谷磨崖仏', null, '栃木県', null, 36.5967838, 139.8208345, 'B', '寺院', '大谷寺（おおやじ）は、栃木県宇都宮市大谷町にある天台宗の寺院である。山号は天開山。'),
    ('阿伎留神社', null, '東京都', null, 35.725325, 139.2227717, 'B', '神社', null),
    ('第31番札所 竹林寺', null, '高知県', '高知市', 33.5464894, 133.5766731, 'B', '寺院', null),
    ('慈眼寺', null, '東京都', null, 35.7397042, 139.7359332, 'B', '寺院', '慈眼寺（じげんじ）は、東京都豊島区にある日蓮宗の寺院。'),
    ('敏馬神社', null, '兵庫県', null, 34.7033214, 135.2188106, 'B', '神社', '敏馬神社（みぬめじんじゃ）は、神戸市灘区岩屋中町にある神社。式内社で、旧社格は県社。'),
    ('岩船寺', null, '京都府', null, 34.7198554, 135.8860168, 'B', '寺院', '岩船寺（がんせんじ）は、京都府木津川市加茂町岩船にある真言律宗の寺院。山号は高雄山（こうゆうざん）。'),
    ('大善寺', null, '山梨県', null, 35.6559111, 138.7431425, 'B', '寺院', '大善寺（だいぜんじ）は、山梨県甲州市勝沼町にある仏教寺院。宗派は真言宗智山派、山号は柏尾山、本尊は薬師如来である。'),
    ('鏡作坐天照御魂神社', null, '奈良県', null, 34.5610813, 135.7939861, 'B', '神社', null),
    ('東照宮', null, '広島県', null, 34.403216, 132.4756089, 'B', '神社', '広島東照宮（ひろしまとうしょうぐう）は、広島県広島市東区の二葉山山麓の約300 ｍの高台にある東照宮で、尾長東照宮ともよばれている。'),
    ('第78番札所 郷照寺', null, '香川県', null, 34.3066903, 133.8242112, 'B', '寺院', null),
    ('津観音', null, '三重県', null, 34.720671, 136.5131952, 'B', '寺院', '津観音（つかんのん）は、三重県津市大門にある寺院。正式な寺号は恵日山観音寺大宝院（えにちざんかんのんじだいほういん）であり、宗派は真言宗醍醐派の別格本山。'),
    ('倭文神社', null, '鳥取県', null, 35.4896252, 133.9031175, 'B', '神社', '倭文神社（しとりじんじゃ/しずりじんじゃ）は、鳥取県東伯郡湯梨浜町大字宮内にある神社。式内社、伯耆国一宮。'),
    ('賣太神社', null, '奈良県', null, 34.6392857, 135.7966605, 'B', '神社', null),
    ('妙立寺(忍者寺)', null, '石川県', 'Nomachi, Kanazawa, Ishikawa', 36.5553573, 136.6490285, 'B', '寺院', '妙立寺（みょうりゅうじ）とは、石川県金沢市にある日蓮宗の寺院。山号は正久山。'),
    ('尾張戸神社', null, '愛知県', null, 35.2559774, 137.0530299, 'B', '神社', '尾張戸神社（おわりべじんじゃ）は、愛知県名古屋市守山区および瀬戸市にある神社。『延喜式神名帳』の尾張国山田郡「尾張戸神社」に比定されている。'),
    ('法輪寺', null, '京都府', null, 35.010001, 135.677215, 'B', '寺院', '法輪寺（ほうりんじ）は、京都市西京区嵐山虚空蔵山町にある真言宗五智教団の寺院。山号は智福山。'),
    ('常寂光寺', null, '京都府', null, 35.01964, 135.6685724, 'B', '寺院', '常寂光寺（じょうじゃっこうじ）は、京都市右京区嵯峨小倉山小倉町にある日蓮宗の寺院。山号は小倉山。'),
    ('熊野大社', null, '山形県', null, 38.0779556, 140.1372481, 'B', '神社', '熊野神社（くまのじんじゃ）は、山形県南陽市にある神社である。旧社格は県社。'),
    ('伊豫豆比古命神社', null, '愛媛県', null, 33.8092853, 132.7707522, 'B', '神社', '伊豫豆比古命神社（いよずひこのみことじんじゃ）は、愛媛県松山市居相町にある神社。式内社、旧社格は県社。'),
    ('今熊野観音寺', null, '京都府', null, 34.9798185, 135.781121, 'B', '寺院', '今熊野観音寺（いまくまのかんのんじ）は、京都市東山区泉涌寺山内町にある真言宗泉涌寺派の寺院。総本山泉涌寺の塔頭。'),
    ('壇林寺', null, '京都府', null, 35.0237604, 135.6676877, 'B', '寺院', '檀林寺（だんりんじ）は、平安時代初期に嵯峨天皇の皇后・橘嘉智子が唐の僧侶・義空を招いて京都の嵯峨に開山させた禅宗の尼寺。
今日では廃絶している。'),
    ('福徳神社', null, '東京都', null, 35.6872213, 139.7744198, 'B', '神社', null),
    ('萬昌院功運寺', null, '東京都', null, 35.7124759, 139.6787211, 'B', '寺院', null),
    ('不退寺', null, '奈良県', null, 34.6948041, 135.8124863, 'B', '寺院', '不退寺（ふたいじ）は、奈良県奈良市法蓮町にある真言律宗の寺院。山号は金龍山。'),
    ('鷲林寺', null, '兵庫県', null, 34.7754497, 135.3083501, 'B', '寺院', null),
    ('唐沢山神社', null, '栃木県', null, 36.3538136, 139.600758, 'B', '神社', '唐沢山神社（からさわやまじんじゃ）は、栃木県佐野市の唐沢山山頂にある神社。藤原秀郷を祀る。'),
    ('清浄華院', null, '京都府', null, 35.025339, 135.7684081, 'B', '寺院', '清浄華院（しょうじょうけいん）は、京都市上京区にある浄土宗の大本山の寺院。呼称は院号のみで、山号・寺号はない。'),
    ('皇大神社', null, '京都府', null, 35.4292311, 135.1546594, 'B', '神社', null),
