    ('杉本寺', null, '神奈川県', '鎌倉市', 35.3226286, 139.5674413, 'B', '寺院', '杉本寺（すぎもとでら）は、神奈川県鎌倉市二階堂にある天台宗の寺院。山号は大蔵山。'),
    ('資福寺', null, '宮城県', null, 38.282936, 140.8602846, 'B', '寺院', null),
    ('武雄神社', null, '佐賀県', null, 33.1883674, 130.0210925, 'B', '神社', '武雄神社（たけおじんじゃ）は、佐賀県武雄市武雄町の御船山の山麓にある神社。樹齢3000年ともいわれる御神木の大楠があることでも知られる。'),
    ('真如寺', null, '京都府', null, 35.0309012, 135.7251849, 'B', '寺院', '真如寺（しんにょじ）は、京都市北区等持院北町にある臨済宗相国寺派の寺院。大本山相国寺の山外塔頭。'),
    ('本成寺', null, '新潟県', null, 37.622725, 138.9449872, 'B', '寺院', '本成寺（ほんじょうじ）は、新潟県三条市西本成寺にある、法華宗陣門流の総本山。山号は長久山（ちょうきゅうさん）。'),
    ('五流尊瀧院', null, '岡山県', null, 34.5367999, 133.818862, 'B', '寺院', '五流尊瀧院（ごりゅうそんりゅういん）は岡山県倉敷市林に所在する修験道の寺院。本尊は十一面観音。'),
    ('堀越神社', null, '大阪府', null, 34.6514679, 135.5132883, 'B', '神社', '堀越神社（ほりこしじんじゃ）は、大阪市天王寺区茶臼山町にある神社。旧社格は村社。'),
    ('第84番札所 屋島寺', null, '香川県', '高松市', 34.357386, 134.1011415, 'B', '寺院', '屋島寺（やしまじ）は、屋島の南嶺山上（香川県高松市屋島東町）にある真言宗御室派の寺院。南面山（なんめんざん）、千光院（せんこういん）と号す。'),
    ('蚶満寺', null, '秋田県', null, 39.2162489, 139.9029442, 'B', '寺院', null),
    ('安養寺', null, '京都府', null, 35.0038142, 135.7844862, 'B', '寺院', '安養寺（あんようじ）は、京都市東山区にある時宗の寺院。山号は慈円山。'),
    ('浦嶋神社', null, '京都府', null, 35.7289933, 135.2578485, 'B', '神社', '浦嶋神社（うらしまじんじゃ）は、京都府与謝郡伊根町本庄浜にある神社。旧社格は郷社。'),
    ('金峯神社', null, '奈良県', null, 34.3427486, 135.8818934, 'B', '神社', null),
    ('飯高寺', null, '千葉県', null, 35.7444127, 140.5293346, 'B', '寺院', null),
    ('本法寺', null, '京都府', null, 35.0350543, 135.7522199, 'B', '寺院', '本法寺（ほんぽうじ）は、京都市上京区本法寺前町にある日蓮宗の本山（由緒寺院）の寺院。山号は叡昌山。'),
    ('大乗寺', null, '石川県', null, 36.532427, 136.6591413, 'B', '寺院', '大乗寺（だいじょうじ、大乘寺）は、石川県金沢市長坂町にある曹洞宗の寺院。山号は東香山、椙樹林、古くは金獅峯。'),
    ('善福寺', null, '東京都', null, 35.7182061, 139.5912218, 'B', '寺院', '善福寺（ぜんぷくじ）は、東京都杉並区善福寺にある曹洞宗の寺院。
なお、当寺の名称は、従来からの地名の善福寺に基づき改称した結果、善福寺となった。'),
    ('玉敷神社', null, '埼玉県', '加須市　騎西522', 36.10734, 139.5697264, 'B', '神社', '玉敷神社（たましきじんじゃ）は、埼玉県加須市騎西にある神社。式内社で、旧社格は県社。'),
    ('真間山弘法寺', null, '千葉県', '市川市', 35.7399649, 139.9081634, 'B', '寺院', '弘法寺（ぐほうじ）は、千葉県市川市真間四丁目にある日蓮宗の本山（由緒寺院）。山号は真間山。'),
    ('沖宮', null, '沖縄県', '那覇市', 26.202662, 127.6771053, 'B', '神社', '沖宮（おきのぐう）は沖縄県那覇市にある神社。琉球八社の一つであるが、近代社格制度では社格を与えられておらず、神社本庁に属さない単立の神社である。'),
    ('長國寺', null, '東京都', null, 35.722999, 139.7920204, 'B', '寺院', null),
    ('穴澤天神社', null, '東京都', null, 35.6327598, 139.5221016, 'B', '神社', null),
