    ('最勝寺', null, '東京都', '世田谷区', 35.6448796, 139.6678821, 'B', '寺院', '教学院（きょうがくいん）は、東京都世田谷区太子堂四丁目にある天台宗の寺院。寛永寺の末寺の一つである。'),
    ('東口本宮冨士浅間神社', null, '静岡県', '小山町', 35.362946, 138.8638294, 'B', '神社', '東口本宮冨士浅間神社（ひがしぐちほんぐうふじせんげんじんじゃ）は、静岡県駿東郡小山町須走にある神社。旧社格は県社。'),
    ('河口浅間神社', null, '山梨県', null, 35.5310685, 138.7749964, 'B', '神社', null),
    ('圓徳院', null, '京都府', null, 35.0008054, 135.7795814, 'B', '寺院', '圓徳院（えんとくいん、常用漢字体：円徳院）は、京都市東山区にある臨済宗建仁寺派の寺院。高台寺の塔頭。'),
    ('柿本神社', null, '兵庫県', null, 34.6499784, 135.0016265, 'B', '神社', '柿本神社（かきのもとじんじゃ）は、兵庫県明石市人丸町にある神社。人丸山（人丸山公園）の頂上に鎮座するが、山名も当神社に因むものである。'),
    ('一言主神社', null, '茨城県', null, 36.0120733, 139.9273187, 'B', '神社', '一言主神社（ひとことぬしじんじゃ）は、茨城県常総市にある神社。一言明神（ひとことみょうじん）ともいう。'),
    ('宝泉院', null, '京都府', null, 35.121352, 135.8339989, 'B', '寺院', '宝泉院（ほうせんいん）は、京都市左京区大原勝林院町にある天台宗の寺院。大原寺勝林院の塔頭。'),
    ('平等寺', null, '京都府', null, 34.9994893, 135.7602802, 'B', '寺院', '平等寺（びょうどうじ）は、京都市下京区因幡堂町にある真言宗智山派の寺院。山号は福聚山。'),
    ('多奈波太神社', null, '愛知県', null, 35.1931476, 136.9056732, 'B', '神社', '多奈波太神社（たなばたじんじゃ）は、愛知県名古屋市北区金城四丁目に鎮座する神社。『延喜式神名帳』の尾張国山田郡「多奈波太神社」に比定されている。'),
    ('大依羅神社', null, '大阪府', null, 34.5948685, 135.5179394, 'B', '神社', '大依羅神社（おおよさみじんじゃ）は、大阪市住吉区にある神社。式内社（名神大社）で、旧社格は府社。'),
    ('第36番札所 青龍寺', null, '高知県', '土佐市', 33.4260649, 133.45095, 'B', '寺院', null),
    ('下谷神社', null, '東京都', null, 35.7108056, 139.7813235, 'B', '神社', '下谷神社（したやじんじゃ）は、東京都台東区東上野三丁目にある神社。大年神と日本武尊を祭っている。'),
    ('観福寺', null, '千葉県', null, 35.8809888, 140.4992005, 'B', '寺院', null),
    ('常楽寺', null, '神奈川県', null, 35.3482067, 139.5407424, 'B', '寺院', '常楽寺（じょうらくじ）は、神奈川県鎌倉市大船にある臨済宗建長寺派の寺院である。山号は粟船山（ぞくせんざん）。'),
    ('東林院', null, '京都府', null, 35.0230309, 135.7224821, 'B', '寺院', '東林院（とうりんいん）は、京都市右京区花園妙心寺町にある臨済宗妙心寺派の寺院。大本山妙心寺の塔頭。'),
    ('酒折宮', null, '山梨県', null, 35.6610301, 138.5965888, 'B', '神社', null),
    ('坂東16番 五徳山 水澤寺', null, '群馬県', null, 36.4793789, 138.9455274, 'B', '寺院', '水澤寺（みずさわでら）は、群馬県渋川市にある天台宗の寺院。山号は五徳山。'),
    ('開成山大神宮', null, '福島県', null, 37.3979737, 140.3532251, 'B', '神社', null),
    ('熊谷寺', null, '埼玉県', null, 36.1465845, 139.3829814, 'B', '寺院', '熊谷寺（ゆうこくじ）は、埼玉県熊谷市仲町にある浄土宗の寺院である。山号は蓮生山（れんせいざん）。'),
    ('慈光院', null, '奈良県', null, 34.6315567, 135.758621, 'B', '寺院', '慈光院（じこういん）は、奈良県大和郡山市小泉町にある臨済宗大徳寺派の寺院である。山号は円通山。'),
    ('本願寺', null, '京都府', null, 35.0269588, 135.6705803, 'B', '寺院', '本願寺（ほんがんじ）は、京都市右京区にある浄土真宗の寺院である。嵯峨本願寺とも。'),
    ('善知鳥神社', null, '青森県', null, 40.8266592, 140.7427279, 'B', '神社', '善知鳥神社（うとうじんじゃ）は、青森県青森市安方にある神社である。旧社格は県社。'),
    ('千光寺', null, '広島県', null, 34.4103649, 133.1986846, 'B', '寺院', '千光寺（せんこうじ）は、広島県尾道市東土堂町の千光寺公園内にある、仏教真言宗系の単立寺院。山号は大宝山（たいほうざん）。'),
    ('第03番札所 金泉寺', null, '徳島県', '板野町', 34.147453, 134.4685024, 'B', '寺院', null),
    ('粟田神社', null, '京都府', null, 35.0081887, 135.7849486, 'B', '神社', '粟田神社（あわたじんじゃ）は、京都市東山区粟田口鍛冶町にある神社。旧社格は府社。'),
    ('高砂神社', null, '兵庫県', null, 34.7437854, 134.8035942, 'B', '神社', null),
    ('千栗八幡宮', null, '佐賀県', null, 33.3314201, 130.4786568, 'B', '神社', '千栗八幡宮（ちりくはちまんぐう）は、佐賀県三養基郡みやき町にある神社。肥前一宮。'),
    ('機物神社', null, '大阪府', null, 34.794783, 135.6942868, 'B', '神社', '機物神社（はたものじんじゃ）は、大阪府交野市倉治にある神社。七夕に関する伝説で知られる神社である。'),
    ('願興寺', null, '岐阜県', null, 35.4303943, 137.1289936, 'B', '寺院', null),
    ('新倉富士浅間神社', null, '山梨県', '富士吉田市', 35.5003121, 138.8001336, 'B', '神社', '三國第一山新倉富士浅間神社（さんごくだいいちさん あらくらふじせんげんじんじゃ）は山梨県富士吉田市にある神社。旧社格は村社。'),
    ('瑞鳳寺', null, '宮城県', null, 38.2515084, 140.8666829, 'B', '寺院', null),
    ('亀戸水神宮', null, '東京都', '江東区', 35.7010875, 139.8314992, 'B', '神社', '亀戸水神社（かめいどすいじんしゃ）とは、東京都江東区亀戸にある神社。亀戸水神宮（かめいどすいじんぐう）、あるいは単に亀戸水神（かめいどすいじん）とも称される。'),
    ('別格15 箸蔵寺', null, '徳島県', '三好市', 34.0491841, 133.8418219, 'B', '寺院', '箸蔵寺（はしくらじ）は、徳島県三好市池田町州津にある真言宗御室派別格本山の寺院。宝珠山（ほうしゅざん）、真光院（しんこういん）と号す。'),
    ('第71番札所 弥谷寺', null, '香川県', null, 34.230281, 133.7241876, 'B', '寺院', '弥谷寺（いやだにじ）は、香川県三豊市三野町にある大本山の寺格を持つ真言宗善通寺派の寺院。剣五山 （けんござん）、千手院（せんじゅいん）と号す。'),
    ('桃巌寺', null, '愛知県', null, 35.161062, 136.9646536, 'B', '寺院', '桃巖禪寺、桃巌禪寺（とうがんぜんじ）、桃巌寺（とうがんじ）は、愛知県名古屋市千種区四谷通にある曹洞宗の寺院。山号は泉龍山。'),
    ('向嶽寺', null, '山梨県', '甲州市', 35.7108854, 138.7224266, 'B', '寺院', '向嶽寺（こうがくじ）は、山梨県甲州市にある禅寺で臨済宗向嶽寺派の大本山。山号は塩山。'),
    ('金乗院(山口観音)', null, '埼玉県', null, 35.7687853, 139.414396, 'B', '寺院', null),
    ('筑紫神社', null, '福岡県', null, 33.4570984, 130.5428982, 'B', '神社', null),
    ('倭姬宮', null, '三重県', null, 34.4852112, 136.7233418, 'B', '神社', '倭姫宮（やまとひめのみや）は、三重県伊勢市楠部町にある神社。内宮（皇大神宮）の別宮である。'),
    ('羽田航空神社', null, '東京都', null, 35.5487477, 139.7844283, 'B', '神社', null),
    ('白山中居神社', null, '岐阜県', null, 35.9921241, 136.7689753, 'B', '神社', null),
    ('総願寺', null, '埼玉県', null, 36.1356777, 139.5853946, 'B', '寺院', null),
    ('月輪寺', null, '京都府', null, 35.0584098, 135.6451531, 'B', '寺院', '月輪寺（つきのわでら）は、京都市右京区嵯峨清滝月ノ輪町にある天台宗の寺院。山号は鎌倉山（かまくらやま、けんそうざん）。'),
    ('天徳寺', null, '東京都', null, 35.6641968, 139.747004, 'B', '寺院', '天徳寺（てんとくじ）は、東京都港区にある浄土宗の寺院。'),
    ('塩船観音寺', null, '東京都', null, 35.8046676, 139.2808225, 'B', '寺院', '塩船観音寺（しおふねかんのんじ）は、東京都青梅市塩船にある真言宗醍醐派の別格本山。山号は大悲山。'),
    ('相馬中村神社', null, '福島県', null, 37.797275, 140.913059, 'B', '神社', '相馬中村神社（そうまなかむらじんじゃ）は、福島県相馬市中村に立地する神社。別名は妙見中村神社（みょうけんなかむらじんじゃ）だが、中村神社と省略されることもある。'),
    ('妙成寺', null, '石川県', null, 36.9540632, 136.7766599, 'B', '寺院', '妙成寺（みょうじょうじ）は、石川県羽咋市滝谷町にある日蓮宗の寺院。山号は金栄山（きんえいざん）。'),
    ('宗忠神社', null, '京都府', null, 35.0228595, 135.7856978, 'B', '神社', '宗忠神社（むねただじんじゃ）は、黒住教の教祖である黒住宗忠を祀る神社である。京都および、黒住宗忠の生地で黒住教の本部のある岡山にある。'),
    ('本照寺', null, '大阪府', null, 34.830874, 135.5941694, 'B', '寺院', '本照寺（ほんしょうじ）は、大阪府高槻市富田町（とんだちょう）にある浄土真宗本願寺派の仏教寺院。富寿栄山（ふすえざん）あるいは富山と号し、富田御坊（とんだごぼう）ともいう。'),
    ('崇福寺', null, '岐阜県', null, 35.4432484, 136.7673257, 'B', '寺院', '崇福寺（そうふくじ）は、岐阜県岐阜市にある臨済宗妙心寺派の寺院である。山号は神護山。'),
    ('玉若酢命神社', null, '島根県', null, 36.2070502, 133.3128776, 'B', '神社', '玉若酢命神社（たまわかすみことじんじゃ/たまわかすのみことじんじゃ）は、島根県隠岐郡隠岐の島町下西にある神社。式内社で、旧社格は県社。'),
    ('龍角寺', null, '千葉県', null, 35.8331761, 140.2698394, 'B', '寺院', null),
    ('油日神社', null, '滋賀県', null, 34.886703, 136.2495738, 'B', '神社', '油日神社（あぶらひじんじゃ）は、滋賀県甲賀市甲賀町油日にある神社。国史見在社で旧社格は県社。'),
    ('観音', null, '千葉県', null, 35.7319462, 140.840608, 'B', '寺院', '円福寺（えんぷくじ）は、千葉県銚子市にある真言宗系単立の寺院。山号は飯沼山。'),
    ('子ノ権現天龍寺', null, '埼玉県', null, 35.907368, 139.1892395, 'B', '寺院', '子の権現 天龍寺（ねのごんげん てんりゅうじ）は埼玉県飯能市にある天台宗の寺院である。武蔵野三十三観音霊場32番札所。'),
    ('走水神社', null, '兵庫県', null, 34.6848218, 135.1814927, 'B', '神社', null),
    ('正伝寺', null, '京都府', null, 35.0622841, 135.738056, 'B', '寺院', '正伝寺（しょうでんじ）は、京都市北区にある臨済宗南禅寺派の寺院。山号は吉祥山。'),
    ('雷電神社', null, '群馬県', null, 36.227526, 139.6078042, 'B', '神社', null),
    ('宝鏡寺', null, '京都府', null, 35.034015, 135.7527593, 'B', '寺院', '宝鏡寺（ほうきょうじ）は、京都市上京区百々町にある臨済宗系単立の寺院（尼寺）。山号は西山（せいざん）。'),
    ('油山寺', null, '静岡県', null, 34.7855186, 137.9361726, 'B', '寺院', '油山寺（ゆさんじ）は、静岡県袋井市村松にある真言宗智山派の寺院。遠州三山の1つ。'),
    ('雲峰寺', null, '山梨県', null, 35.7393686, 138.8046698, 'B', '寺院', null),
    ('長浜神社', null, '大分県', '大分市', 33.2376383, 131.6161884, 'B', '神社', null),
    ('魚吹八幡神社', null, '兵庫県', null, 34.7963708, 134.5903096, 'B', '神社', null),
    ('妙蓮寺', null, '静岡県', null, 35.2691005, 138.5787021, 'B', '寺院', '下条妙蓮寺（しもじょうみょうれんじ）は、静岡県富士宮市にある日蓮正宗の本山格寺院である。山号は多宝富士山。'),
    ('駒込富士神社', null, '東京都', null, 35.7312141, 139.7511561, 'B', '神社', null),
    ('八街神社', null, '千葉県', '八街市', 35.6369735, 140.3191689, 'B', '寺院', '八街神社（やちまたじんじゃ）とは、千葉県八街市にある神社。'),
    ('第27番札所 神峯寺', null, '高知県', '安田町', 33.4675303, 133.9749882, 'B', '寺院', null),
    ('源九郎稲荷神社', null, '奈良県', null, 34.6456287, 135.7855631, 'B', '神社', '源九郎稲荷神社（げんくろういなりじんじゃ）は、奈良県大和郡山市洞泉寺町にある神社。源九郎狐や綿帽子を買った狐の伝説で有名である。'),
    ('大谷地神社', null, '北海道', null, 43.0264936, 141.4474905, 'B', '神社', '大谷地神社（おおやちじんじゃ）は北海道札幌市厚別区大谷地西2丁目2番1号にある神社。旧社格は無格社。'),
    ('函館八幡宮', null, '北海道', '函館市', 41.753536, 140.7106751, 'B', '神社', '函館八幡宮（はこだてはちまんぐう）は、北海道函館市にある神社である。旧社格は国幣中社で現在は神社本庁の別表神社。'),
    ('諏訪神社', null, '東京都', null, 35.6948813, 139.4059966, 'B', '神社', null),
    ('出雲大社相模分祠', null, '神奈川県', null, 35.3709553, 139.2094479, 'B', '神社', '出雲大社相模分祠（いづもおおやしろ／たいしゃ さがみぶんし）は、神奈川県秦野市平沢にある神社。名の通り出雲大社の分社である。'),
    ('天徳院', null, '石川県', null, 36.5514901, 136.6768907, 'B', '寺院', '天徳院（てんとくいん）は、石川県金沢市小立野にある曹洞宗の寺院。山号は金龍山（きんりゅうざん）。'),
    ('霊雲寺', null, '東京都', '文京区', 35.7055939, 139.7656873, 'B', '寺院', null),
    ('本山寺', null, '香川県', null, 34.1397276, 133.6939426, 'B', '寺院', '本山寺（もとやまじ）は香川県三豊市にある高野山真言宗の寺院。七宝山（しっぽうざん）、持宝院（じほういん）と号す。'),
    ('成子天神社', null, '東京都', null, 35.6957685, 139.69221, 'B', '神社', '成子天神社（なるこてんじんしゃ）は、東京都新宿区西新宿にある神社。祭神は菅原道真（天満大自在天神）。'),
    ('高来神社', null, '神奈川県', null, 35.3220972, 139.3247207, 'B', '神社', null),
    ('井伊谷宮', null, '静岡県', null, 34.8292008, 137.6679133, 'B', '神社', '井伊谷宮（いいのやぐう）は、静岡県浜松市浜名区引佐町井伊谷にある神社である。旧社格は官幣中社。'),
    ('氷川神社', null, '東京都', null, 35.6550739, 139.7108213, 'B', '神社', '氷川神社（ひかわじんじゃ）は、東京都渋谷区東二丁目にある神社。地名を冠して渋谷氷川神社（しぶやひかわじんじゃ）とも称される。'),
    ('久米田寺', null, '大阪府', '岸和田市池尻町', 34.4593281, 135.4117412, 'B', '寺院', '久米田寺（くめだでら）は、大阪府岸和田市にある高野山真言宗の準別格本山の寺院。山号は龍臥山。'),
    ('第40番札所 観自在寺', null, '愛媛県', '愛南町', 32.9643398, 132.5640423, 'B', '寺院', null),
    ('鶴見神社', null, '神奈川県', null, 35.5109656, 139.6773296, 'B', '神社', null),
    ('児玉神社', null, '神奈川県', null, 35.3006461, 139.4809925, 'B', '神社', '児玉神社（こだまじんじゃ）は、神奈川県藤沢市江の島にある日露戦争で活躍した明治時代の軍人・児玉源太郎を祀った神社である。'),
    ('菊池神社', null, '熊本県', null, 32.987829, 130.8160512, 'B', '神社', null),
    ('岡崎神社', null, '京都府', null, 35.0172931, 135.7889383, 'B', '神社', '岡崎神社（おかざきじんじゃ）は、京都市左京区岡崎東天王町にある神社。別名「東天王」ともいわれる。'),
    ('第65番札所 三角寺', null, '愛媛県', null, 33.9673725, 133.5866363, 'B', '寺院', '三角寺（さんかくじ）は愛媛県四国中央市金田町三角寺75にある高野山真言宗の寺院。由霊山（ゆれいざん）、慈尊院（じそんいん）と号す。'),
    ('柳森神社', null, '東京都', null, 35.6967336, 139.7734568, 'B', '神社', '柳森神社（やなぎもりじんじゃ）は、東京都千代田区神田須田町にある神社。通称は倉稲魂大神。'),
    ('高源院', null, '東京都', null, 35.6803887, 139.5946402, 'B', '寺院', null),
    ('高牟神社', null, '愛知県', null, 35.1692522, 136.9324109, 'B', '神社', null),
    ('白峰宮', null, '香川県', null, 34.3109643, 133.882525, 'B', '神社', '白峰宮（しろみねぐう）は、香川県坂出市に鎮座する神社で、明治維新以前は崇徳天皇社であった。明ノ宮（あかりのみや）とも呼ばれる。'),
    ('山住神社', null, '静岡県', null, 35.1351436, 137.9141518, 'B', '神社', '山住神社（やまずみじんじゃ）は、静岡県浜松市天竜区水窪町山住山に鎮座する神社である。旧社格は県社。'),
    ('神戸護国神社', null, '兵庫県', null, 34.7216973, 135.2248258, 'B', '神社', '兵庫縣神戸護國神社（ひょうごけんこうべごこくじんじゃ）は、兵庫県神戸市灘区篠原北町にある神社（護国神社）である。兵庫県東部（丹波・摂津・淡路）14市出身の英霊53,257柱を祀る。'),
    ('瑞峯院', null, '京都府', null, 35.0421666, 135.7454214, 'B', '寺院', '瑞峯院（ずいほういん）は、京都市北区紫野大徳寺町にある臨済宗大徳寺派の寺院。大本山大徳寺の塔頭。'),
    ('光悦寺', null, '京都府', null, 35.0535234, 135.7301872, 'B', '寺院', '光悦寺（こうえつじ）は、京都市北区鷹峯光悦町にある日蓮宗の寺院。山号は大虚山。'),
    ('玉蔵院', null, '埼玉県', null, 35.8590212, 139.6520785, 'B', '寺院', '玉蔵院（ぎょくぞういん）は、埼玉県さいたま市浦和区にある真言宗豊山派の寺院。山号は宝珠山。'),
    ('上品蓮台寺', null, '京都府', null, 35.0382928, 135.7389189, 'B', '寺院', '上品蓮台寺（じょうぼんれんだいじ）は、京都市北区紫野十二坊町（蓮台野の附近）にある真言宗智山派の寺院。山号は蓮華金宝山。'),
    ('洲崎神社', null, '愛知県', null, 35.1631086, 136.893041, 'B', '神社', '洲崎神社（すさきじんじゃ）は、愛知県名古屋市中区栄1丁目にある神社。社格は旧郷社。'),
    ('鉄舟寺', null, '静岡県', null, 34.9926884, 138.4830443, 'B', '寺院', null),
    ('三津寺', null, '大阪府', null, 34.6705645, 135.5007063, 'B', '寺院', '三津寺（みつてら）は、大阪市中央区心斎橋筋にある真言宗御室派の準別格本山の寺院。山号は七宝山。'),
    ('国分寺', null, '新潟県', null, 37.168556, 138.2248871, 'B', '寺院', '五智国分寺（ごちこくぶんじ）は、新潟県上越市五智にある天台宗の寺院。山号は安国山。'),
    ('芳徳禅寺', null, '奈良県', null, 34.7316443, 135.95388, 'B', '寺院', null),
    ('養源寺', null, '東京都', null, 35.7262053, 139.756144, 'B', '寺院', null),
    ('仙波東照宮', null, '埼玉県', null, 35.9166164, 139.4897556, 'B', '神社', '仙波東照宮（せんばとうしょうぐう）は、埼玉県川越市小仙波町にある神社（東照宮）。日光・久能山と並ぶ日本三大東照宮の1つ。'),
    ('豊受大神社', null, '京都府', null, 35.4020152, 135.1505081, 'B', '神社', null),
    ('第37番札所 岩本寺', null, '高知県', '四万十町', 33.2080031, 133.1346448, 'B', '寺院', '岩本寺（いわもとじ）は、高知県高岡郡四万十町にある真言宗智山派の寺院。藤井山（ふじいざん）、五智院（ごちいん）と号す。'),
    ('熊野神社', null, '京都府', null, 35.0177095, 135.7780435, 'B', '神社', null),
    ('櫻井神社', null, '大阪府', null, 34.4854068, 135.5062146, 'B', '神社', '桜井神社（さくらいじんじゃ、櫻井神社）は、大阪府堺市南区片蔵にある神社。式内社で、旧社格は府社。'),
    ('松戸神社', null, '千葉県', '松戸市', 35.7806157, 139.8979915, 'B', '神社', '松戸神社（まつどじんじゃ）は、千葉県松戸市松戸1457番地にある神社である。寛永3年（1626年）の創建とされ、松戸市の総鎮守とされている。'),
    ('猪名野神社', null, '兵庫県', null, 34.7850488, 135.4151758, 'B', '神社', '猪名野神社（いなのじんじゃ）は、兵庫県伊丹市宮ノ前にある神社。戦国時代には有岡城の総構えの北端に位置し、「岸の砦」が置かれていた場所にある。'),
    ('可成寺', null, '岐阜県', null, 35.4545851, 137.0907537, 'B', '寺院', '可成寺（かじょうじ）は、岐阜県可児市兼山にある臨済宗妙心寺派の寺院。山号は大龍山。'),
    ('久渡寺', null, '青森県', null, 40.5398578, 140.4292452, 'B', '寺院', '久渡寺（くどじ）は、青森県弘前市坂元に所在する真言宗智山派寺院。山号は護国山。'),
    ('弥栄神社', null, '長野県', null, 36.6597219, 138.1866675, 'B', '神社', '弥栄神社（やさかじんじゃ）は、長野県長野市上西之門町にある神社。'),
    ('安仁神社', null, '岡山県', null, 34.6102989, 134.0960041, 'B', '神社', '安仁神社（あにじんじゃ）は、岡山県岡山市東区西大寺にある神社。式内社（名神大社）、備前国元一宮。'),
    ('鹿王院', null, '京都府', null, 35.0161484, 135.6844287, 'B', '寺院', null),
    ('柴田神社', null, '福井県', null, 36.060291, 136.2195004, 'B', '神社', '柴田神社（しばたじんじゃ）は、福井県福井市にある神社である。戦国時代の武将・柴田勝家を主祭神とし、妻の市を配祀する。'),
    ('関蝉丸神社下社', null, '滋賀県', null, 35.0027662, 135.8590588, 'B', '神社', null),
    ('最勝院', null, '青森県', null, 40.5966459, 140.4686501, 'B', '寺院', '最勝院（さいしょういん）は、青森県弘前市銅屋町にある真言宗智山派の寺院。山号は金剛山、寺号は光明寺。'),
    ('七寶寺', null, '大阪府', null, 34.9857437, 135.4658105, 'B', '寺院', '七宝寺（ひちほうじ）は、大阪府豊能郡能勢町の妙見山に位置する日蓮宗の寺院である。山号は七面山。'),
    ('櫻山神社', null, '岩手県', null, 39.7015131, 141.1516719, 'B', '神社', '櫻山神社（さくらやまじんじゃ）は、岩手県盛岡市に鎮座する神社である。'),
    ('徳大寺', null, '東京都', '台東区', 35.7086114, 139.7745099, 'B', '寺院', '徳大寺（とくだいじ）は、東京都台東区上野4丁目アメヤ横丁のほど近くにある日蓮宗の寺院。山号は妙宣山。'),
    ('花山院 菩提寺', null, '兵庫県', null, 34.940272, 135.2406042, 'B', '寺院', null),
    ('黄梅院', null, '京都府', null, 35.0415206, 135.7460125, 'B', '寺院', null),
    ('丹生官省符神社', null, '和歌山県', null, 34.2585692, 135.5150043, 'B', '神社', '丹生官省符神社（にうかんしょうぶじんじゃ）は、和歌山県伊都郡九度山町慈尊院にある神社。旧社格は郷社。'),
    ('常在寺', null, '岐阜県', null, 35.4321671, 136.7707536, 'B', '寺院', '常在寺（じょうざいじ）は、岐阜県岐阜市にある日蓮宗京都妙覚寺の旧末寺である。正式名は、鷲林山常在寺（しゅうりんざんじょうざいじ）。'),
    ('某神社', null, '新潟県', null, 37.7058812, 138.8271226, 'B', '神社', '彌彦神社の境内末社である某神社（ぼうじんじゃ）は、彌彦神社の境内にある祭神が不明の神社。祭神の名前が分からないため、某神社と呼ばれている。'),
    ('狸谷山不動院', null, '京都府', null, 35.0411881, 135.8019778, 'B', '寺院', '狸谷山不動院（たぬきだにさんふどういん）は、京都市左京区一乗寺にある真言宗修験道の大本山の寺院。山号は狸谷山。'),
    ('眞浄寺', null, '東京都', null, 35.7218516, 139.7566283, 'B', '寺院', null),
    ('十輪寺', null, '京都府', '京都市', 34.9442642, 135.6569727, 'B', '寺院', '十輪寺（じゅうりんじ）は、京都市西京区大原野小塩町にある天台宗の寺院。山号は小塩山（おしおざん）。'),
    ('勝願寺', null, '埼玉県', null, 36.0556229, 139.5143134, 'B', '寺院', '勝願寺（しょうがんじ）は、埼玉県鴻巣市本町8丁目にある浄土宗の寺院である。
浄土宗の関東十八檀林の1つであり、号は天照山良忠院。'),
    ('恵心院', null, '京都府', null, 34.89029, 135.811151, 'B', '寺院', '恵心院（えしんいん）は、京都府宇治市にある真言宗智山派の寺院。山号は朝日山。'),
    ('由良比女神社', null, '島根県', null, 36.0921889, 132.9877304, 'B', '神社', '由良比女神社（ゆらひめじんじゃ）は、島根県隠岐郡西ノ島町浦郷にある神社。式内社（名神大社）、隠岐国一宮で、旧社格は郷社。'),
    ('松蔭寺', null, '静岡県', '沼津市', 35.1234958, 138.8000452, 'B', '寺院', '松蔭寺（しょういんじ）は、静岡県沼津市原にある臨済宗系の寺院。往時の東海道原宿東町に当たり、白隠慧鶴所縁の寺として知られ、白隠さんの名前で親しまれている。'),
    ('第29番札所 土佐国分寺', null, '高知県', '香南市', 33.5987846, 133.6404629, 'B', '寺院', '土佐国分寺（とさ こくぶんじ）は高知県南国市にある真言宗智山派の寺院。摩尼山（まにざん）、宝蔵院（ほうぞういん）と号す。'),
    ('医王寺', null, '福島県', null, 37.822642, 140.4400074, 'B', '寺院', '医王寺（いおうじ）は、福島県福島市にある真言宗の寺院で、山号は瑠璃光山。中世初期に信夫郡を支配した佐藤氏の菩提寺。'),
    ('筑土八幡神社', null, '東京都', null, 35.704155, 139.7404247, 'B', '神社', null),
    ('吉田神社', null, '茨城県', null, 36.3617832, 140.4823559, 'B', '神社', '吉田神社（よしだじんじゃ）は、茨城県水戸市宮内町にある神社。式内社（名神大社）、常陸国三宮で、旧社格は県社。'),
    ('三瀧寺', null, '広島県', null, 34.4199827, 132.4382919, 'B', '寺院', '三瀧寺（みたきでら）は広島県広島市西区の三滝山（宗箇山）の中腹にある高野山真言宗の寺院。三滝寺とも。'),
    ('菅原神社', null, '東京都', null, 35.5594664, 139.4476426, 'B', '神社', null),
    ('影向寺', null, '神奈川県', null, 35.5784754, 139.6188348, 'B', '寺院', '影向寺（ようごうじ）は、神奈川県川崎市宮前区野川本町三丁目にある天台宗の寺院。本尊は薬師如来である。'),
    ('名和神社', null, '鳥取県', null, 35.5044263, 133.4950688, 'B', '神社', '名和神社（なわじんじゃ）は、鳥取県西伯郡大山町（旧名和町）にある神社で、名和長年を祭る。旧社格は別格官幣社。'),
    ('乗泉寺', null, '東京都', null, 35.6532311, 139.7018469, 'B', '寺院', '乗泉寺（じょうせんじ）は、東京都渋谷区鶯谷町にある本門佛立宗の寺院。山号は妙証山。'),
    ('日向薬師', null, '神奈川県', '伊勢原市', 35.4396198, 139.2749946, 'B', '寺院', '日向薬師（ひなたやくし）は、神奈川県伊勢原市日向（ひなた）にある高野山真言宗の寺院。本尊は薬師三尊。'),
    ('正暦寺', null, '奈良県', '奈良市', 34.6446963, 135.8685415, 'B', '寺院', '正暦寺（しょうりゃくじ）は、奈良県奈良市菩提山町にある菩提山真言宗の大本山の寺院。山号は菩提山。'),
    ('易行院', null, '東京都', null, 35.803448, 139.7886231, 'B', '寺院', '易行院（いぎょういん）は、東京都足立区にある浄土宗の寺院。'),
    ('由岐神社', null, '京都府', null, 35.1162396, 135.7714962, 'B', '神社', '由岐神社（ゆきじんじゃ）は、京都市左京区鞍馬本町にある神社。通称靫明神（ゆきみょうじん）。'),
    ('宮城県護国神社', null, '宮城県', null, 38.2524883, 140.8555168, 'B', '神社', '宮城縣護國神社（みやぎけんごこくじんじゃ）は、宮城県仙台市青葉区川内にある神社（護国神社）である。青葉山の仙台城（青葉城）本丸跡に創建された。'),
    ('太田姫稲荷神社', null, '東京都', '千代田区', 35.6964298, 139.7630784, 'B', '神社', '太田姫稲荷神社（おおたひめいなりじんじゃ）は、東京都千代田区にある神社である。旧社格は村社。'),
    ('冠櫻神社', null, '香川県', null, 34.2383932, 134.0118969, 'B', '神社', '冠纓神社（かんえいじんじゃ）は、香川県高松市香南町由佐にある神社。別名は「かむろ八幡宮」で、香南町の氏神として親しまれ、縁結び神社としても知られる。'),
    ('安養院', null, '神奈川県', null, 35.3140697, 139.5554188, 'B', '寺院', '安養院（あんよういん）は、神奈川県鎌倉市大町にある浄土宗の寺院。山号は祇園山。'),
    ('名古屋晴明神社', null, '愛知県', '名古屋市', 35.184515, 136.9500467, 'B', '神社', '名古屋晴明神社（なごやせいめいじんじゃ）は愛知県名古屋市千種区清明山1-6にある、陰陽師安倍晴明を祀る神社。'),
    ('勝林院', null, '京都府', null, 35.1211985, 135.8345446, 'B', '寺院', '勝林院（しょうりんいん）は、京都市左京区大原勝林院町にある天台宗の寺院。山号は魚山。'),
    ('光禅寺', null, '富山県', null, 36.8577546, 136.9861344, 'B', '寺院', '光禪寺（こうぜんじ）は、日本の富山県氷見市に所在する曹洞宗の寺院である。山号は海慧山（かいけいざん）。'),
    ('十条富士神社', null, '東京都', null, 35.7628621, 139.7254007, 'B', '神社', '十条冨士神社（じゅうじょうふじじんじゃ）は東京都北区の神社。'),
    ('八幡神社', null, '東京都', null, 35.661546, 139.7427542, 'B', '神社', '八幡神社（はちまんじんじゃ）は、東京都港区虎ノ門にある神社である。通常は他との区別の都合上、旧地名を冠して、西久保八幡神社（にしくぼはちまんじんじゃ）と称される。'),
    ('天龍寺', null, '東京都', '新宿区', 35.6887408, 139.7042007, 'B', '寺院', '天龍寺（てんりゅうじ、天竜寺とも）は、東京都新宿区新宿四丁目にある曹洞宗の寺院。山号は護本山。'),
    ('久伊豆神社', null, '埼玉県', '越谷市', 35.9018025, 139.7905491, 'B', '神社', '久伊豆神社（ひさいずじんじゃ）は、埼玉県越谷市越ヶ谷にある神社である。越谷の総鎮守とされている。'),
    ('万九千神社', null, '島根県', '出雲市', 35.3746536, 132.7871236, 'B', '神社', '万九千社（まくせのやしろ）、通称・万九千神社（まんくせんじんじゃ）は島根県出雲市斐川町にある神社。立虫神社（たちむしじんじゃ）の境内社として祀られている。'),
    ('宇奈岐日女神社', null, '大分県', null, 33.2568498, 131.3654962, 'B', '神社', '宇奈岐日女神社（うなぐひめじんじゃ/うなきひめ-/うなぎひめ-）は、大分県由布市にある神社。式内社で、旧社格は県社。'),
    ('第26番札所 金剛頂寺 (Kongōchōji)', null, '高知県', '室戸市', 33.3070734, 134.1228508, 'B', '寺院', null),
    ('総社神社', null, '群馬県', null, 36.3880464, 139.0378887, 'B', '神社', '総社神社（そうじゃじんじゃ）は、群馬県前橋市元総社町にある神社。上野国総社で、旧社格は県社。'),
    ('松岬神社', null, '山形県', null, 37.9092579, 140.10666, 'B', '神社', '松岬神社（まつがさきじんじゃ）は、山形県米沢市に鎮座する神社。上杉神社の摂社。'),
    ('蟹満寺', null, '京都府', null, 34.7862514, 135.8162305, 'B', '寺院', null),
    ('真福寺', null, '東京都', null, 35.6657453, 139.7493304, 'B', '寺院', '真福寺（しんぷくじ）は、東京都港区にある真言宗智山派の寺院。真言宗智山派総本山智積院の別院であり、真言宗智山派の宗務出張所が置かれている。'),
    ('北澤八幡神社', null, '東京都', null, 35.6562201, 139.6697449, 'B', '神社', '北澤八幡神社（きたざわはちまんじんじゃ）は、東京都世田谷区代沢にある神社（八幡宮）である。通称は北澤八幡宮（きたざわはちまんぐう）。'),
    ('磐井神社', null, '東京都', null, 35.5851416, 139.7356331, 'B', '神社', '磐井神社（いわいじんじゃ）は、東京都大田区大森北にある神社（八幡宮）。式内社で、旧社格は郷社。'),
    ('草戸稲荷神社', null, '広島県', null, 34.479548, 133.3464421, 'B', '神社', null),
    ('杉山神社', null, '神奈川県', null, 35.5283867, 139.5269304, 'B', '神社', '杉山神社（すぎやまじんじゃ）は、神奈川県横浜市緑区西八朔町にある神社。式内社論社、武蔵国六宮。'),
    ('総泉寺', null, '東京都', null, 35.7781852, 139.693707, 'B', '寺院', null),
    ('岩松院', null, '長野県', null, 36.6984606, 138.3338805, 'B', '寺院', '岩松院（がんしょういん）は、長野県上高井郡小布施町雁田にある曹洞宗の寺院。山号は梅洞山。'),
    ('円光寺', null, '京都府', null, 35.0449987, 135.7971651, 'B', '寺院', '円光寺（えんこうじ）は、京都市左京区一乗寺にある臨済宗南禅寺派の寺院。山号は瑞巌山（ずいがんさん）。'),
    ('妙宣寺', null, '新潟県', null, 37.9715523, 138.3732015, 'B', '寺院', '妙宣寺（みょうせんじ）は、新潟県佐渡市阿仏坊にある日蓮宗の寺院。日蓮の弟子阿仏房日得が自宅を寺として開基した日蓮宗佐渡三本山のひとつ。'),
    ('泉神社', null, '茨城県', null, 36.5185394, 140.6249533, 'B', '神社', '泉神社（いずみじんじゃ）は茨城県日立市にある神社である。『延喜式神名帳』の「天速玉姫命神社」に比定されており、境内にある湧泉は『常陸国風土記』に「密筑の里の大井」として記述がある。'),
    ('蓮昌寺', null, '東京都', null, 35.7568322, 139.82537, 'B', '寺院', null),
    ('沼名前神社', null, '広島県', null, 34.3864234, 133.3790141, 'B', '神社', '沼名前神社（ぬなくまじんじゃ）は、広島県福山市鞆町後地にある神社。式内社、旧社格は国幣小社で、現在は神社本庁の別表神社。'),
    ('伽耶院', null, '兵庫県', null, 34.8054785, 135.0583166, 'B', '寺院', '伽耶院（がやいん）は、兵庫県三木市志染町大谷にある本山修験宗の寺院。山号は大谷山（おおたにさん）。'),
    ('第22番札所 平等寺', null, '徳島県', '阿南市', 33.8521418, 134.5823363, 'B', '寺院', '平等寺（びょうどうじ）は、徳島県阿南市新野町にある高野山真言宗の寺院。白水山（はくすいざん）、医王院（いおういん）と号す。'),
    ('大善寺', null, '東京都', null, 35.671664, 139.3452167, 'B', '寺院', '大善寺（だいぜんじ）は、東京都八王子市にある浄土宗の寺院。山号は観池山。'),
    ('大龍寺', null, '東京都', null, 35.737746, 139.7546965, 'B', '寺院', '大龍寺（だいりゅうじ）は、東京都北区田端4丁目にある真言宗霊雲寺派の寺院。'),
    ('中央寺', null, '北海道', '札幌市', 43.0533006, 141.3563786, 'B', '寺院', '中央寺（ちゅうおうじ）は北海道札幌市中央区南6条西2丁目にある曹洞宗の仏教寺院。山号は實相山。'),
    ('二宮赤城神社', null, '群馬県', null, 36.3672528, 139.1676494, 'B', '神社', '二宮赤城神社（にのみやあかぎじんじゃ）は、群馬県前橋市二之宮町にある神社。式内社（名神大社）論社、上野国二宮論社。'),
    ('実相寺', null, '静岡県', null, 35.1725648, 138.6274535, 'B', '寺院', '実相寺（じっそうじ、實相寺とも表記）は静岡県富士市岩本にある、日蓮宗の本山（霊蹟寺院）。山号は岩本山。'),
    ('赤羽八幡神社', null, '東京都', null, 35.7830641, 139.7171057, 'B', '神社', null),
    ('衣笠山 地蔵院', null, '京都府', null, 34.9906862, 135.6863635, 'B', '寺院', '地蔵院（じぞういん）は、京都市西京区にある臨済宗系単立の寺院。山号は衣笠山（えりゅうざん）。'),
    ('円応寺', null, '神奈川県', '鎌倉市', 35.3296997, 139.5529452, 'B', '寺院', '円応寺（えんのうじ）は、神奈川県鎌倉市山ノ内にある臨済宗建長寺派の仏教寺院。開山は桑田道海（智覚禅師）とも伝えるが未詳。'),
    ('琴似神社', null, '北海道', '札幌市', 43.0732021, 141.301543, 'B', '神社', null),
    ('妙蓮寺', null, '京都府', null, 35.0345245, 135.7501722, 'B', '寺院', '妙蓮寺（みょうれんじ）は、京都市上京区妙蓮寺前町にある本門法華宗の大本山の寺院。山号は卯木山（うぼくさん）。'),
    ('円通寺', null, '青森県', null, 41.2924509, 141.2144105, 'B', '寺院', '円通寺（えんつうじ）は、青森県むつ市にある曹洞宗の寺院。山号は吉祥山。'),
    ('目白不動願照寺', null, '大阪府', null, 34.4646641, 135.5883788, 'B', '寺院', null),
    ('白鬚神社', null, '東京都', null, 35.7250949, 139.8130611, 'B', '神社', null),
    ('瀬戸神社', null, '神奈川県', null, 35.3324957, 139.6219815, 'B', '神社', null),
    ('第13番札所 大日寺', null, '徳島県', '徳島市', 34.038117, 134.4625583, 'B', '寺院', '大日寺（だいにちじ）は、徳島県徳島市一宮町に位置する真言宗大覚寺派の寺院。大栗山（おおぐりざん）、花蔵院（けぞういん）と号す。'),
    ('下総国分寺', null, '千葉県', null, 35.7438606, 139.9165095, 'B', '寺院', '下総国分寺（しもうさこくぶんじ）は、千葉県市川市にある真言宗豊山派の寺院。山号は国分山。'),
    ('六郷神社', null, '東京都', null, 35.5439479, 139.7127807, 'B', '神社', '六郷神社（ろくごうじんじゃ）は、東京都大田区東六郷にある神社である。六郷一円の総鎮守として伝えられる。'),
    ('安楽寺', null, '京都府', null, 35.0218663, 135.796649, 'B', '寺院', '安楽寺（あんらくじ）は、京都市左京区鹿ケ谷御所ノ段町にある浄土宗系単立の寺院。山号は住蓮山。'),
    ('天寧寺', null, '福島県', null, 37.4903676, 139.9528311, 'B', '寺院', '天寧寺（てんねいじ）は，福島県会津若松市東山町石山天寧に所在する曹洞宗寺院。山号は萬松山。'),
    ('金蓮寺', null, '愛知県', null, 34.8093781, 137.0725854, 'B', '寺院', null),
    ('於美阿志神社', null, '奈良県', null, 34.4568376, 135.8028632, 'B', '神社', '於美阿志神社（おみあしじんじゃ）は、奈良県高市郡明日香村にある神社。式内社で、旧社格は村社。'),
    ('織姫神社', null, '京都府', null, 34.8910631, 135.8058609, 'B', '神社', '橋姫神社（はしひめじんじゃ）は、京都府宇治市にある神社である。宇治橋を守るとされる。'),
    ('前鳥神社', null, '神奈川県', '平塚市', 35.3570226, 139.3646753, 'B', '神社', '前鳥神社（さきとりじんじゃ）は、神奈川県平塚市四之宮にある神社。旧社格は郷社。'),
    ('長講堂', null, '京都府', null, 34.9938632, 135.7638586, 'B', '寺院', null),
    ('金山寺', null, '岡山県', null, 34.737374, 133.9479987, 'B', '寺院', '金山寺（きんざんじ、かなやまじ）は、岡山県岡山市北区金山寺（かなやまじ）にある天台宗の寺院。山号は銘金山。'),
    ('長谷寺', null, '群馬県', null, 36.3851102, 138.9325061, 'B', '寺院', null),
    ('第43番札所 明石寺', null, '愛媛県', '西予市', 33.3692339, 132.5190216, 'B', '寺院', '明石寺（めいせきじ）は、愛媛県西予市にある天台寺門宗の寺院。源光山（げんこうざん）、円手院（えんしゅいん）と号す。'),
    ('松苧神社', null, '新潟県', null, 37.1476754, 138.6464232, 'B', '神社', '松苧神社（まつおじんしゃ）は、新潟県十日町市犬伏（いぬぶし）の松苧山にある神社。「松苧大権現」とも呼ばれる。'),
    ('厳島神社', null, '神奈川県', null, 35.4433293, 139.6337571, 'B', '神社', '厳島神社（いつくしまじんじゃ）は、神奈川県横浜市中区羽衣町二丁目にある神社。武蔵国久良岐郡横浜村の鎮守で、現在は宗像三女神（市杵島姫尊、多紀理姫尊、多岐都姫尊）を祭神とする。'),
    ('長慶寺', null, '大阪府', null, 34.366896, 135.2870168, 'B', '寺院', null),
    ('金胎寺', null, '京都府', null, 34.8300319, 135.9091113, 'B', '寺院', null),
    ('高椅神社', null, '栃木県', null, 36.3374224, 139.892022, 'B', '神社', null),
    ('寂光寺', null, '京都府', null, 35.0112039, 135.7773507, 'B', '寺院', '寂光寺（じゃっこうじ）は、京都府京都市左京区にある、顕本法華宗の本山。山号は妙泉山。'),
    ('早吸日女神社', null, '大分県', null, 33.2502208, 131.8783869, 'B', '神社', '早吸日女神社（はやすいひめじんじゃ、はやすひめじんじゃ、速吸日女神社とも表記）は、大分県大分市にある神社。式内社で、旧社格は県社。'),
    ('第10番札所 切幡寺', null, '徳島県', '阿波市', 34.1077257, 134.3043032, 'B', '寺院', '切幡寺（きりはたじ）は徳島県阿波市市場町切幡にある高野山真言宗の寺院。得度山（とくどざん）灌頂院（かんじょういん）と号す。'),
    ('ワットパクナム日本別院', null, '千葉県', null, 35.8466739, 140.3975004, 'B', '寺院', 'ワットパクナム日本別院（ワットパクナムにほんべついん、タイ語:วัดปากน้ำญี่ปุ่น）は、千葉県成田市にある、日本最大のタイの仏教の寺院。'),
    ('開口神社', null, '大阪府', '堺市', 34.5767547, 135.4744328, 'B', '神社', null),
    ('萬満寺', null, '千葉県', null, 35.8129523, 139.9196103, 'B', '寺院', '万満寺（まんまんじ、萬満寺）は千葉県松戸市馬橋にある臨済宗大徳寺派の寺院。山号は法王山。'),
    ('長楽寺', null, '京都府', null, 35.0025902, 135.7835394, 'B', '寺院', null),
    ('和光寺', null, '大阪府', null, 34.6740786, 135.4890007, 'B', '寺院', '和光寺（わこうじ）は、大阪市西区北堀江にある浄土宗の寺院。山号は蓮池山。'),
    ('別格01 大山寺', null, '徳島県', '上板町', 34.1592474, 134.3995553, 'B', '寺院', '大山寺（たいさんじ）は徳島県板野郡上板町に所在する真言宗醍醐派の寺院。仏王山（ぶつおうざん）、玉林院（ぎょくりんいん）と号す。'),
    ('陶荒田神社', null, '大阪府', null, 34.5104033, 135.5224563, 'B', '神社', null),
    ('第20番札所 鶴林寺', null, '徳島県', '勝浦町', 33.9141272, 134.505258, 'B', '寺院', null),
    ('馬見岡綿向神社', null, '滋賀県', '日野町', 35.0149557, 136.2618372, 'B', '神社', null),
    ('長尾神社', null, '奈良県', null, 34.5088498, 135.7103938, 'B', '神社', null),
    ('本光寺', null, '千葉県', null, 35.7557718, 139.9539573, 'B', '寺院', '本光寺（ほんこうじ）は、千葉県市川市にある、日蓮宗の寺院。山号は光胤山。'),
    ('報徳二宮神社', null, '神奈川県', '小田原市', 35.2497951, 139.1531546, 'B', '神社', '報徳二宮神社（ほうとくにのみやじんじゃ）は、神奈川県小田原市にある二宮尊徳を祀る神社である。旧社格は県社で、現在は神社本庁の別表神社となっている。'),
    ('御田八幡神社', null, '東京都', null, 35.643125, 139.7416202, 'B', '神社', '御田八幡神社（みたはちまんじんじゃ）は、東京都港区三田にある神社である。'),
    ('焼津神社', null, '静岡県', null, 34.8650033, 138.3136426, 'B', '神社', '焼津神社（やいづじんじゃ）は、静岡県焼津市焼津にある神社。式内社、旧社格は県社で、現在は神社本庁の別表神社。'),
    ('安国寺', null, '広島県', null, 34.3881619, 133.3798208, 'B', '寺院', '安国寺（あんこくじ）は、広島県福山市鞆町後地にある臨済宗妙心寺派の仏教寺院。山号は瑞雲山。'),
    ('總見寺', null, '愛知県', null, 35.1598402, 136.9029193, 'B', '寺院', null),
    ('三縁寺', null, '京都府', null, 35.0713851, 135.7951742, 'B', '寺院', '三縁寺（さんえんじ）は京都市左京区にある浄土宗の寺院である。池田屋事件で亡くなった維新志士の墓がある事で知られている。'),
    ('寒川神社', null, '千葉県', null, 35.5971755, 140.120149, 'B', '神社', '寒川神社（さむかわじんじゃ）は、千葉県千葉市中央区にある神社である。式内小社、旧社格は村社。'),
    ('正春寺', null, '東京都', null, 35.6841479, 139.6915911, 'B', '寺院', '正春寺（しょうしゅんじ）は、東京都渋谷区にある真宗大谷派系（浄土真宗東本願寺派）の単立寺院。'),
    ('戒光寺', null, '京都府', null, 34.9808593, 135.7780756, 'B', '寺院', '戒光寺（かいこうじ）は、京都市東山区泉涌寺山内町にある真言宗泉涌寺派の準別格本山の寺院。総本山泉涌寺の塔頭。'),
    ('法蔵寺', null, '愛知県', null, 34.8884991, 137.2617707, 'B', '寺院', '法蔵寺（ほうぞうじ）は、愛知県岡崎市本宿町にある浄土宗西山深草派の寺院。山号は二村山（にそんざん）。'),
    ('玉作湯神社', null, '島根県', null, 35.413689, 133.0117747, 'B', '神社', null),
    ('竹林寺', null, '奈良県', null, 34.6724932, 135.7031476, 'B', '寺院', null),
    ('大鷲神社', null, '東京都', null, 35.8092584, 139.8202084, 'B', '神社', '大鷲神社（おおとりじんじゃ）は、東京都足立区で地元・花畑地区の産土神とされる神社で、花畑大鷲神社（はなはたおおとりじんじゃ）とも称される。'),
    ('三輪神社', null, '愛知県', null, 35.1609106, 136.9056025, 'B', '神社', '三輪神社（みわじんじゃ）は、愛知県名古屋市中区大須3-9-32にある神社。社格は旧村社。'),
    ('深志神社', null, '長野県', null, 36.22971, 137.9736241, 'B', '神社', '深志神社（ふかしじんじゃ）は、長野県松本市深志にある神社である。旧社格は県社で、現在は神社本庁の別表神社。'),
    ('苗村神社', null, '滋賀県', null, 35.064968, 136.1282192, 'B', '神社', null),
    ('泉穴師神社', null, '大阪府', null, 34.4964243, 135.4196713, 'B', '神社', '泉穴師神社（いずみあなしじんじゃ）は、大阪府泉大津市にある神社。式内社、和泉国二宮で、旧社格は府社。'),
    ('和気神社', null, '岡山県', null, 34.8203707, 134.1756265, 'B', '神社', '和気神社（わけじんじゃ）は、岡山県和気郡和気町にある神社。旧社格は県社。'),
    ('円通寺', null, '京都府', null, 35.064392, 135.7686312, 'B', '寺院', '圓通寺（えんつうじ）は、京都市左京区岩倉にある臨済宗妙心寺派の寺院。山号は大悲山。'),
    ('大鳥神社', null, '東京都', '目黒区', 35.6322287, 139.7081699, 'B', '神社', '大鳥神社（おおとりじんじゃ）は、東京都目黒区下目黒にある神社。かつての目黒村（それ以前は下目黒村）の総鎮守。'),
    ('瑞泉寺', null, '愛知県', null, 35.389838, 136.9477526, 'B', '寺院', null),
    ('東湖八坂神社', null, '秋田県', null, 39.897306, 139.9629371, 'B', '神社', '東湖八坂神社（とうこやさかじんじゃ）は、日本の東北地方、秋田県潟上市天王字天王（江戸時代における出羽国秋田郡天王村、幕藩体制下の久保田藩天王村）に所在する神社である。'),
    ('香取神社', null, '東京都', null, 35.7044169, 139.8254918, 'B', '神社', null),
    ('止止呂支比売命神社', null, '大阪府', null, 34.6048112, 135.4974063, 'B', '神社', '止止呂支比売命神社（とどろきひめみことじんじゃ）は、大阪府大阪市住吉区にある神社。式内社で、旧社格は村社。'),
    ('大名持神社', null, '奈良県', '奈良県吉野郡吉野町河原屋', 34.3940018, 135.8689178, 'B', '神社', '大名持神社（おおなもちじんじゃ）は、奈良県吉野郡吉野町河原屋にある神社。式内社（名神大社）で、旧社格は郷社。'),
    ('青麻神社', null, '宮城県', null, 38.3352669, 140.9350141, 'B', '神社', null),
    ('岡太神社', null, '兵庫県', null, 34.7214685, 135.3794424, 'B', '神社', '岡太神社（おかたじんじゃ）は、兵庫県西宮市小松南町にある神社。式内社論社で、旧社格は県社。'),
    ('瓢箪山稲荷神社', null, '大阪府', null, 34.660733, 135.6419942, 'B', '神社', null),
    ('十和田神社', null, '青森県', null, 40.4331605, 140.892145, 'B', '神社', '十和田神社（とわだじんじゃ）は、青森県十和田市奥瀬十和田湖畔休屋486にある神社。江戸時代は十湾寺として熊野修験の寺院が建っており、巡礼の聖地であった。'),
    ('東照宮', null, '愛知県', null, 34.9785178, 137.5879694, 'B', '神社', null),
    ('成覚寺', null, '東京都', '新宿区', 35.6911747, 139.7092945, 'B', '寺院', '成覚寺（じょうかくじ）は、東京都新宿区新宿二丁目にある浄土宗の寺院である。正式名は十劫山無量寿院成覚寺。'),
    ('護国寺', null, '沖縄県', null, 26.220085, 127.6715798, 'B', '寺院', null),
    ('第02番札所 極楽寺', null, '徳島県', '鳴門市', 34.1561604, 134.4902123, 'B', '寺院', '極楽寺（ごくらくじ）は徳島県鳴門市にある高野山真言宗の寺院。日照山（にっしょうざん）無量寿院（むりょうじゅいん）と号す。'),
    ('滝山寺', null, '愛知県', null, 34.9881689, 137.2055819, 'B', '寺院', '滝山寺（たきさんじ）は、愛知県岡崎市滝町にある天台宗の寺院。'),
    ('阿智神社', null, '岡山県', null, 34.5975068, 133.7733796, 'B', '神社', null),
    ('無量壽寺', null, '愛知県', null, 35.0073707, 137.0758193, 'B', '寺院', '無量寿寺（むりょうじゅじ）は、愛知県知立市にある臨済宗妙心寺派の寺院。山号は八橋山（やつはしさん）。'),
    ('春日山神社', null, '新潟県', null, 37.1474352, 138.2089548, 'B', '神社', '春日山神社（かすがやまじんじゃ）は、新潟県上越市の春日山山腹にある神社。'),
    ('神祇大社', null, '静岡県', null, 34.9053486, 139.1192126, 'B', '神社', '神祇大社（じんぎたいしゃ）は、静岡県伊東市富戸にある単立神社。'),
