    ('浄土院', null, '京都府', null, 35.0273071, 135.797504, 'B', '寺院', '浄土院（じょうどいん）は、京都市左京区銀閣寺町にある浄土宗の寺院。山号は清泰山。'),
    ('菅原院天満宮神社', null, '京都府', null, 35.0195718, 135.7590819, 'B', '神社', null),
    ('錦天満宮', null, '京都府', null, 35.0050453, 135.7673955, 'B', '神社', null),
    ('引接寺', null, '京都府', null, 35.0351909, 135.7405729, 'B', '寺院', '引接寺（いんじょうじ）は、京都市上京区千本通廬山寺上る閻魔前町にある高野山真言宗の寺院。山号は光明山。'),
    ('帯解寺', null, '奈良県', null, 34.6448355, 135.8267247, 'B', '寺院', '帯解寺（おびとけでら）は、奈良県奈良市にある華厳宗の寺院。山号は子安山。'),
    ('十輪院', null, '奈良県', null, 34.676355, 135.8333142, 'B', '寺院', '十輪院（じゅうりんいん）は、奈良県奈良市十輪院町にある真言宗醍醐派の寺院。山号は雨宝山。'),
    ('熊野若王子神社', null, '京都府', null, 35.0156681, 135.7961879, 'B', '神社', '熊野若王子神社（くまのにゃくおうじじんじゃ）は、京都市左京区若王子町にある神社。旧社格は村社。'),
    ('江田神社', null, '宮崎県', null, 31.9604562, 131.4648765, 'B', '神社', null),
    ('夢宅寺', null, '青森県', null, 40.8868969, 140.8641766, 'B', '寺院', '夢宅寺（むたくじ）は青森県青森市浅虫山下に所在する曹洞宗寺院。山号は安養山。'),
    ('粟井神社', null, '香川県', null, 34.0912154, 133.7047693, 'B', '神社', '粟井神社（あわいじんじゃ）は、香川県観音寺市にある神社。讃岐国苅田郡（後の豊田郡、次いで三豊郡）の式内社（名神大社）で讃岐国式内二十四社のひとつ。'),
    ('岩間寺', null, '滋賀県', null, 34.932483, 135.8786752, 'B', '寺院', '正法寺（しょうほうじ）は、滋賀県大津市にある真言宗醍醐派の寺院。山号は岩間山。'),
    ('第11番札所 藤井寺', null, '徳島県', '吉野川市', 34.0516692, 134.3485336, 'B', '寺院', null),
    ('豊国神社', null, '滋賀県', null, 35.3804862, 136.2650187, 'B', '神社', null),
    ('大瀬神社', null, '静岡県', null, 35.0281672, 138.7864366, 'B', '神社', '引手力命神社（ひきてちからのみことじんじゃ、ひきたぢからのみことじんじゃ）は、静岡県沼津市西浦江梨の大瀬崎（おせざき）にある神社。旧社格は式内社（国弊小社論社）、郷社。'),
    ('吉原神社', null, '東京都', null, 35.7228449, 139.7933546, 'B', '神社', '吉原神社（よしわらじんじゃ）は、東京都台東区千束三丁目20番2号に鎮座する神社。
かつての新吉原遊廓を守護していた氏神様であり、計6柱の神さま（神社）をお祀りしている。'),
    ('鳩森八幡神社', null, '東京都', null, 35.6779241, 139.709569, 'B', '神社', '鳩森八幡神社（はとのもりはちまんじんじゃ、別称については下記）は、東京都渋谷区千駄ヶ谷にある神社。千駄ヶ谷一帯の総鎮守である。'),
    ('千光寺', null, '岐阜県', null, 36.1899853, 137.2886973, 'B', '寺院', '千光寺（せんこうじ）は、岐阜県高山市丹生川町下保にある高野山真言宗の寺院である。山号は袈裟山。'),
    ('小野神社', null, '東京都', null, 35.6642229, 139.4564021, 'B', '神社', '小野神社（おのじんじゃ）は、東京都府中市にある神社。式内社論社。'),
    ('能褒野神社', null, '三重県', null, 34.8855449, 136.4833856, 'B', '神社', null),
    ('第32番札所 禅師峰寺', null, '高知県', '南国市', 33.5267092, 133.6113941, 'B', '寺院', null),
    ('常宮神社', null, '福井県', null, 35.6904365, 136.0297034, 'B', '神社', '常宮神社（じょうぐうじんじゃ）は、福井県敦賀市常宮にある神社。式内社論社で、旧社格は県社。'),
    ('第41番札所 龍光寺', null, '愛媛県', '宇和島市', 33.2952023, 132.5986435, 'B', '寺院', null),
    ('長命寺', null, '東京都', null, 35.7178498, 139.8090139, 'B', '寺院', null),
    ('多聞院', null, '広島県', null, 34.3867954, 132.4715944, 'B', '寺院', '多聞院（たもんいん）は、広島県広島市南区にある寺院。比治山西麓の登山道入口に位置する。'),
    ('皆中稲荷神社', null, '東京都', null, 35.7012427, 139.6993921, 'B', '神社', '皆中稲荷神社（かいちゅういなりじんじゃ）は東京都新宿区百人町にある稲荷神社である。JR新大久保駅の西約100mの市街地に鎮座している。'),
    ('寶相寺', null, '東京都', null, 35.7059052, 139.8001104, 'B', '寺院', '東駒形（ひがしこまがた）は、東京都墨田区の町名。現行行政地名は東駒形一丁目から東駒形四丁目。'),
    ('日高神社', null, '岩手県', null, 39.1427825, 141.1326149, 'B', '神社', '日高神社（ひたかじんじゃ）は、岩手県奥州市水沢に鎮座する神社。旧社格は郷社。'),
    ('大乗寺', null, '兵庫県', null, 35.6237655, 134.6255569, 'B', '寺院', '大乗寺（だいじょうじ）は、兵庫県美方郡香美町にある高野山真言宗の寺院。円山応挙ゆかりの寺で応挙寺ともいう。'),
    ('札幌護国神社', null, '北海道', '札幌市', 43.0407426, 141.3529813, 'B', '神社', '札幌護国神社（さっぽろごこくじんじゃ、旧字体: 札幌護國神󠄀社󠄁）は、北海道札幌市中央区にある神社。護国神社の一つである。'),
    ('妙行寺', null, '東京都', null, 35.7432279, 139.7311211, 'B', '寺院', '妙行寺（みょうぎょうじ）は、東京都豊島区西巣鴨にある、法華宗陣門流の仏教寺院。山号は長徳山。'),
    ('鼻節神社', null, '宮城県', null, 38.2959385, 141.0850313, 'B', '神社', null),
    ('漢國神社', null, '奈良県', null, 34.6835164, 135.8253049, 'B', '神社', '漢國神社（かんごうじんじゃ）は、奈良県奈良市にある神社。式内社（小、論社）で、旧社格は県社。'),
    ('白鷺神社', null, '栃木県', null, 36.4404428, 139.9130763, 'B', '神社', null),
    ('船越山瑠璃寺', null, '兵庫県', '佐用町', 35.1047163, 134.4236609, 'B', '寺院', '瑠璃寺（るりじ）は、兵庫県佐用郡佐用町船越にある高野山真言宗の別格本山の寺院。山号は船越山。'),
    ('和樂備神社', null, '埼玉県', null, 35.8265506, 139.6812847, 'B', '神社', '和樂備神社（わらびじんじゃ）は埼玉県蕨市にある神社である。新字体を用いて和楽備神社と表記されることが多い。'),
    ('北海道護国神社', null, '北海道', '旭川市', 43.7881888, 142.3668222, 'B', '神社', '北海道護國神社（ほっかいどうごこくじんじゃ）は、北海道旭川市に鎮座する護国神社。北海道・樺太関係の戦没者等の国事殉難者を祀る。'),
    ('玉姫稲荷神社', null, '東京都', null, 35.7269353, 139.8023283, 'B', '神社', null),
    ('妙法寺', null, '神奈川県', null, 35.3128009, 139.5593167, 'B', '寺院', '妙法寺（みょうほうじ）は、神奈川県鎌倉市大町（名越）にある日蓮宗の寺院。山号は楞厳山。'),
    ('深見神社', null, '神奈川県', null, 35.4686365, 139.4716605, 'B', '神社', '深見神社（ふかみじんじゃ）は、神奈川県大和市深見に鎮座する神社。西暦927年（延長5年）の『延喜式神名帳』に記載されている相模国の延喜式内社十三社の内の一社（小社）とされる。'),
    ('満願寺', null, '東京都', null, 35.6101061, 139.6497681, 'B', '寺院', '満願寺（まんがんじ）は、東京都世田谷区等々力にある真言宗智山派の仏教寺院。'),
    ('昆陽寺', null, '兵庫県', null, 34.7769019, 135.3884086, 'B', '寺院', '昆陽寺（こんようじ、こやでら）は、兵庫県伊丹市寺本にある高野山真言宗の寺院。山号は崑崙山（こんろんさん）。'),
    ('大仏寺', null, '富山県', null, 36.7456634, 137.017249, 'B', '寺院', '大佛寺（だいぶつじ）は、富山県高岡市大手町（もと定塚町）にある浄土宗の寺院。境内にある銅造阿弥陀如来坐像は高岡大仏（たかおかだいぶつ）として知られる。'),
    ('百舌鳥八幡宮', null, '大阪府', null, 34.5534864, 135.4946498, 'B', '神社', null),
    ('立本寺', null, '京都府', null, 35.024822, 135.7385736, 'B', '寺院', null),
    ('諫早神社', null, '長崎県', null, 32.8483985, 130.0432636, 'B', '神社', null),
    ('第17番札所 井戸寺', null, '徳島県', '徳島市', 34.0851717, 134.4854986, 'B', '寺院', '井戸寺（いどじ）は、徳島県徳島市国府町井戸にある真言宗善通寺派の寺院。瑠璃山（るりざん）、真福院（しんぷくいん）と号す。'),
    ('手児奈霊神堂', null, '千葉県', null, 35.7383504, 139.9092631, 'B', '寺院', '手児奈霊神堂（てこなれいじんどう）は、千葉県市川市真間に所在する、伝説上の女性手児奈を祀る霊堂である。手児奈霊堂とも称される。'),
    ('太田神社', null, '京都府', null, 35.059857, 135.7584983, 'B', '寺院', '大田神社（おおたじんじゃ）は、京都府京都市北区上賀茂本山にある神社。式内社で、現在は賀茂別雷神社（上賀茂神社）の境外摂社（第三摂社）。'),
    ('浅間神社', null, '神奈川県', null, 35.4651525, 139.6108473, 'B', '神社', '浅間神社（せんげんじんじゃ）は、神奈川県横浜市西区にある神社。旧・芝生村（しぼうむら、現・浅間町）の鎮守であった。'),
    ('蓮華寺', null, '京都府', null, 34.983412, 135.7397892, 'B', '寺院', null),
    ('法恩寺', null, '東京都', null, 35.7022068, 139.8102305, 'B', '寺院', '法恩寺（ほうおんじ）は、東京都墨田区太平にある日蓮宗の寺院。山号は平河山。'),
    ('了仙寺', null, '静岡県', null, 34.6721798, 138.9416489, 'B', '寺院', '了仙寺（りょうせんじ）は、静岡県下田市七軒町3丁目にある日蓮宗の寺院。山号は法順山。'),
    ('お岩稲荷田宮神社', null, '東京都', '新宿区', 35.6854764, 139.7208727, 'B', '神社', '於岩稲荷田宮神社（おいわいなりたみやじんじゃ）は、東京都新宿区の神社。'),
    ('五條宮', null, '大阪府', null, 34.6570768, 135.518608, 'B', '神社', '五條宮（ごじょうぐう）は、大阪市天王寺区にある神社。旧社格は村社。'),
    ('大光院', null, '愛知県', null, 35.1609349, 136.9011048, 'B', '寺院', '大光院（だいこういん）は、愛知県名古屋市中区大須二丁目7番25号にある曹洞宗の寺院。山号は興國山（こうこくさん）。'),
    ('虎捕　山津見神社', null, '福島県', null, 37.7364983, 140.6969555, 'B', '神社', '山津見神社（やまつみじんじゃ）は、福島県相馬郡飯舘村に鎮座する神社。
別名虎捕山津見神社とも呼ばれる。'),
    ('二所山田神社', null, '山口県', null, 34.2341254, 131.8167305, 'B', '神社', '二所山田神社（にしょやまだじんじゃ）は、山口県周南市にある神社である。式内社で、旧社格は郷社。'),
    ('花岳寺', null, '兵庫県', null, 34.7527827, 134.3905904, 'B', '寺院', '花岳寺（かがくじ）は、兵庫県赤穂市にある曹洞宗の寺院。山号は台雲山（たいうんざん）。'),
    ('回天神社', null, '茨城県', null, 36.3925788, 140.4544663, 'B', '神社', '回天神社（かいてんじんじゃ）は茨城県水戸市にある神社である。'),
    ('末吉宮', null, '沖縄県', '那覇市', 26.229356, 127.7144617, 'B', '神社', '末吉宮（すえよしぐう）は、沖縄県那覇市首里末吉町の末吉公園内にある神社で琉球八社のひとつ。旧社格は無格社。'),
    ('輪王寺', null, '宮城県', null, 38.2832153, 140.8587803, 'B', '寺院', null),
    ('光明寺', null, '東京都', null, 35.573614, 139.6843099, 'B', '寺院', '光明寺（こうみょうじ）は、東京都大田区鵜の木にある浄土宗の寺院。'),
