    ('相馬太田神社', null, '福島県', null, 37.6107485, 140.9672492, 'B', '神社', '相馬太田神社（そうまおおたじんじゃ）は、福島県南相馬市原町区中太田に立地する神社。相馬三妙見社の一つ。'),
    ('東漸寺', null, '千葉県', null, 35.8291742, 139.92905, 'B', '寺院', '東漸寺（とうぜんじ）は、千葉県松戸市小金にある枝垂桜で有名な浄土宗の寺院。'),
    ('平等寺', null, '奈良県', null, 34.5267803, 135.8542973, 'B', '寺院', '平等寺（びょうどうじ）は、奈良県桜井市三輪にある曹洞宗の寺院。山号は三輪山。'),
    ('気多若宮神社', null, '岐阜県', null, 36.2392502, 137.1976293, 'B', '神社', '気多若宮神社（けたわかみやじんじゃ）は、岐阜県飛騨市（旧吉城郡古川町）にある神社である。通称 杉本さま。'),
    ('国清寺', null, '静岡県', null, 35.070696, 138.9724089, 'B', '寺院', '国清寺（こくせいじ／こくしょうじ）は、静岡県伊豆の国市奈古谷にある臨済宗円覚寺派の寺院である。室町時代に関東十刹に列せられた。'),
    ('拝島大師', null, '東京都', null, 35.7057391, 139.347104, 'B', '寺院', '拝島大師（はいじまだいし）は、東京都昭島市拝島町一丁目にある天台宗の仏教寺院である。本覚院が正式な名称である。'),
    ('大平山神社', null, '栃木県', 'Tochigi', 36.3626322, 139.6932291, 'B', '神社', '太平山神社（おおひらさんじんじゃ）は、栃木県栃木市にある神社。旧社格は県社。'),
    ('竹寺', null, '埼玉県', null, 35.8891205, 139.192094, 'B', '寺院', '竹寺（たけでら）は、埼玉県飯能市大字南字八王子にある天台宗の寺院である。正式名称は医王山薬寿院八王寺（いおうざんやくじゅいんはちおうじ）。'),
    ('大宮神社', null, '大阪府', null, 34.7252782, 135.5450872, 'B', '神社', '大宮神社（おおみやじんじゃ）は、大阪市旭区大宮にある神社。旧社格は村社。'),
    ('乃木神社', null, '栃木県', null, 36.887713, 140.0025432, 'B', '神社', '乃木神社（のぎじんじゃ）は、栃木県那須塩原市にある神社である。旧社格は県社。'),
    ('山口大神宮', null, '山口県', null, 34.1843928, 131.4680103, 'B', '神社', '山口大神宮（やまぐちだいじんぐう）は、山口県山口市にある神社である。旧社格は県社。'),
