    ('蓮着寺', null, '静岡県', null, 34.8827336, 139.131003, 'C', '寺院', '蓮着寺（れんちゃくじ）は、静岡県伊東市にある、法華宗陣門流の霊跡別院。山号は俎岩山（そがんざん）。'),
    ('龍源院', null, '京都府', null, 35.0421786, 135.7461047, 'C', '寺院', null),
    ('栖賢寺', null, '京都府', null, 35.0642102, 135.8011731, 'C', '寺院', '栖賢寺（せいけんじ）は京都市左京区上高野にある臨済宗の仏教寺院。'),
    ('西念寺', null, '東京都', '新宿区', 35.6846695, 139.7254838, 'C', '寺院', null),
    ('岩水寺', null, '静岡県', null, 34.8454277, 137.7933979, 'C', '寺院', '岩水寺（がんすいじ）は、静岡県浜松市浜名区にある高野山真言宗別格本山の寺院。山号は龍宮山。'),
    ('明眼院', null, '愛知県', null, 35.1745216, 136.8205037, 'C', '寺院', '明眼院（みょうげんいん）は、愛知県海部郡大治町にある天台宗の寺院である。日本最古の眼科専門の医療施設として知られる。'),
    ('黄金山神社', null, '宮城県', null, 38.5598514, 141.1390484, 'C', '神社', null),
    ('月江寺', null, '山梨県', null, 35.4934141, 138.8000223, 'C', '寺院', '月江寺（げっこうじ）は、山梨県富士吉田市下吉田に所在する寺院。臨済宗妙心寺派の寺院で、山号は水上山。'),
    ('唐崎神社', null, '滋賀県', null, 35.0473676, 135.8743203, 'C', '神社', '唐崎神社（からさきじんじゃ）は、滋賀県大津市にある神社。日吉大社の摂社の一つである。'),
    ('養老神社', null, '岐阜県', null, 35.2824679, 136.5388604, 'C', '神社', null),
    ('大宝八幡宮', null, '茨城県', null, 36.2046353, 139.9713997, 'C', '神社', '大宝八幡宮（だいほうはちまんぐう）は、茨城県下妻市大宝に所在する関東地方で最古の八幡宮。県社。'),
    ('江文神社', null, '京都府', null, 35.1130015, 135.813621, 'C', '神社', '江文神社（えぶみじんじゃ）は京都府京都市左京区大原野村町にある神社。毎年5月5日に例大祭が行われる。'),
    ('第05番札所 地蔵寺', null, '徳島県', '板野町', 34.1371936, 134.4319428, 'C', '寺院', '地蔵寺（じぞうじ）は、徳島県板野郡板野町羅漢にある真言宗御室派の寺院。無尽山（むじんざん）荘厳院（しょうごんいん）と号す。'),
    ('加佐登神社', null, '三重県', '鈴鹿市加佐登町', 34.9002177, 136.527256, 'C', '神社', '加佐登神社（かさどじんじゃ）は三重県鈴鹿市にある神社である。'),
    ('日本寺', null, '千葉県', '多古町', 35.7402666, 140.487392, 'C', '寺院', '日本寺（にちほんじ）は、千葉県香取郡多古町にある、日蓮宗の本山（由緒寺院）。山号は正東山。'),
    ('八幡大神社', null, '東京都', null, 35.6940845, 139.559521, 'C', '神社', '八幡大神社（はちまんだいじんじゃ）は、東京都三鷹市にある神社。別名、三鷹八幡大神社とも言われている。'),
    ('聖天了徳院', null, '大阪府', null, 34.6984073, 135.4829978, 'C', '寺院', '了徳院（りょうとくいん）は、大阪市福島区にある東寺真言宗の寺院。山号は如意山。'),
    ('乙宝寺大日堂', null, '新潟県', null, 38.1199434, 139.4030724, 'C', '寺院', '乙寶寺（おっぽうじ）は、新潟県胎内市乙（きのと）にある真言宗智山派の寺院。猿供養寺、乙寺（きのとでら）とも呼ばれる。'),
    ('新羅神社', null, '岐阜県', null, 35.3303082, 137.127494, 'C', '神社', '新羅神社（しんらじんじゃ）は、岐阜県多治見市御幸町に鎮座する神社。社格は旧郷社。'),
    ('阿弥陀寺', null, '福島県', null, 37.5007968, 139.9193267, 'C', '寺院', null),
