    ('埼玉縣護國神社', null, '埼玉県', 'さいたま市', 35.9195698, 139.6279129, 'C', '神社', '埼玉縣護國神社（さいたまけんごこくじんじゃ）は、埼玉県さいたま市大宮区に鎮座する旧指定護国神社である。'),
    ('梅林寺', null, '大阪府', null, 34.8188313, 135.5718273, 'C', '寺院', null),
    ('尉殿神社', null, '東京都', null, 35.7438019, 139.5503089, 'C', '神社', '尉殿神社（じょうどのじんじゃ）は、東京都西東京市にある神社である。'),
    ('龍蔵寺', null, '群馬県', null, 36.4205561, 139.0722889, 'C', '寺院', null),
    ('亀ケ池八幡宮', null, '神奈川県', '相模原市', 35.550928, 139.3661492, 'C', '神社', '亀ヶ池八幡宮（かめがいけはちまんぐう）は神奈川県相模原市にある神社。'),
    ('菟足神社', null, '愛知県', null, 34.7973458, 137.3658364, 'C', '神社', null),
    ('喜見山 摩尼寺', null, '鳥取県', '鳥取市', 35.5294225, 134.2634551, 'C', '寺院', '摩尼寺（まにじ、まにでら）は鳥取県鳥取市にある天台宗安楽律法流の寺。山号は喜見山（きけんざん）。'),
    ('金福寺', null, '京都府', null, 35.0421483, 135.7954337, 'C', '寺院', null),
    ('本刈谷神社', null, '愛知県', null, 34.9786229, 136.9899678, 'C', '神社', '本刈谷神社（もとかりやじんじゃ）は、愛知県刈谷市天王町4丁目9番地にある神社。旧社格は村社。'),
    ('瀧尾神社', null, '京都府', null, 34.9825301, 135.7706777, 'C', '神社', null),
    ('長寿寺', null, '神奈川県', null, 35.3315236, 139.5503113, 'C', '寺院', null),
    ('國前寺', null, '広島県', null, 34.403117, 132.4811553, 'C', '寺院', '國前寺（こくぜんじ）は、広島県広島市東区山根町にある日蓮宗本山（由緒寺院）の寺院。すぐそばに尾長天満宮がある。'),
    ('円鏡寺', null, '岐阜県', null, 35.436155, 136.6871811, 'C', '寺院', '円鏡寺（えんきょうじ、旧字体：圓鏡寺）は、岐阜県本巣郡北方町にある高野山真言宗別格本山の寺院である。'),
    ('丹生酒殿神社', null, '和歌山県', 'かつらぎ町', 34.2893585, 135.5200242, 'C', '神社', '丹生酒殿神社（にうさかどのじんじゃ）は、和歌山県伊都郡かつらぎ町三谷に鎮座する神社。'),
    ('大高山神社', null, '宮城県', null, 38.0385182, 140.6995864, 'C', '神社', '大高山神社（おおたかやまじんじゃ）は、宮城県柴田郡大河原町にある神社。式内社（名神大社）で、旧社格は郷社。'),
    ('円通山 大黒寺', null, '京都府', null, 34.9369635, 135.7607787, 'C', '寺院', '大黒寺（だいこくじ）は、京都府京都市伏見区鷹匠町にある、真言宗東寺派の寺院である。通称は薩摩寺（さつまでら）。'),
    ('法谷寺', null, '徳島県', null, 34.0700332, 134.5149927, 'C', '寺院', '法谷寺（ほうこくじ）は、徳島県徳島市南庄町の眉山麓にある真言宗大覚寺派の寺院。山号は救世山。'),
    ('多井畑厄除八幡宮', null, '兵庫県', null, 34.6620814, 135.0955487, 'C', '神社', '多井畑厄除八幡宮（たいのはたやくよけはちまんぐう）とは、兵庫県神戸市須磨区多井畑字宮脇に鎮座する神社。通称、多井畑厄神。'),
    ('永慶寺', null, '奈良県', null, 34.6486083, 135.7765136, 'C', '寺院', '永慶寺（えいけいじ）は、奈良県大和郡山市永慶寺町にある寺院。黄檗宗寺院で、山号は龍華山。'),
    ('柏神社', null, '千葉県', '柏市', 35.8599645, 139.9736896, 'C', '神社', '柏神社（かしわじんじゃ）は、千葉県柏市柏三丁目にある神社。羽黒神社と八坂神社を合祀した神社である。'),
    ('月桂寺', null, '東京都', null, 35.696905, 139.7228011, 'C', '寺院', '月桂寺（げっけいじ）は、東京都新宿区河田町にある臨済宗円覚寺派の寺院。'),
    ('孝恩寺', null, '大阪府', null, 34.3971592, 135.3945693, 'C', '寺院', '孝恩寺（こうおんじ）は、大阪府貝塚市木積（こつみ）にある浄土宗の寺院。山号は慈眼山。'),
    ('龍口明神社', null, '神奈川県', null, 35.318103, 139.5070358, 'C', '神社', null),
    ('大生郷天満宮', null, '茨城県', '常総市', 36.0606685, 139.9526789, 'C', '神社', '大生郷天満宮（おおのごうてんまんぐう）は、茨城県常総市の神社。'),
    ('大宮賣神社', null, '京都府', null, 35.5912113, 135.1018568, 'C', '神社', '大宮売神社（おおみやめじんじゃ/おおみやのめじんじゃ、大宮賣神社）は、京都府京丹後市大宮町周枳（すき）にある神社。式内社（名神大社）で、丹後国二宮を称する。'),
    ('蒲原神社', null, '新潟県', null, 37.9147035, 139.0702977, 'C', '神社', null),
    ('椋橋総社', null, '大阪府', null, 34.7433447, 135.4607052, 'C', '神社', '椋橋総社（くらはしそうしゃ）は、大阪府豊中市庄本町に鎮座する神社。鯉伝説が古くから知られており、別称を「鯉の宮」ともいう。'),
    ('釜蓋神社', null, '鹿児島県', null, 31.2495692, 130.4161145, 'C', '神社', '射楯兵主神社（いたてつわものぬしじんじゃ）は、鹿児島県南九州市頴娃町別府に鎮座する神社である。旧社格は無格社。'),
    ('勝鬘寺', null, '愛知県', null, 34.9185334, 137.1547268, 'C', '寺院', '勝鬘寺（しょうまんじ）は、愛知県岡崎市針崎町にある真宗大谷派の寺院。山号は和田山、寂光山。'),
    ('長者山新羅神社', null, '青森県', null, 40.5028882, 141.4911126, 'C', '神社', null),
    ('法霊山 龗神社', null, '青森県', null, 40.5149206, 141.4903926, 'C', '神社', null),
    ('本行寺', null, '東京都', null, 35.5800879, 139.7033846, 'C', '寺院', '本行寺（ほんぎょうじ）は東京都大田区池上にある日蓮宗の寺院。山号は長崇山。'),
    ('専光寺', null, '東京都', null, 35.6798626, 139.5950445, 'C', '寺院', '専光寺（せんこうじ）は、東京都世田谷区北烏山にある寺院。浄土宗単立寺院で、創建は江戸時代初期の1604年（慶長9年）に遡る。'),
    ('成田山川越別院', null, '埼玉県', null, 35.9193158, 139.4888354, 'C', '寺院', '成田山川越別院本行院（なりたさん かわごえべついん ほんぎょういん）は、埼玉県川越市久保町ある真言宗智山派の寺院である。成田山新勝寺（千葉県成田市）の別院で、通称は川越不動。'),
    ('物部神社', null, '愛知県', null, 35.1734501, 136.9316439, 'C', '神社', '物部神社（もののべじんじゃ）は、愛知県名古屋市東区筒井にある神社。『延喜式神名帳』の尾張国愛智郡「物部神社」に比定されているが、後述するように異説もある。'),
    ('常堅寺', null, '岩手県', null, 39.3545011, 141.5710403, 'C', '寺院', '常堅寺（じょうけんじ）は岩手県遠野市にある曹洞宗の寺院。山号は蓮峰山。'),
    ('本宗寺', null, '愛知県', null, 34.9255259, 137.1925288, 'C', '寺院', '本宗寺（ほんしゅうじ）は、愛知県岡崎市美合町にある浄土真宗本願寺派の寺院。山号は土呂殿。'),
    ('高伝寺', null, '佐賀県', '佐賀市', 33.2379447, 130.2832399, 'C', '寺院', null),
    ('冨塚八幡宮', null, '神奈川県', null, 35.3935852, 139.5287574, 'C', '神社', '富塚八幡宮（とみつかはちまんぐう）は、神奈川県横浜市戸塚区にある神社である。旧社格は郷社。'),
    ('郡山八幡神社', null, '鹿児島県', null, 32.0829217, 130.5980337, 'C', '神社', null),
    ('妙法寺', null, '山梨県', null, 35.5445935, 138.4305703, 'C', '寺院', '妙法寺（みょうほうじ）は、山梨県南巨摩郡富士川町小室3063番地にある日蓮宗の本山（由緒寺院）で小西法縁六本山の一つ。山号は徳栄山または小室山。'),
    ('妙縁寺', null, '東京都', null, 35.7082076, 139.8039935, 'C', '寺院', '妙縁寺（みょうえんじ）は、東京都墨田区吾妻橋に所在する日蓮正宗の寺院。山号は正栄山（しょうえいざん）。'),
    ('本願寺神戸別院 (モダン寺)', null, '兵庫県', null, 34.6860135, 135.180144, 'C', '寺院', '本願寺神戸別院（ほんがんじこうべべついん）は、兵庫県神戸市中央区下山手通にある浄土真宗本願寺派の寺院である。同派本山の西本願寺（京都市）直属の別院である。'),
    ('白幡神社', null, '千葉県', null, 35.6036266, 140.1139331, 'C', '神社', null),
    ('妙見寺', null, '群馬県', null, 36.3928899, 139.0196929, 'C', '寺院', '妙見寺（みょうけんじ）は、群馬県高崎市引間町にある天台宗の寺院である。山号は三鈷山。'),
    ('白崎八幡宮', null, '山口県', null, 34.1606006, 132.2089796, 'C', '神社', '白崎八幡宮（しらさきはちまんぐう）は、山口県岩国市今津「白崎山」にある神社。'),
    ('正受院', null, '東京都', '新宿区', 35.6911106, 139.7096211, 'C', '寺院', '正受院（しょうじゅいん）は、東京都新宿区新宿二丁目にある浄土宗の寺院である。正式には明了山正受院願光寺という。'),
    ('興正寺富田林別院', null, '大阪府', null, 34.5001422, 135.6024521, 'C', '寺院', '富田林興正寺別院（とんだばやしこうしょうじべついん）は、大阪府富田林市富田林町にある真宗興正派の寺院。本山興正寺の別院。'),
    ('神宮寺', null, '福井県', null, 35.4596729, 135.7829638, 'C', '寺院', null),
    ('鎮宅霊符神社', null, '奈良県', null, 34.6773866, 135.8282148, 'C', '神社', null),
    ('大日寺', null, '千葉県', '千葉市', 35.6276114, 140.107606, 'C', '寺院', '大日寺（だいにちじ）は、千葉県千葉市稲毛区轟町にある真言宗豊山派の寺院。山号は阿毘盧山。'),
    ('大泉寺', null, '山梨県', null, 35.6769966, 138.580891, 'C', '寺院', '大泉寺（だいせんじ）は、山梨県甲府市古府中町にある寺院。曹洞宗寺院で、山号は万年山。'),
    ('龍城神社', null, '愛知県', null, 34.956132, 137.1591337, 'C', '神社', null),
    ('別格02 童学寺', null, '徳島県', '石井町', 34.0582504, 134.4280592, 'C', '寺院', null),
    ('大井神社', null, '静岡県', null, 34.8333982, 138.1717564, 'C', '神社', '大井神社（おおいじんじゃ）は、静岡県島田市大井町にある神社。国史見在社、旧社格は県社で、現在は神社本庁の別表神社。'),
    ('三柱神社', null, '福岡県', null, 33.1703115, 130.4151859, 'C', '神社', '三柱神社（みはしらじんじゃ）は、福岡県柳川市三橋町にある神社。柳河藩初代藩主の立花宗茂、その妻の誾千代及び岳父の戸次道雪の三柱を祀り、柳川城からは鬼門の位置に鎮座している。'),
    ('願得寺', null, '大阪府', null, 34.7425718, 135.5963256, 'C', '寺院', null),
    ('武蔵國府八幡宮', null, '東京都', null, 35.6677307, 139.4889779, 'C', '神社', '武蔵国府八幡宮（むさしのこくふはちまんぐう）とは、東京都府中市八幡町に所在する神社。「府中八幡宮」「六所八幡神社」ともいい、地元では単に「八幡神社」とも呼ぶ。'),
    ('葛西神社', null, '東京都', '葛飾区', 35.7713273, 139.8784527, 'C', '神社', null),
    ('愛宕神社', null, '宮城県', '仙台市', 38.2458699, 140.8755152, 'C', '神社', '宮城県仙台市太白区向山四丁目にある愛宕神社（あたごじんじゃ）は、愛宕信仰にもとづく愛宕神社の一つである。広瀬川の南側にある標高75メートルの愛宕山の頂上に鎮座する。'),
    ('三崎稲荷神社', null, '東京都', null, 35.7016464, 139.7544889, 'C', '神社', '三崎稲荷神社（みさきいなりじんじゃ）は、東京都千代田区神田三崎町にある神社。創建は、鎌倉時代の建久年間より前と伝えられる。'),
    ('蛸薬師堂 永福寺', null, '京都府', null, 35.0061903, 135.767337, 'C', '寺院', '永福寺（えいふくじ）は、京都市中京区新京極蛸薬師東側町にある浄土宗西山深草派の寺院。山号は浄瑠璃山。'),
    ('圓乘院', null, '埼玉県', 'さいたま市', 35.8817997, 139.6203309, 'C', '寺院', '円乗院（えんじょういん）は、埼玉県さいたま市中央区にある真言宗智山派の寺院。'),
    ('妙高寺', null, '東京都', null, 35.6756841, 139.5983166, 'C', '寺院', '妙高寺（みょうこうじ）は、東京都世田谷区北烏山にある寺院である。日蓮宗に属し、本山は身延山久遠寺、山号を「玄立山」という。'),
    ('貴船神社', null, '神奈川県', null, 35.1499276, 139.1461552, 'C', '神社', null),
    ('福島天満宮', null, '大阪府', '大阪市', 34.6949102, 135.4869772, 'C', '寺院', null),
    ('日枝神社', null, '神奈川県', null, 35.4353947, 139.6157462, 'C', '神社', '日枝神社（ひえじんじゃ）は、神奈川県横浜市南区にある神社。旧村社で吉田新田（横浜関外地区40余ヶ町）の総鎮守。'),
    ('第14番札所 常楽寺', null, '徳島県', '徳島市', 34.0503581, 134.4759521, 'C', '寺院', '常楽寺（じょうらくじ）は、徳島県徳島市国府町延命にある高野山真言宗の寺院。盛寿山（せいじゅさん）、延命院（えんめいいん）と号す。'),
    ('建勲神社', null, '山形県', null, 38.3557377, 140.3748704, 'C', '神社', '建勲神社（たけいさおじんじゃ）は、山形県天童市にある神社。旧社格は県社。'),
    ('最勝寺', null, '東京都', null, 35.7039357, 139.8510536, 'C', '寺院', '最勝寺（さいしょうじ）は、東京都江戸川区平井にある天台宗の寺院。通称「目黄不動尊」、正式名称は「牛宝山（ごほうざん）明王院最勝寺」である。'),
    ('若宮八幡宮', null, '神奈川県', null, 35.5346995, 139.7248477, 'C', '神社', null),
    ('神光院', null, '京都府', null, 35.0600972, 135.7434667, 'C', '寺院', null),
    ('菅原天満宮', null, '奈良県', null, 34.6856615, 135.7784901, 'C', '神社', null),
    ('伊奴神社', null, '愛知県', null, 35.2084155, 136.8976483, 'C', '神社', '伊奴神社（いぬじんじゃ）は、愛知県名古屋市西区稲生町にある神社。『延喜式神名帳』の尾張国山田郡「伊奴神社」に比定されている。'),
    ('神崎神社', null, '千葉県', null, 35.9058546, 140.4001672, 'C', '神社', '神崎神社（こうざきじんじゃ）は、千葉県香取郡神崎町（下総国香取郡）にある神社。旧社格は県社。'),
    ('鈴鹿明神社', null, '神奈川県', '座間市', 35.4846862, 139.3946948, 'C', '神社', null),
    ('小石川大神宮', null, '東京都', null, 35.7094265, 139.7492232, 'C', '神社', '小石川大神宮（こいしかわ だいじんぐう）は東京都文京区にある神社。天照大神を祀る。'),
    ('京都ゑびす神社', null, '京都府', null, 34.9998291, 135.7719052, 'C', '神社', '京都ゑびす神社（きょうとえびすじんじゃ）は、京都市東山区にある神社。旧社格は郷社。'),
    ('産田神社', null, '三重県', null, 33.8807871, 136.0796436, 'C', '神社', null),
    ('秩父32番 般若山 法性寺', null, '埼玉県', null, 35.9966146, 139.0129819, 'C', '寺院', '法性寺（ほうしょうじ）は、埼玉県秩父郡小鹿野町にある曹洞宗の寺院で、山号は般若山と号する。'),
    ('安国論寺', null, '神奈川県', '鎌倉市', 35.3113421, 139.5585866, 'C', '寺院', '安国論寺（あんこくろんじ）は、神奈川県鎌倉市大町（名越）にある日蓮宗の寺院。山号は妙法華經山。'),
    ('鷺宮八幡神社', null, '東京都', null, 35.7216123, 139.6382927, 'C', '神社', null),
    ('瑞應寺', null, '愛媛県', null, 33.9192853, 133.3017357, 'C', '寺院', '瑞應寺（ずいおうじ）は、愛媛県新居浜市山根町にある曹洞宗の寺院である。市街地南端の四国山地山麓に位置する。'),
    ('両足院', null, '京都府', null, 35.0001351, 135.7746121, 'C', '寺院', '両足院（りょうそくいん）は、京都市東山区にある臨済宗建仁寺派の寺院。大本山建仁寺の塔頭。'),
    ('立行寺', null, '東京都', null, 35.6432155, 139.7323181, 'C', '寺院', '立行寺（りゅうぎょうじ）とは、東京都港区白金二丁目に存在する法華宗の寺院。別名を大久保寺という。'),
    ('潮見寺', null, '徳島県', null, 34.0571198, 134.5443502, 'C', '寺院', '潮見寺（ちょうけんじ）は徳島県徳島市西二軒屋町にある仏教寺院。山号は黒谷山、宗派は浄土真宗本願寺派。'),
    ('円通院', null, '宮城県', '松島町', 38.3712885, 141.0599598, 'C', '寺院', '円通院（えんつういん。旧字体：圓通院）は、宮城県宮城郡松島町（日本三景・松島）にある臨済宗妙心寺派の寺院である。'),
    ('華蔵寺', null, '愛知県', null, 34.8428038, 137.0815864, 'C', '寺院', null),
    ('伊豆国分寺', null, '静岡県', null, 35.1200984, 138.9099139, 'C', '寺院', '伊豆国分寺（いずこくぶんじ）は、静岡県三島市にある日蓮宗の寺院。旧称は蓮行寺。'),
    ('天石立神社', null, '奈良県', null, 34.7269314, 135.959164, 'C', '神社', '天石立神社（あまのいわたてじんじゃ）は奈良県奈良市柳生町の岩戸谷にある神社。戸岩山という小高い山の北麓、標高330メートルの山中に本殿を有たず、鎮座する巨岩を直接拝する形態をとる。'),
    ('仙寿院', null, '東京都', null, 35.6754115, 139.711676, 'C', '寺院', '仙寿院（せんじゅいん、法雲山仙寿院東漸寺）は、東京都渋谷区千駄ヶ谷にある日蓮宗の寺院である。旧本山は大野山本遠寺。'),
    ('崇道天皇神社', null, '奈良県', null, 34.6559296, 135.8250643, 'C', '神社', null),
    ('崇道天皇神社', null, '奈良県', null, 34.6588464, 135.823351, 'C', '神社', null),
    ('崇道天皇神社', null, '奈良県', null, 34.6630529, 135.8290192, 'C', '神社', null),
    ('六所神社', null, '島根県', null, 35.4272622, 133.1042231, 'C', '神社', '六所神社（ろくしょじんじゃ）は、島根県松江市大草町にある神社である。意宇六社の一つ。'),
    ('甘縄神明神社', null, '神奈川県', '鎌倉市', 35.3143072, 139.5371091, 'C', '神社', null),
    ('和歌浦天満宮', null, '和歌山県', null, 34.1912247, 135.1643813, 'C', '神社', '和歌浦天満宮（わかうらてんまんぐう）は、和歌山県和歌山市和歌浦西にある神社。法人としての名称は「天満神社」。'),
    ('第30番札所 善楽寺', null, '高知県', '高知市', 33.5918535, 133.5777101, 'C', '寺院', '善楽寺（ぜんらくじ）は、高知県高知市にある真言宗豊山派の寺院。百々山（どどさん）、東明院（とうみょういん）と号す。'),
    ('真山神社', null, '秋田県', null, 39.9269771, 139.7671572, 'C', '神社', '真山神社（しんざんじんじゃ）は、秋田県男鹿市北浦字真山にある神社。江戸時代は秋田六郡三十三観音霊場の27番札所として赤神山光飯寺があったが、明治の廃仏毀釈運動で真山神社となった。'),
    ('第18番札所 恩山寺', null, '徳島県', '小松島市', 33.9860981, 134.5778614, 'C', '寺院', '恩山寺（おんざんじ）は、徳島県小松島市田野町にある高野山真言宗の寺院。母養山（ぼようざん）、宝樹院（ほうじゅいん）と号す。'),
    ('大盛寺', null, '東京都', null, 35.699126, 139.5744078, 'C', '寺院', '大盛寺（だいせいじ）は、東京都三鷹市井の頭にある天台宗の寺院。山号は明静山。'),
    ('永尾剱神社', null, '熊本県', null, 32.6319333, 130.6161029, 'C', '神社', null),
    ('八海山 法音寺', null, '山形県', null, 37.9133638, 140.0917376, 'C', '寺院', '法音寺（ほうおんじ）は、山形県米沢市にある真言宗豊山派の寺院。山号は八海山。'),
    ('源覚寺', null, '東京都', null, 35.7107999, 139.7511065, 'C', '寺院', null),
    ('長建寺', null, '京都府', null, 34.9282364, 135.7608881, 'C', '寺院', null),
    ('舞子六神社', null, '兵庫県', null, 34.6375572, 135.0288081, 'C', '神社', null),
    ('別小江神社', null, '愛知県', null, 35.2104006, 136.9209494, 'C', '神社', '別小江神社（わけおえじんじゃ）は、愛知県名古屋市北区安井四丁目に鎮座する神社。『延喜式神名帳』の尾張国山田郡「別小江神社」に比定されているが、後述するように異説もある。'),
    ('石船神社', null, '山梨県', null, 35.5630967, 138.9730472, 'C', '神社', '石船神社（いしふねじんじゃ・いしぶねじんじゃ）は、山梨県都留市朝日馬場にある神社。表筒男命、中筒男命、底筒男命を祭神とする。'),
    ('妙源寺', null, '愛知県', null, 34.9485577, 137.1242835, 'C', '寺院', '妙源寺（みょうげんじ）は、愛知県岡崎市大和町にある真宗高田派の寺院。山号は桑子山。'),
    ('諏訪神社', null, '東京都', null, 35.730582, 139.7672293, 'C', '神社', null),
    ('登弥神社', null, '奈良県', null, 34.6609833, 135.7659638, 'C', '神社', '登彌神社（とみじんじゃ）は、奈良県奈良市石木町に鎮座する式内社で、旧社格は、県社(昭和14年に列格)。神社の北の明神山からは、祭祀土器が出土している。'),
    ('西明寺', null, '京都府', null, 35.0572308, 135.6747987, 'C', '寺院', null),
    ('温泉寺', null, '兵庫県', '神戸市', 34.7958196, 135.2482247, 'C', '寺院', '温泉寺（おんせんじ）は、兵庫県神戸市北区有馬町にある黄檗宗の寺院。山号は有馬山。'),
    ('飛騨国分寺', null, '岐阜県', null, 36.1435011, 137.2538422, 'C', '寺院', null),
    ('山倉大神', null, '千葉県', null, 35.7903562, 140.5387747, 'C', '神社', '山倉大神（やまくらだいじん）は、千葉県香取市山倉（下総国香取郡）にある神社。'),
    ('稲田神社', null, '茨城県', null, 36.3685335, 140.2064598, 'C', '神社', '稲田神社（いなだじんじゃ、稻田神社）は、茨城県笠間市稲田にある神社。式内社（名神大社）で、旧社格は県社。'),
    ('開山堂', null, '東京都', null, 35.7171928, 139.7776333, 'C', '寺院', null),
    ('穴切大神社', null, '山梨県', null, 35.6626481, 138.5610766, 'C', '神社', null),
    ('櫻宮', null, '大阪府', null, 34.7006074, 135.5236768, 'C', '神社', '櫻宮（さくらのみや）は、大阪市都島区中野町にある神社。旧・社格は郷社。'),
    ('大安楽寺', null, '東京都', null, 35.6908528, 139.7780335, 'C', '寺院', '大安楽寺（だいあんらくじ）は、東京都中央区日本橋小伝馬町にある高野山真言宗の仏教寺院である。山号は新高野山。'),
    ('栖岸院', null, '東京都', null, 35.6686027, 139.6426956, 'C', '寺院', '栖岸院（せいがんいん）は、東京都杉並区にある浄土宗の寺院。'),
    ('西光寺', null, '奈良県', null, 34.4610568, 135.7614941, 'C', '寺院', null),
    ('四本木稲荷神社', null, '東京都', null, 35.7497067, 139.7291605, 'C', '神社', '四本木稲荷神社（よもとぎいなりじんじゃ）は、東京都北区の神社。現在は教派神道の教団神道大教所属の神社となっている。'),
    ('顕本寺', null, '大阪府', '堺市', 34.5734842, 135.4741406, 'C', '寺院', null),
    ('貴船神社', null, '愛知県', null, 35.1683117, 137.0017864, 'C', '神社', '貴船神社（きふねじんじゃ）は、愛知県名古屋市名東区一社3丁目14番地に位置する神社。法人格の名称は宗教法人貴船社（法人番号：7180005001911）。'),
    ('興神社', null, '長崎県', null, 33.7696826, 129.7318176, 'C', '神社', null),
    ('青海神社', null, '新潟県', null, 37.6566551, 139.053825, 'C', '神社', null),
    ('第34番札所 種間寺', null, '高知県', '高知市', 33.4917044, 133.4876666, 'C', '寺院', null),
    ('向上寺', null, '広島県', null, 34.3064398, 133.0867581, 'C', '寺院', '向上寺（こうじょうじ）は、広島県尾道市にある曹洞宗の寺院。山号は潮音山。'),
    ('證菩提寺', null, '神奈川県', null, 35.3628457, 139.5699497, 'C', '寺院', null),
    ('隠岐國分寺', null, '島根県', null, 36.224257, 133.3072968, 'C', '寺院', null),
    ('福昌寺', null, '東京都', null, 35.6505183, 139.6362377, 'C', '寺院', '福昌寺（ふくしょうじ）は、東京都世田谷区経堂にある寺院。曹洞宗に属し、山号を「経堂山」という。'),
    ('伊勢崎神社', null, '群馬県', null, 36.3197375, 139.1934219, 'C', '神社', '伊勢崎神社（いせさきじんじゃ）は、群馬県伊勢崎市本町にある神社。旧社名は飯福神社（いいふくじんじゃ）で、通称はいいふくさま。'),
    ('大連神社', null, '山口県', '下関市', 33.9605431, 130.9486309, 'C', '神社', '大連神社（旧字体: 大連󠄀神󠄀社󠄁、だいれんじんじゃ）は、山口県下関市にある神社である。'),
    ('須佐神社', null, '和歌山県', null, 34.0647539, 135.1416757, 'C', '神社', null),
    ('稲荷鬼王神社', null, '東京都', null, 35.6977693, 139.7052551, 'C', '神社', null),
    ('下野宮近津神社', null, '茨城県', null, 36.8175584, 140.3729681, 'C', '神社', null),
    ('東北寺', null, '東京都', null, 35.6519321, 139.7139131, 'C', '寺院', '禅河山東北寺（ぜんがさん とうぼくじ）は、東京都渋谷区広尾二丁目にある臨済宗妙心寺派の寺院。日向佐土原藩島津家、出羽米沢藩上杉家の墓所として知られる。'),
    ('光明寺', null, '神奈川県', null, 35.3587637, 139.2887396, 'C', '寺院', '光明寺（こうみょうじ）は、神奈川県平塚市にある天台宗の寺院。山号は金目山（かなめさん）。'),
    ('出雲伊波比神社', null, '埼玉県', null, 35.942478, 139.3112962, 'C', '神社', '出雲伊波比神社（いずもいわいじんじゃ）は埼玉県入間郡毛呂山町に鎮座する神社。旧社格は郷社。'),
    ('光明寺', null, '兵庫県', null, 34.9483236, 134.949191, 'C', '寺院', '光明寺（こうみょうじ）は、兵庫県加東市光明寺にある高野山真言宗の寺院。山号は五峯山（ごぶさん）。'),
    ('本福寺', null, '兵庫県', null, 34.5462317, 134.9896696, 'C', '寺院', '本福寺（ほんぷくじ）は、兵庫県淡路市にある真言密教の寺院で真言宗御室派の別格本山。'),
    ('第04番札所 大日寺', null, '徳島県', '板野郡', 34.1515688, 134.4308846, 'C', '寺院', '大日寺（だいにちじ）は徳島県板野郡板野町黒谷にある東寺真言宗の準別格本山。山号は黒巌山（こくがんざん）、院号は遍照院（へんじょういん）と号す。'),
    ('矢先稲荷神社', null, '東京都', null, 35.7135263, 139.7876524, 'C', '神社', null),
