    ('第06番札所 安楽寺', null, '徳島県', '上板町', 34.1181096, 134.3884768, 'C', '寺院', '安楽寺（あんらくじ）は徳島県板野郡上板町にある高野山真言宗の寺院。温泉山（おんせんざん）瑠璃光院（るりこういん）と号す。'),
    ('諸口神社', null, '静岡県', null, 34.9765993, 138.7668823, 'C', '神社', null),
    ('大岡寺', null, '滋賀県', null, 34.969189, 136.1789378, 'C', '寺院', '大岡寺（だいこうじ）は、滋賀県甲賀市水口町にある天台宗系単立の寺院。山号は龍王山。'),
    ('大井蔵王権現神社', null, '東京都', null, 35.6075215, 139.7314554, 'C', '神社', '大井蔵王権現神社（おおいざおうごんげんじんじゃ）は、東京都品川区大井にある神社。'),
    ('松原神社', null, '神奈川県', '小田原市', 35.2492727, 139.1599432, 'C', '神社', '松原神社（まつばらじんじゃ）は神奈川県小田原市にある神社である。小田原宿総鎮守。'),
    ('大蓮寺', null, '石川県', null, 36.55755, 136.6485941, 'C', '寺院', '大蓮寺（だいれんじ）は、石川県金沢市野町にある、浄土宗の寺院。'),
    ('妻恋神社', null, '東京都', null, 35.7034401, 139.7672287, 'C', '神社', '妻恋神社（つまこいじんじゃ）は、東京都文京区湯島三丁目にある神社。神紋は「檜扇に御の字」。'),
    ('靜岡縣護國神社', null, '静岡県', '静岡市', 34.9875346, 138.4069687, 'C', '神社', null),
    ('合氣神社', null, '茨城県', null, 36.2942466, 140.281319, 'C', '神社', '合氣神社（あいきじんじゃ 合気神社）は茨城県笠間市にある神社。合気道開祖植芝盛平の創建による、合気道に関する唯一の神社。'),
    ('天性寺', null, '大阪府', null, 34.4589527, 135.3651665, 'C', '寺院', '天性寺（てんしょうじ）は、大阪府岸和田市南町にある浄土宗の寺院。山号は護持山。'),
    ('常圓寺 (新宿区)', null, '東京都', null, 35.6940314, 139.6965802, 'C', '寺院', '常圓寺（じょうえんじ、常円寺）は、東京都新宿区西新宿七丁目にある日蓮宗の寺院。山号は福聚山。'),
    ('水戸八幡宮', null, '茨城県', null, 36.3877834, 140.4598855, 'C', '神社', '水戸八幡宮（みとはちまんぐう）は、茨城県水戸市八幡町にある神社。正式名称は「八幡宮」である。'),
    ('世界平和パゴダ', null, '福岡県', '北九州市', 33.9546664, 130.9707541, 'C', '寺院', '世界平和パゴダ（せかいへいわパゴダ、ビルマ語: ကမ္ဘာအေးစေတီတော်）は、福岡県北九州市門司区の瀬戸内海国立公園敷地内の和布刈公園に近接した山頂にあり、日本とミャ...'),
    ('光明寺', null, '神奈川県', '横浜市', 35.4427788, 139.6100292, 'C', '寺院', '光明寺（こうみょうじ）は、神奈川県横浜市南区庚台にある浄土宗の寺院である。山号を吉上山と称する。'),
    ('芦屋神社', null, '兵庫県', '芦屋市', 34.7426186, 135.3029679, 'C', '神社', null),
    ('草部吉見神社', null, '熊本県', null, 32.782451, 131.2180209, 'C', '神社', null),
    ('秋田県護国神社', null, '秋田県', null, 39.7412509, 140.08055, 'C', '神社', '秋田県護国神社（あきたけんごこくじんじゃ）は、秋田県秋田市にある神社（護国神社）。秋田県下の戦没者および伊弉諾尊・伊弉冉尊を祀る。'),
    ('大雄寺', null, '栃木県', null, 36.8656229, 140.1226572, 'C', '寺院', '大雄寺（だいおうじ）は栃木県大田原市にある曹洞宗の寺院。山号は黒羽山。'),
    ('鹿児島神社', null, '鹿児島県', null, 31.6097637, 130.5395796, 'C', '神社', null),
    ('圓照寺', null, '東京都', null, 35.7040533, 139.6903684, 'C', '寺院', '圓照寺（円照寺）（えんしょうじ）は、東京都新宿区北新宿三丁目にある真言宗豊山派の寺院。'),
    ('別格7番 出石寺', null, '愛媛県', '大洲市', 33.5354998, 132.4657994, 'C', '寺院', '出石寺（しゅっせきじ）は愛媛県大洲市に所在する真言宗御室派別格本山の寺院。金山（きんざん）、光明院（こうみょういん）と号す。'),
    ('大東神社', null, '東京都', '青梅市', 35.7951371, 139.3241533, 'C', '神社', '大東神社（だいとうじんじゃ）は、東京都青梅市に位置する神社。
祭神は天照大御神を始め、天津神国津神八百万の神々。'),
    ('安岡寺', null, '大阪府', null, 34.8690006, 135.6037914, 'C', '寺院', '安岡寺（あんこうじ）は、大阪府高槻市にある天台宗系単立の寺院。山号は南山。'),
    ('浅間神社', null, '山梨県', null, 35.647769, 138.6974562, 'C', '神社', '一宮浅間神社（いちのみやせんげんじんじゃ）は、山梨県西八代郡市川三郷町高田にある神社。式内社（名神大社）論社で、旧社格は村社。'),
