    ('興善寺', null, '兵庫県', null, 35.1743621, 135.1010196, 'C', '寺院', '興禅寺（こうぜんじ）は、兵庫県丹波市にある仏教寺院。山号は大梅山、曹洞宗別格地、本尊は釈迦如来（仏師春日作）。'),
    ('福井神社', null, '福井県', null, 36.0660021, 136.2196293, 'C', '神社', '福井神社（ふくいじんじゃ）は、福井県福井市にある神社である。旧社格は別格官幣社。'),
    ('胡宮神社', null, '滋賀県', null, 35.2152766, 136.2866573, 'C', '神社', null),
