    ('普門寺', null, '愛知県', null, 34.7451851, 137.4728351, 'C', '寺院', '普門寺（ふもんじ）は、愛知県豊橋市雲谷町にある高野山真言宗の寺院。
山号は船形山（せんぎょうさん）。'),
    ('鳳凰山 天妙国寺', null, '東京都', null, 35.611896, 139.7433952, 'C', '寺院', '天妙国寺（てんみょうこくじ）は、東京都品川区南品川にある、顕本法華宗の別格山。山号は鳳凰山。'),
    ('闇之森八幡社', null, '愛知県', null, 35.1482119, 136.89621, 'C', '神社', null),
    ('三重県護国神社', null, '三重県', null, 34.7331042, 136.5092887, 'C', '神社', '三重県護国神社（みえけんごこくじんじゃ）は、三重県津市にある神社（護国神社）である。禁門の変・戊辰戦争から第二次世界大戦までの三重県関係の戦歿者6万3百余柱を祀る。'),
    ('日置神社', null, '愛知県', null, 35.1553248, 136.8995785, 'C', '神社', null),
    ('子嶋寺', null, '奈良県', '高取町', 34.4521947, 135.7985438, 'C', '寺院', '子嶋寺（こじまでら）は、奈良県高市郡高取町観覚寺にある高野山真言宗の寺院。山号は子嶋山（報恩山とも）。'),
    ('大川神社', null, '京都府', null, 35.4479824, 135.2587205, 'C', '神社', '大川神社（おおかわじんじゃ）は、京都府舞鶴市大川にある神社である。社格は式内社（名神大）、府社。'),
    ('尾崎神社', null, '石川県', null, 36.5692638, 136.6574919, 'C', '神社', '尾﨑神社（おざきじんじゃ）は、石川県金沢市にある神社。天照大神、東照大権現、加賀藩三代藩主前田利常を祀る。'),
    ('寂光院', null, '愛知県', null, 35.3962939, 136.9620095, 'C', '寺院', '寂光院（じゃっこういん）は、愛知県犬山市にある真言宗智山派の寺院。山号は継鹿尾山（つがおざん）。'),
    ('一之御前神社', null, '愛知県', null, 35.1279403, 136.9083225, 'C', '神社', '一之御前神社（いちのみさきじんじゃ）は、愛知県名古屋市熱田区にある神社である。熱田神宮の境内摂社のひとつ。'),
    ('薬樹山延命寺', null, '大阪府', null, 34.4263254, 135.5944346, 'C', '寺院', '延命寺（えんめいじ）は、大阪府河内長野市の真言宗御室派の寺院。'),
    ('日岡神社', null, '兵庫県', null, 34.780745, 134.8606351, 'C', '神社', '日岡神社（ひおかじんじゃ）は、兵庫県加古川市加古川町大野にある神社。式内社で、旧社格は郷社。'),
    ('西野神社', null, '北海道', '札幌市', 43.0597451, 141.2604031, 'C', '神社', null),
    ('用賀神社', null, '東京都', null, 35.6277204, 139.6369716, 'C', '神社', null),
    ('新海三社神社', null, '長野県', null, 36.1955522, 138.5120395, 'C', '神社', '新海三社神社（しんかいさんしゃじんじゃ、単に「新海神社」ともいう）は、長野県佐久市田口に鎮座する神社。旧県社で佐久郡の総社。'),
    ('幸龍寺', null, '東京都', null, 35.6778323, 139.5956152, 'C', '寺院', '幸龍寺（こうりゅうじ）は、東京都世田谷区北烏山五丁目にある寺院。日蓮宗に属し、旧本山は大本山本圀寺（六条門流）である。'),
    ('高家神社', null, '千葉県', '南房総市', 34.9624597, 139.949596, 'C', '神社', null),
    ('善光寺', null, '北海道', null, 42.5205107, 140.7799338, 'C', '寺院', '有珠善光寺（うすぜんこうじ）は、北海道伊達市にある寺院。「善光寺跡」として国の史跡に指定されている。'),
    ('報恩寺', null, '京都府', null, 35.0331258, 135.7530118, 'C', '寺院', '報恩寺（ほうおんじ）は、京都市上京区にある浄土宗の寺院。山号は尭天山。'),
    ('延命寺', null, '東京都', null, 35.7316179, 139.7978339, 'C', '寺院', '延命寺（えんめいじ）は、東京都荒川区南千住にある浄土宗の寺院。'),
    ('子守神社', null, '千葉県', null, 35.6640627, 140.0492778, 'C', '神社', '子守神社（こまもりじんじゃ）は、千葉市花見川区幕張町にある神社。旧社格は村社。'),
    ('獅子窟寺', null, '大阪府', null, 34.7682888, 135.6961324, 'C', '寺院', null),
    ('遠見岬神社', null, '千葉県', '勝浦市', 35.1467051, 140.3155697, 'C', '神社', null),
    ('桃林寺', null, '沖縄県', null, 24.3437512, 124.1555183, 'C', '寺院', '桃林寺（とうりんじ）は、沖縄県石垣市にある臨済宗妙心寺派の寺院。山号は南海山。'),
    ('腹五社神社', null, '鹿児島県', '鹿児島市', 31.5846253, 130.7053598, 'C', '神社', null),
