    ('山阪神社', null, '大阪府', null, 34.6232774, 135.5217548, 'C', '神社', '山阪神社（やまさかじんじゃ）は、大阪市東住吉区山坂に鎮座する神社。'),
    ('馬橋稲荷神社', null, '東京都', '杉並区', 35.7029604, 139.6425699, 'C', '神社', null),
    ('居木神社', null, '東京都', null, 35.6198531, 139.7252578, 'C', '神社', '居木神社（いるぎじんしゃ、ゐるぎじんじゃ）は、東京都品川区大崎にある神社。'),
    ('足神神社', null, '静岡県', null, 35.2405983, 137.9031265, 'C', '神社', null),
    ('賣布神社', null, '島根県', null, 35.466549, 133.0588227, 'C', '神社', '売布神社（めふじんじゃ）は、島根県松江市に鎮座する神社。式内社で旧社格は県社。'),
    ('福山八幡宮', null, '広島県', null, 34.49455, 133.359888, 'C', '神社', null),
    ('武蔵寺', null, '福岡県', null, 33.4893926, 130.507785, 'C', '寺院', '武蔵寺（ぶぞうじ）は、福岡県筑紫野市武蔵、菅原道真公ゆかりの天拝山の登山口にある、天台宗の寺院。山号は椿花山（ちんかざん）。'),
    ('楠永神社', null, '大阪府', null, 34.6842409, 135.4925608, 'C', '神社', '楠永神社（くすながじんじゃ）は、大阪府大阪市西区にある神社。'),
    ('専称寺', null, '山形県', null, 38.2517832, 140.3464523, 'C', '寺院', '専称寺（せんしょうじ）は、山形市緑町(旧寺町)にある真宗大谷派の寺院。山号は最上山。'),
    ('櫻井神社', null, '福岡県', '糸島市', 33.6281963, 130.1919889, 'C', '神社', '桜井神社（さくらいじんじゃ）は福岡県糸島市志摩桜井にある福岡藩二代藩主黒田忠之が創建した神社で、正式には「櫻井神社」である。'),
    ('廣幡八幡宮', null, '千葉県', null, 35.8387918, 139.9890786, 'C', '神社', '廣幡八幡宮（ひろはたはちまんぐう）は千葉県柏市にある神社である。旧社格は村社。'),
    ('高石神社', null, '大阪府', null, 34.5276154, 135.4327742, 'C', '神社', null),
    ('安達太良神社', null, '福島県', null, 37.5211975, 140.4043066, 'C', '神社', '安達太良神社（あだたらじんじゃ）は福島県本宮市にある神社である。式内小社飯豊和氣神社の論社である。'),
    ('長祐山 承教寺', null, '東京都', null, 35.6366608, 139.7346907, 'C', '寺院', '承教寺（じょうきょうじ）は東京都港区高輪に所在する日蓮宗の寺院。山号は長祐山。'),
    ('秩父今宮神社', null, '埼玉県', null, 35.9949601, 139.0803248, 'C', '神社', null),
    ('久国寺', null, '愛知県', null, 35.1893597, 136.9159781, 'C', '寺院', '久国寺（きゅうこくじ）は、愛知県名古屋市北区大杉三丁目にある曹洞宗の寺院。山号は天長山。'),
    ('姉倉比売神社', null, '富山県', null, 36.7182014, 137.166763, 'C', '神社', '姉倉比賣神社（あねくらひめじんじゃ）は、富山県富山市にある神社である。姉倉姫神社とも表記する。'),
    ('生源寺', null, '滋賀県', null, 35.0715014, 135.8704013, 'C', '寺院', '生源寺（しょうげんじ）は、滋賀県大津市坂本にある天台宗の寺院。山号は比叡山。'),
    ('四宮神社', null, '兵庫県', null, 34.6911687, 135.1818796, 'C', '神社', '四宮神社 (よのみやじんじゃ)は神戸市中央区中山手通に鎮座する神社で、生田裔神八社の1社。'),
    ('蛇池神社', null, '愛知県', null, 35.2254162, 136.9036496, 'C', '神社', null),
    ('寳田恵比寿神社', null, '東京都', null, 35.6892449, 139.776961, 'C', '神社', '宝田恵比寿神社（たからだえびすじんじゃ）は、東京都中央区日本橋本町にある神社。'),
    ('諏訪神社', null, '千葉県', '市川市', 35.7277097, 139.9181587, 'C', '神社', null),
    ('岐阜護國神社', null, '岐阜県', null, 35.437002, 136.7763516, 'C', '神社', '岐阜護國神社（ぎふごこくじんじゃ）は、岐阜県岐阜市にある神社（護國神社）である。岐阜城の築かれた金華山の北麓に鎮座する。'),
    ('一心山良翁院 境木延命地蔵尊', null, '神奈川県', null, 35.4369344, 139.5668684, 'C', '神社', '境木地蔵（さかいぎじぞう）は、神奈川県横浜市保土ケ谷区にある、地蔵菩薩を祀る仏堂。旧東海道の権太坂頂上にあり、武蔵国と相模国との国境にあたる。'),
    ('廣徳寺', null, '兵庫県', null, 34.7176996, 135.4137146, 'C', '寺院', '広徳寺（こうとくじ、旧字体：廣徳寺）は、兵庫県尼崎市寺町にある臨済宗大徳寺派の寺院。山号は瑞雲山。'),
    ('邇保姫神社', null, '広島県', null, 34.3760845, 132.4872858, 'C', '神社', null),
    ('釈迦院', null, '熊本県', '八代市泉町柿迫', 32.5650779, 130.8398335, 'C', '寺院', null),
    ('東昌寺', null, '宮城県', null, 38.2825289, 140.8639484, 'C', '寺院', '東昌寺（とうしょうじ）は、宮城県仙台市青葉区青葉町にある臨済宗東福寺派の寺院である。仙台の北山に並ぶ禅寺北山五山の一つ。'),
    ('英賀神社', null, '兵庫県', null, 34.8061535, 134.6398399, 'C', '神社', null),
    ('木曽三社神社', null, '群馬県', null, 36.4722559, 139.0457229, 'C', '神社', '木曾三社神社（きそさんしゃじんじゃ）は、群馬県渋川市北橘町下箱田にある神社。祭神は須佐之男尊、彦火々出見尊、豊玉姫尊、宇気母智神、旧社格は県社。'),
    ('為那都比古神社', null, '大阪府', null, 34.8396215, 135.4979057, 'C', '神社', null),
    ('蜂田神社', null, '大阪府', null, 34.5280758, 135.4791938, 'C', '神社', null),
    ('五穀神社', null, '福岡県', null, 33.3160505, 130.5258951, 'C', '神社', '五穀神社（ごこくじんじゃ）は、福岡県久留米市通外町58番地にある神社。豊宇気比売神（とようけひめのかみ）を主祭神とし、相殿に稲次因幡正誠公（いなつぎいなばまさざねこう）を祀る。'),
    ('高龍寺', null, '北海道', '函館市', 41.768619, 140.6996068, 'C', '寺院', null),
    ('喜福寿寺', null, '東京都', null, 35.7114429, 139.758988, 'C', '寺院', '喜福寺（きふくじ）は、東京都文京区にある曹洞宗の寺院。'),
    ('世田谷八幡宮', null, '東京都', null, 35.6487317, 139.6445543, 'C', '神社', '世田谷八幡宮（せたがやはちまんぐう）は、東京都世田谷区宮坂一丁目にある神社である。旧社格は郷社。'),
    ('三宅八幡神社', null, '京都府', null, 35.0678436, 135.7943047, 'C', '神社', '三宅八幡宮（みやけはちまんぐう）は、京都市左京区上高野三宅町にある神社。旧社格は村社。'),
    ('阿波命神社', null, '東京都', null, 34.228159, 139.1388457, 'C', '神社', null),
    ('長楽寺', null, '愛知県', null, 35.1058389, 136.9316101, 'C', '寺院', null),
    ('チュアベトナム（ベトナム寺）', null, '神奈川県', '愛川町', 35.5422248, 139.2627465, 'C', '寺院', 'チュアベトナム（ベトナム語：Chùa Việt Nam / 𫴶越南）は、神奈川県愛甲郡愛川町にあるベトナム仏教の寺院。'),
    ('飯野八幡宮', null, '福島県', null, 37.0603435, 140.882108, 'C', '神社', null),
    ('竹林院', null, '奈良県', null, 34.3602687, 135.862857, 'C', '寺院', null),
    ('下立松原神社', null, '千葉県', '南房総市', 34.9152341, 139.8677204, 'C', '神社', '下立松原神社（しもたてまつばらじんじゃ）は、千葉県南房総市にある神社である。
同名社が旧白浜町と旧千倉町に2社ある。'),
    ('天津神明宮', null, '千葉県', '鴨川市', 35.1288608, 140.1713277, 'C', '神社', '天津神明宮（あまつしんめいぐう）は、千葉県鴨川市天津（安房国長狭郡）にある神社。旧社格は郷社。'),
    ('第07番札所 十楽寺', null, '徳島県', '阿波市', 34.1206876, 134.3780307, 'C', '寺院', '十楽寺（じゅうらくじ）は徳島県阿波市土成町高尾法教田にある高野山真言宗の寺院。光明山（こうみょうざん）、蓮華院（れんげいん）と号す。'),
    ('一行院 千日谷会堂', null, '東京都', '新宿区', 35.6794899, 139.7204556, 'C', '寺院', '一行院（いちぎょういん）は、東京都新宿区南元町にある浄土宗の寺院。山号は永固山（えいこざん）、本尊は阿弥陀如来。'),
    ('龍雲寺', null, '静岡県', null, 34.702475, 137.6882381, 'C', '寺院', null),
    ('六所神社', null, '千葉県', null, 35.7366079, 139.917038, 'C', '神社', '六所神社（ろくしょじんじゃ）は、千葉県市川市須和田にある神社。下総国総社で、旧社格は村社。'),
    ('山崎聖天(観音寺)', null, '京都府', null, 34.898062, 135.6821534, 'C', '寺院', '山崎聖天（やまざきしょうてん）は、京都府乙訓郡大山崎町にある真言宗系単立の寺院。山号は妙音山。'),
    ('西福寺', null, '京都府', null, 34.9978146, 135.773618, 'C', '寺院', null),
    ('大物主神社', null, '兵庫県', null, 34.7151999, 135.4251534, 'C', '神社', '大物主神社（おおものぬしじんじゃ）は、兵庫県尼崎市にある神社。旧大物町（現・大物町二丁目）・大物村（現・東大物町付近）における、地域住民の氏神として信仰されている。'),
    ('宇夫階神社', null, '香川県', null, 34.3081615, 133.8206329, 'C', '神社', '宇夫階神社（うぶしなじんじゃ）は、香川県綾歌郡宇多津町にある神社である。祭神は大己貴命（おおなむちのみこと）
。'),
    ('妙光寺', null, '東京都', null, 35.613786, 139.7306171, 'C', '寺院', '妙光寺（みょうこうじ）は、東京都品川区に所在する日蓮正宗の寺院。山号は高照山（こうしょうさん）。'),
    ('唱導寺', null, '神奈川県', null, 35.3933144, 139.5845073, 'C', '寺院', '唱導寺（しょうどうじ）は、神奈川県横浜市港南区日野中央一丁目にある日蓮宗の寺院である。山号は延宝山。'),
    ('北海道神宮頓宮', null, '北海道', '札幌市', 43.0599769, 141.3614254, 'C', '神社', '北海道神宮頓宮（ほっかいどうじんぐう とんぐう）は、北海道札幌市中央区南2条東3丁目に所在する神社。北海道神宮の境外末社であり、「頓宮」とは「仮の宮」を意味する。'),
    ('本隆寺', null, '京都府', null, 35.0317811, 135.7464664, 'C', '寺院', '本隆寺（ほんりゅうじ）は、京都市上京区にある法華宗真門流の総本山の寺院。山号は慧光山。'),
    ('八幡八雲神社', null, '東京都', null, 35.6612837, 139.3354019, 'C', '神社', '八幡八雲神社（はちまんやくもじんじゃ）は、東京都八王子市元横山町にある神社。八幡神社（八幡宮）と八雲神社（天王宮）とを合祀したもので、誉田別尊（応神天皇）と素盞鳴尊を祭神とする。'),
    ('玉村八幡宮', null, '群馬県', null, 36.3048419, 139.1085829, 'C', '神社', '玉村八幡宮（たまむらはちまんぐう）は、群馬県佐波郡玉村町にある神社。本殿が国の重要文化財に指定されている。'),
    ('狭山神社', null, '大阪府', null, 34.494827, 135.557119, 'C', '神社', '狭山神社（さやまじんじゃ）は、大阪府大阪狭山市の狭山池の近くにある神社。式内社で、旧社格は郷社。'),
    ('淵神社', null, '長崎県', null, 32.7582456, 129.8595806, 'C', '神社', '淵神社（ふちじんじゃ）は、長崎県長崎市淵町にある神社である。旧社格は県社。'),
    ('早馬神社', null, '宮城県', null, 38.9029336, 141.6383372, 'C', '神社', '早馬神社（はやまじんじゃ）は、宮城県気仙沼市唐桑町宿地区にある神社である。鎌倉幕府御家人梶原景時の兄、梶原景実（専光房良暹）が創建、代々梶原氏が祭祀を司る。'),
    ('浪分神社', null, '宮城県', null, 38.235294, 140.9276312, 'C', '神社', '浪分神社（なみわけじんじゃ）は、宮城県仙台市若林区にある神社である。旧社格は村社。'),
    ('白幡天神社', null, '千葉県', '市川市', 35.7287048, 139.9267445, 'C', '神社', '白幡天神社（しらはたてんじんしゃ、しらはたてんじんじゃ）は千葉県市川市菅野にある神社。'),
    ('唐津神社', null, '佐賀県', null, 33.4519686, 129.9695731, 'C', '神社', '唐津神社（からつじんじゃ）は、佐賀県唐津市南城内にある神社である。古くは「唐津大明神 （からつだいみょうじん）」と称した。'),
    ('有間神社', null, '兵庫県', null, 34.8140814, 135.2192247, 'C', '神社', '有間神社（ありまじんじゃ）は、兵庫県神戸市北区有野町にある神社。式内社で、旧社格は郷社。'),
    ('伊和志津神社', null, '兵庫県', null, 34.8000185, 135.3533716, 'C', '神社', '伊和志津神社（いわしづじんじゃ）は、兵庫県宝塚市伊孑志にある神社。延喜式神名帳の式内大社（論社）。'),
    ('潮田神社', null, '神奈川県', null, 35.5043901, 139.6888669, 'C', '神社', '潮田神社（うしおだじんじゃ）とは、神奈川県横浜市鶴見区潮田町にある神社。'),
    ('本山寺', null, '大阪府', null, 34.9173382, 135.6127308, 'C', '寺院', '本山寺（ほんざんじ）は、大阪府高槻市にある天台宗の寺院。山号は北山。'),
    ('矢宮神社', null, '和歌山県', null, 34.1988878, 135.1669735, 'C', '神社', '矢宮神社（やのみやじんじゃ）は、和歌山県和歌山市内に鎮座する神社である。'),
    ('南蔵院', null, '東京都', null, 35.7312219, 139.6463653, 'C', '寺院', '南蔵院（なんぞういん）は、東京都練馬区中村にある真言宗豊山派の寺院。正式には瑠璃光山 南蔵院 医王寺（るりこうざん なんぞういん いおうじ）である。'),
    ('柴又八幡神社', null, '東京都', null, 35.7582234, 139.8750755, 'C', '神社', '柴又八幡神社古墳（しばまたはちまんじんじゃこふん）は、東京都葛飾区柴又にあった古墳。形状は前方後円墳。'),
    ('厳原八幡宮神社', null, '長崎県', null, 34.2064148, 129.2892109, 'C', '神社', '厳原八幡宮神社（いづはらはちまんぐうじんじゃ）は、長崎県対馬市厳原町中村にある神社。対馬国の一宮(論社)。'),
    ('成仏寺', null, '神奈川県', null, 35.4745506, 139.6318503, 'C', '寺院', '成仏寺（じょうぶつじ）、山号は正覚山（しょうがくざん）、院号は法雨院（ほうういん）。'),
    ('大池寺', null, '滋賀県', null, 34.9832894, 136.1718545, 'C', '寺院', '大池寺（だいちじ）は、滋賀県甲賀市水口町にある臨済宗妙心寺派の寺院。山号は龍護山。'),
    ('杉山神社', null, '神奈川県', null, 35.5486891, 139.5730156, 'C', '神社', '杉山神社（すぎやまじんじゃ）は神奈川県横浜市都筑区にて、都筑中央公園東端の高台に鎮座している神社。'),
    ('小塔院', null, '奈良県', null, 34.6762953, 135.8293549, 'C', '寺院', '小塔院（しょうとういん）は、奈良県奈良市にある真言律宗の寺院。本尊は虚空蔵菩薩。'),
    ('宗三寺', null, '神奈川県', null, 35.5327358, 139.7016497, 'C', '寺院', '宗三寺（そうさんじ）は、神奈川県川崎市川崎区にある曹洞宗の寺院。'),
    ('伊河麻神社', null, '静岡県', null, 34.9665944, 138.3898779, 'C', '神社', '伊河麻神社（いかまじんじゃ）は、静岡県静岡市駿河区にある神社。旧駿河国「五宮」の内の四之宮。'),
    ('清瀧寺', null, '静岡県', null, 34.8654748, 137.8135313, 'C', '寺院', '清瀧寺（せいりゅうじ）は、静岡県浜松市天竜区にある浄土宗知恩院の末寺。山号は信康山。'),
    ('出世稲荷神社', null, '京都府', null, 35.1163675, 135.8317959, 'C', '神社', '出世稲荷神社（しゅっせいなりじんじゃ）は、京都市左京区にある神社である。宇迦之御魂命（稲荷神）を祭神とする。'),
    ('昆陽神社', null, '千葉県', null, 35.6611283, 140.0549232, 'C', '神社', '昆陽神社 (こんようじんじゃ)は、千葉市花見川区幕張町にある神社。'),
    ('作楽神社', null, '岡山県', null, 35.0621402, 133.9431378, 'C', '神社', '作楽神社（さくらじんじゃ）は、岡山県津山市神戸にある神社である。'),
    ('仙岳院', null, '宮城県', null, 38.2783319, 140.8843269, 'C', '寺院', '仙岳院（せんがくいん）は、宮城県仙台市青葉区東照宮にある、仙台藩第2代藩主・伊達忠宗が開基した天台宗・康国寺の塔頭寺院。仙台東照宮および平泉・中尊寺の別当寺。'),
    ('鶴満寺', null, '大阪府', null, 34.7107994, 135.5163452, 'C', '寺院', null),
    ('和田稲荷神社', null, '東京都', null, 35.7420182, 139.6075201, 'C', '神社', '和田稲荷神社（わだいなりじんじゃ）は、東京都練馬区石神井町にある稲荷神社。登記上の宗教法人名称は稲荷神社（いなりじんじゃ）。'),
    ('柴籬神社', null, '大阪府', null, 34.5718351, 135.5597588, 'C', '神社', '柴籬神社（しばがきじんじゃ）は、大阪府松原市上田にある神社。旧社格は村社。'),
    ('宮古神社', null, '沖縄県', null, 24.8076966, 125.2805014, 'C', '神社', '宮古神社（みやこじんじゃ）は、沖縄県宮古島市に鎮座する神社である。日本最南端の神社である。'),
    ('千光寺', null, '奈良県', null, 34.6558764, 135.6825511, 'C', '寺院', '千光寺（せんこうじ）は、奈良県生駒郡平群町にある真言宗醍醐派の寺院。山号は鳴川山。'),
    ('積川神社', null, '大阪府', null, 34.4250737, 135.4393373, 'C', '神社', null),
    ('御穂鹿嶋神社', null, '東京都', null, 35.6469908, 139.7491985, 'C', '神社', '御穂鹿嶋神社（みほかしまじんじゃ）は、東京都港区芝4丁目にある神社。
御穂神社と付近にあった鹿嶋神社を2004年（平成16年）に合祀した。'),
    ('兵庫縣姫路護國神社', null, '兵庫県', null, 34.8357086, 134.6946079, 'C', '神社', '兵庫縣姫路護國神社（ひょうごけんひめじごこくじんじゃ）は、兵庫県姫路市にある護国神社。兵庫県西部地区出身（播州・但馬地区十二市十五郡）の戦没者56988柱を祀る。'),
    ('藤次寺', null, '大阪府', null, 34.6661169, 135.5152801, 'C', '寺院', null),
    ('聖武天皇社', null, '三重県', null, 35.0099148, 136.655039, 'C', '神社', '聖武天皇社（しょうむてんのうしゃ）は、三重県四日市市松原町に所在する神社。鎌倉時代に創建された松原地区の氏子大社であり、氏神として聖武天皇を祀っている。'),
    ('本願寺広島別院', null, '広島県', null, 34.4042073, 132.4504289, 'C', '寺院', '本願寺広島別院（ほんがんじひろしまべついん）は、広島県広島市中区寺町にある浄土真宗本願寺派の寺院。旧安芸国の安芸門徒と呼ばれる浄土真宗門徒の活動の中心寺院である。'),
    ('妙伝寺', null, '京都府', null, 35.0132496, 135.7787273, 'C', '寺院', '妙傳寺、妙伝寺（みょうでんじ）は、京都府京都市左京区北門前町にある、日蓮宗の本山（由緒寺院）。山号は法鏡山。'),
    ('遣迎院', null, '京都府', null, 35.0538988, 135.7315777, 'C', '寺院', null),
    ('諏訪神社', null, '千葉県', '流山流山市', 35.8688516, 139.9352574, 'C', '神社', null),
    ('姫島神社', null, '大阪府', null, 34.7044256, 135.4531606, 'C', '神社', '姫嶋神社（ひめじまじんじゃ）は大阪市西淀川区姫島に鎮座する神社。'),
    ('成願寺', null, '愛知県', null, 35.2147973, 136.9161917, 'C', '寺院', '成願寺（じょうがんじ）は、愛知県名古屋市北区成願寺二丁目にある天台宗の寺院。'),
