    ('木母寺', null, '東京都', null, 35.733987, 139.8143173, 'C', '寺院', '木母寺（もくぼじ）は、東京都墨田区にある天台宗の寺院。'),
    ('高浜神社', null, '大阪府', '吹田市', 34.758669, 135.5270466, 'C', '神社', null),
    ('倭文神社', null, '群馬県', null, 36.3111493, 139.1514457, 'C', '神社', '倭文神社（しどりじんじゃ）は、群馬県伊勢崎市東上之宮町にある神社。式内社、上野国九宮。'),
    ('中院', null, '埼玉県', null, 35.914847, 139.490399, 'C', '寺院', '中院（なかいん）は、埼玉県川越市小仙波町にある天台宗の寺院である。山号は星野山。'),
    ('立木山寺', null, '滋賀県', null, 34.9178658, 135.9100849, 'C', '寺院', '安養寺（あんようじ）は、滋賀県大津市にある浄土宗の寺院。山号は立木山。'),
    ('住吉神社', null, '兵庫県', null, 34.9353583, 134.8286638, 'C', '神社', '住吉神社（すみよしじんじゃ）は、兵庫県加西市にある神社。酒見大明神、住吉酒見社、住吉酒見神社とも。'),
    ('薭田神社', null, '東京都', '大田区', 35.5645732, 139.7227438, 'C', '神社', null),
