    ('水火天満宮', null, '京都府', null, 35.0362791, 135.7519172, 'C', '神社', '水火天満宮（すいかてんまんぐう）は、京都市上京区にある神社。旧社格は村社。'),
    ('満願寺', null, '京都府', null, 35.0147459, 135.7866521, 'C', '寺院', '満願寺（まんがんじ）は、京都府京都市左京区にある日蓮宗の寺院。山号は示現山（じげんざん）。'),
    ('鹿島御児神社', null, '宮城県', null, 38.4240368, 141.3081781, 'C', '神社', null),
    ('諏訪神社', null, '大阪府', 'Osaka', 34.6840495, 135.5637716, 'C', '神社', null),
    ('奥氷川神社', null, '東京都', '奥多摩町', 35.8076832, 139.0969785, 'C', '神社', '奥氷川神社（おくひかわじんじゃ）は、東京都西多摩郡奥多摩町にある神社。'),
    ('碑文谷八幡宮', null, '東京都', '目黒区', 35.6174467, 139.686146, 'C', '神社', null),
    ('西國寺', null, '広島県', null, 34.4153961, 133.2031888, 'C', '寺院', '西國寺（さいこくじ）は広島県尾道市にある寺院。真言宗醍醐派大本山である。'),
    ('建治寺', null, '徳島県', '徳島市', 34.0277685, 134.4287749, 'C', '寺院', '建治寺（こんじじ）は、徳島県徳島市入田町金治の西龍王山にある東寺真言宗の寺院。大滝山宝珠院と号す。'),
    ('大綱大神金比羅神社', null, '神奈川県', null, 35.4709145, 139.6250715, 'C', '神社', '大綱金刀比羅神社（おおつなことひらじんじゃ）は、神奈川県横浜市神奈川区台町にある神社。'),
    ('転法輪寺', null, '奈良県', null, 34.4197171, 135.6719303, 'C', '寺院', null),
    ('龍神社', null, '大阪府', '大阪狭山市', 34.5056295, 135.5486143, 'C', '神社', null),
    ('麻賀多神社', null, '千葉県', '佐倉市', 35.7192874, 140.2268198, 'C', '神社', null),
    ('大悲閣山 千光寺', null, '京都府', 'Kyoto', 35.0157751, 135.6655983, 'C', '寺院', '千光寺（せんこうじ）は、京都府京都市西京区嵐山中尾下町にある黄檗宗系の単立寺院。山号は嵐山、寺号は詳しくは大悲閣千光寺と称する。'),
    ('大観音寺', null, '東京都', null, 35.6855158, 139.7824839, 'C', '寺院', '大観音寺（おおかんのんじ）は、東京都中央区にある聖観音宗の寺院。'),
    ('富岡八幡宮', null, '神奈川県', null, 35.3694586, 139.6359223, 'C', '神社', '富岡八幡宮（とみおかはちまんぐう）は、神奈川県横浜市金沢区富岡東にある神社である。旧社格は村社。'),
    ('味鋺神社', null, '愛知県', null, 35.2184858, 136.928063, 'C', '神社', '味鋺神社（あじまじんじゃ）は、愛知県名古屋市北区楠味鋺にある神社。『延喜式神名帳』の尾張国春部郡「味鋺神社」に比定される式内社。'),
    ('曽根天満宮', null, '兵庫県', null, 34.7775545, 134.7734681, 'C', '神社', '曽根天満宮（そねてんまんぐう）は、兵庫県高砂市曽根にある天満宮。秋祭りや天然記念物であった曽根の松で知られる。'),
    ('長遠寺', null, '兵庫県', null, 34.7182721, 135.4119558, 'C', '寺院', null),
    ('徳光院', null, '兵庫県', null, 34.709718, 135.1954536, 'C', '寺院', '徳光院（とっこういん）または徳光禅院（とっこうぜんいん）は、兵庫県神戸市中央区葺合町にある仏教寺院。山号は大円山、臨済宗天龍寺派。'),
    ('櫟谷宗像神社社', null, '京都府', null, 35.0114432, 135.6765675, 'C', '神社', '櫟谷宗像神社（いちたにむなかたじんじゃ/いちいだにむなかたじんじゃ）は、京都府京都市西京区嵐山中尾下町にある神社。'),
    ('斑鳩神社', null, '奈良県', null, 34.6178197, 135.7369932, 'C', '神社', '斑鳩神社（いかるがじんじゃ）は奈良県生駒郡の神社。法隆寺の北東の天満山に位置し、菅原道真を祀る。'),
    ('永安寺', null, '東京都', null, 35.6254434, 139.6094835, 'C', '寺院', '永安寺（えいあんじ）は、東京都世田谷区大蔵六丁目にある天台宗の寺院。'),
    ('大覚寺', null, '兵庫県', null, 34.7788518, 134.5860482, 'C', '寺院', '大覚寺（だいかくじ）は、兵庫県姫路市網干区にある浄土宗の寺院。山号は鶴立山。'),
    ('香取神社', null, '東京都', null, 35.7658301, 139.851226, 'C', '神社', null),
    ('円泉寺', null, '東京都', null, 35.6496754, 139.6703876, 'C', '寺院', '円泉寺（えんせんじ）は、東京都世田谷区太子堂三丁目にある真言宗豊山派の仏教寺院。圓泉寺とも表記される。'),
    ('日枝神社', null, '岐阜県', null, 36.1329045, 137.2608849, 'C', '神社', '日枝神社（ひえじんじゃ）は、岐阜県高山市にある神社である。別名飛騨山王宮 日枝神社（ひださんのうぐう ひえじんじゃ）。'),
    ('尾陽神社', null, '愛知県', null, 35.1479205, 136.9214543, 'C', '神社', '尾陽神社（びようじんじゃ）は、愛知県名古屋市昭和区御器所に鎮座する神社。'),
    ('白山神社', null, '千葉県', null, 35.320471, 140.057927, 'C', '神社', '白山神社（はくさんじんじゃ）は、千葉県君津市俵田にある神社。旧社格は郷社。'),
    ('志貴縣主神社', null, '大阪府', null, 34.5764191, 135.6183708, 'C', '神社', '志貴県主神社（しきあがたぬしじんじゃ）は、大阪府藤井寺市にある神社である。式内社、河内国総社で、旧社格は村社。'),
    ('瑞丘八幡神社', null, '兵庫県', null, 34.6349855, 135.0560392, 'C', '神社', null),
    ('弥刀神社', null, '大阪府', '東大阪市', 34.6462234, 135.5808749, 'C', '神社', '彌刀神社（弥刀神社、みとじんじゃ）は大阪府東大阪市近江堂一丁目にある神社。'),
    ('霊鑑寺', null, '京都府', null, 35.0208443, 135.7964645, 'C', '寺院', null),
    ('道場寺', null, '東京都', null, 35.7364473, 139.5988676, 'C', '寺院', null),
    ('佐保神社', null, '兵庫県', '加東市', 34.9161912, 134.9645367, 'C', '神社', '佐保神社（さほじんじゃ）は、兵庫県加東市にある神社。旧称、坂合神社。'),
    ('勝林寺', null, '東京都', null, 35.7404995, 139.7380283, 'C', '寺院', '勝林寺（しょうりんじ）は、東京都豊島区にある臨済宗妙心寺派の寺院。'),
    ('世尊院正覚寺', null, '東京都', null, 35.7067972, 139.6365737, 'C', '寺院', '世尊院（せそんいん）は、東京都杉並区阿佐谷北にある真言宗豊山派の寺院。山号は阿谷山。'),
    ('雲興寺', null, '愛知県', '瀬戸市', 35.2226547, 137.1448044, 'C', '寺院', null),
    ('清白寺', null, '山梨県', null, 35.694058, 138.7081246, 'C', '寺院', '清白寺（せいはくじ）は、山梨県山梨市にある寺院。宗派は臨済宗妙心寺派、山号は海涌山（かいゆうざん）、本尊は釈迦如来である。'),
    ('健御名方富命彦神別神社', null, '長野県', null, 36.661361, 138.1919642, 'C', '神社', '健御名方富命彦神別神社（たけみなかたとみのみことひこかみわけじんじゃ）は、長野県長野市長野にある神社。式内社（名神大社）論社で、旧社格は県社。'),
