    ('高木神社', null, '東京都', null, 35.7147567, 139.8151922, 'C', '神社', null),
    ('照栄院', null, '東京都', null, 35.5760735, 139.7066487, 'C', '寺院', '照栄院（しょうえいいん）は、東京都大田区池上にある日蓮宗の寺院。'),
    ('長泉寺', null, '東京都', null, 35.6661191, 139.7028014, 'C', '寺院', null),
    ('勝持寺 (花の寺)', null, '京都府', null, 34.9607101, 135.6517813, 'C', '寺院', '勝持寺（しょうじじ）は、京都市西京区大原野南春日町にある天台宗の寺院。山号は小塩山。'),
    ('岡田鴨神社', null, '京都府', null, 34.7615288, 135.8763831, 'C', '神社', '岡田鴨神社（おかだかもじんじゃ）は、京都府木津川市加茂町北にある神社。式内社（式内大社）で、旧社格は郷社。'),
    ('清巖寺', null, '栃木県', null, 36.5620489, 139.8936345, 'C', '寺院', '清巌寺（せいがんじ）は、栃木県宇都宮市大通り五丁目にある浄土宗の寺院。山号は芳宮山。'),
    ('清水寺', null, '福岡県', null, 33.1510535, 130.5254128, 'C', '寺院', '清水寺（きよみずでら）は福岡県みやま市瀬高町本吉にある天台宗の寺院。山号は本吉山（もとよしざん）。'),
