    ('上宮寺', null, '愛知県', null, 34.9422554, 137.1239703, 'C', '寺院', '上宮寺（じょうぐうじ）は、愛知県岡崎市上佐々木町にある寺。本證寺（安城市野寺町）、勝鬘寺（岡崎市針崎町）とともに、三河一向一揆を主導した「三河三ヶ寺」のひとつ。'),
    ('称名寺', null, '兵庫県', null, 34.7685642, 134.8305183, 'C', '寺院', null),
    ('保呂羽山波宇志別神社', null, '秋田県', null, 39.3711219, 140.3103064, 'C', '神社', '保呂羽山波宇志別神社（ほろわさんはうしわけじんじゃ）は、秋田県横手市大森町八沢木の保呂羽山山腹にある神社。式内小社「出羽国平鹿郡 波宇志別神社」、旧社格は県社。'),
    ('長瀧寺', null, '岐阜県', '郡上市', 35.920282, 136.8306022, 'C', '寺院', null),
