    ('頼政神社', null, '茨城県', null, 36.1953984, 139.6957091, 'C', '神社', null),
    ('六甲八幡神社', null, '兵庫県', null, 34.7191805, 135.2350205, 'C', '神社', '六甲八幡神社（ろっこうやはたじんじゃ）は、兵庫県神戸市灘区八幡町（菟原郡八幡村）にある神社。旧社格は県社。'),
    ('正寿院', null, '京都府', null, 34.8498602, 135.9207734, 'C', '寺院', '正寿院（しょうじゅいん）は、京都府綴喜郡宇治田原町にある高野山真言宗の寺院。創建は800年前、鎌倉時代に飯尾教寺の塔頭寺院として建立。'),
    ('氷川神社', null, '東京都', null, 35.7023244, 139.6829679, 'C', '神社', '氷川神社 （ひかわじんじゃ）は東京都中野区東中野一丁目にある神社。旧中野村の総鎮守社。'),
    ('船橋東照宮', null, '千葉県', null, 35.6988674, 139.9892836, 'C', '神社', null),
