    ('若山神社', null, '大阪府', null, 34.8916193, 135.6544811, 'C', '神社', null),
    ('水主神社', null, '京都府', '城陽市', 34.8433299, 135.7616806, 'C', '神社', '水主神社（みずしじんじゃ）は、京都府城陽市水主宮馬場に鎮座する神社である。式内大社で、旧社格は府社。'),
    ('飽富神社', null, '千葉県', null, 35.4208163, 139.9852362, 'C', '神社', null),
    ('一蓮寺', null, '山梨県', null, 35.6520223, 138.5712603, 'C', '寺院', '一蓮寺（いちれんじ）は、山梨県甲府市太田町に所在する寺院。時宗系寺院（単立）で、山号は稲久山。'),
    ('出水神社', null, '熊本県', null, 32.7918944, 130.7343299, 'C', '神社', '出水神社（いずみじんじゃ）は、熊本県熊本市中央区の水前寺成趣園内にある神社である。熊本藩歴代藩主を祀る神社として、明治時代にかつての家臣らによって創建された。'),
    ('坂東30番 平野山 高蔵寺 (高倉観音）', null, '千葉県', '木更津市', 35.3388053, 139.9944496, 'C', '寺院', null),
    ('戒行寺', null, '東京都', null, 35.6843031, 139.723972, 'C', '寺院', '戒行寺（かいぎょうじ）は、東京都新宿区にある日蓮宗の寺院。'),
    ('巨椋神社', null, '京都府', null, 34.8981181, 135.7847966, 'C', '神社', '巨椋神社（おぐらじんじゃ）は、京都府宇治市小倉町寺内にある神社である。式内小社で、旧社格は村社。'),
    ('永福寺', null, '東京都', null, 35.6722482, 139.6441076, 'C', '寺院', '永福寺（えいふくじ）は、東京都杉並区にある曹洞宗の寺院。'),
    ('総禅寺', null, '東京都', null, 35.7414861, 139.732701, 'C', '寺院', '摠禅寺（そうぜんじ）は、東京都豊島区にある曹洞宗の寺院。なお「摠」の字が常用漢字外であることから、常用漢字の「総」を用いて「総禅寺」と書かれることもある。'),
    ('本光寺', null, '東京都', null, 35.655056, 139.7295218, 'C', '寺院', '本光寺（ほんこうじ）は、東京都港区元麻布にある、法華宗陣門流の寺院。新潟県三条市西本成寺にある法華宗陣門流の総本山である長久山本成寺の末寺である。'),
    ('本願寺金沢別院', null, '石川県', null, 36.5774377, 136.6557513, 'C', '寺院', '本願寺金沢別院（ほんがんじかなざわべついん）は金沢市笠市町にある浄土真宗本願寺派（西本願寺）の別院である。'),
    ('香林寺', null, '神奈川県', '川崎市', 35.6161914, 139.5135251, 'C', '寺院', null),
    ('岡田国神社', null, '京都府', null, 34.7295538, 135.8245007, 'C', '神社', '岡田国神社（おかだくにじんじゃ）は、京都府木津川市木津大谷にある神社。式内社（式内大社）で、旧社格は郷社。'),
    ('法善寺', null, '山梨県', null, 35.603176, 138.4852427, 'C', '寺院', '法善寺（ほうぜんじ）は、山梨県南アルプス市加賀美にある寺。高野山真言宗寺院。'),
    ('春日神社', null, '大分県', null, 33.2449945, 131.5982246, 'C', '神社', '春日神社（かすがじんじゃ）は、大分県大分市にある神社である。旧社格は県社で、現在は神社本庁の別表神社。'),
    ('龍泉寺', null, '大阪府', null, 34.4616446, 135.5977351, 'C', '寺院', null),
    ('筑摩神社', null, '滋賀県', null, 35.3164156, 136.2666133, 'C', '神社', '筑摩神社（ちくまじんじゃ）は滋賀県米原市にある神社。国史見在社で旧県社。'),
    ('西寿寺', null, '京都府', null, 35.0339328, 135.7065737, 'C', '寺院', null),
    ('佐良志奈神社', null, '長野県', null, 36.4873422, 138.1418636, 'C', '神社', '佐良志奈神社（さらしなじんじゃ）は長野県千曲市にある神社。『延喜式神名帳』に記載される式内社である。'),
    ('金山神社', null, '愛知県', null, 35.140534, 136.9005107, 'C', '神社', null),
    ('榧寺', null, '東京都', null, 35.7052583, 139.7922683, 'C', '寺院', '榧寺（かやでら）は、東京都台東区にある浄土宗の寺院。'),
    ('川口神社', null, '埼玉県', '川口市', 35.798148, 139.7227169, 'C', '神社', '川口神社（かわぐちじんじゃ）は、埼玉県川口市にある神社である。旧社格は県社。'),
    ('三明寺', null, '愛知県', null, 34.8208868, 137.3992357, 'C', '寺院', '三明寺（さんみょうじ）は、愛知県豊川市豊川町波通にある曹洞宗の寺院。豊川弁財天（とよかわべんざいてん）の通称で知られる。'),
    ('若桜神社', null, '鳥取県', null, 35.3430416, 134.3918097, 'C', '神社', '若桜神社（わかさじんじゃ）は鳥取県八頭郡若桜町にある神社。旧・社格は郷社。'),
    ('坂戸神社', null, '千葉県', null, 35.425944, 139.9547594, 'C', '神社', '坂戸神社（さかとじんじゃ）は、千葉県袖ケ浦市の神社。'),
    ('坂東報恩寺', null, '東京都', null, 35.7129523, 139.7848199, 'C', '寺院', '報恩寺（ほうおんじ）は、東京都台東区東上野にある真宗大谷派の寺院。「坂東報恩寺」と通称される。'),
    ('国清寺', null, '岡山県', null, 34.6568429, 133.9367893, 'C', '寺院', '国清寺（こくせいじ）は岡山県岡山市中区にある臨済宗妙心寺派の寺院。山号は萬歳山。'),
    ('蹉跎神社', null, '大阪府', null, 34.7927414, 135.6330126, 'C', '神社', null),
    ('西澄寺', null, '東京都', null, 35.6396089, 139.6778634, 'C', '寺院', null),
    ('善養寺', null, '東京都', null, 35.7278655, 139.8935214, 'C', '寺院', '善養寺（ぜんようじ）は、東京都江戸川区東小岩にある寺院。真言宗豊山派に属し、大永7年（1527年）の創建と伝わる。'),
    ('圓頓寺', null, '愛知県', '名古屋市', 35.1765669, 136.8908345, 'C', '寺院', '圓頓寺（えんどんじ）は愛知県名古屋市西区那古野一丁目11番7号にある日蓮宗の寺院。山号は長久山（ちょうきゅうさん）。'),
    ('妙立寺', null, '静岡県', null, 34.7188927, 137.5258791, 'C', '寺院', '妙立寺（みょうりゅうじ）は、静岡県湖西市吉美2745番地にある日蓮宗の本山（由緒寺院）。山号は延兼山。'),
    ('阿蘇神社', null, '東京都', null, 35.7628821, 139.297963, 'C', '神社', null),
    ('興徳寺', null, '福島県', null, 37.4963665, 139.9290001, 'C', '寺院', null),
    ('最勝寺', null, '東京都', null, 35.7133941, 139.68526, 'C', '寺院', '最勝寺（さいしょうじ）は東京都新宿区上落合3の4の12にある真言宗豊山派の寺院。本尊は釈迦牟尼如来。'),
    ('松平西福寺', null, '東京都', null, 35.703504, 139.7887341, 'C', '寺院', null),
    ('平群坐紀氏神社', null, '奈良県', null, 34.6356958, 135.7034986, 'C', '神社', '平群坐紀氏神社（へぐりにますきしじんじゃ/へぐりにますきのうじじんじゃ/へぐりにいますきうじのじんじや）は、奈良県生駒郡平群町上庄にある神社。式内社（名神大社）で、旧社格は村社。'),
    ('蔵前神社', null, '東京都', '台東区', 35.7047922, 139.7918332, 'C', '神社', '藏前神社（くらまえじんじゃ）は、東京都台東区蔵前にある神社。'),
    ('与楽寺', null, '東京都', null, 35.7346041, 139.7615617, 'C', '寺院', '与楽寺（よらくじ）は、東京都北区田端1丁目にある真言宗豊山派の寺院。'),
    ('常高寺', null, '福井県', null, 35.4896373, 135.7347618, 'C', '寺院', '常高寺（じょうこうじ）は、福井県小浜市小浜浅間にある臨済宗妙心寺派の寺院。山号は凌霄山。'),
    ('清瀧神社', null, '千葉県', null, 35.6621431, 139.8912165, 'C', '神社', null),
    ('廣田神社', null, '青森県', null, 40.8224856, 140.7426408, 'C', '神社', '廣田神社（ひろたじんじゃ）は、青森県青森市長島にある神社。
JR青森駅の東方、国道4号沿いに青森市役所に向かう途中、青森地方裁判所の南向かいに鎮座している。'),
    ('円成院', null, '東京都', null, 35.7293258, 139.5142083, 'C', '寺院', '円成院（えんじょういん）は、東京都小平市にある黄檗宗の寺院。'),
    ('御幸森天神宮', null, '大阪府', null, 34.6602351, 135.5344659, 'C', '神社', '御幸森天神宮（みゆきもりてんじんぐう）は、大阪市生野区桃谷3丁目（旧摂津国東生郡猪飼野村）（明治時代は天王寺村）にある神社。'),
    ('松久寺', null, '神奈川県', '鎌倉市', 35.3174712, 139.5732463, 'C', '寺院', '松久寺（しょうきゅうじ）は、神奈川県鎌倉市にある曹洞宗の寺院。'),
    ('熊野神社', null, '東京都', null, 35.6106401, 139.6688923, 'C', '神社', null),
    ('多賀神社', null, '宮城県', '仙台市', 38.217988, 140.8595395, 'C', '神社', '多賀神社（たがじんじゃ）は、宮城県旧名取郡にある神社である。'),
    ('廣瀬神社', null, '静岡県', null, 35.0106057, 138.9461682, 'C', '神社', '広瀬神社（ひろせじんじゃ）は、静岡県伊豆の国市田京にある神社。式内社で、旧社格は県社。'),
    ('東禪寺', null, '東京都', null, 35.7242048, 139.8001649, 'C', '寺院', '東禅寺（とうぜんじ）は、東京都台東区にある曹洞宗の寺院。'),
    ('廣園寺', null, '東京都', '八王子市', 35.6468824, 139.3165108, 'C', '寺院', '広園寺（こうおんじ、旧字体：廣園寺）は、東京都八王子市にある臨済宗南禅寺派の寺院である。山号は兜卒山（とそつざん）。'),
    ('鹿島神社', null, '神奈川県', null, 35.2822234, 139.6508827, 'C', '神社', null),
    ('須賀神社', null, '京都府', null, 35.0183547, 135.7815274, 'C', '神社', null),
    ('西方寺', null, '東京都', null, 35.7428131, 139.7299358, 'C', '寺院', null),
    ('興禅寺', null, '長野県', null, 35.8532953, 137.7029888, 'C', '寺院', null),
    ('金峯神社', null, '山形県', null, 38.682298, 139.7982439, 'C', '神社', null),
    ('網走神社', null, '北海道', '網走市', 44.015745, 144.2702362, 'C', '神社', '網走神社（あばしりじんじゃ）は、北海道網走市にある神社である。旧社格は県社。'),
    ('佐貫観音院', null, '栃木県', null, 36.7497109, 139.7991996, 'C', '寺院', '佐貫観音院（さぬきかんのんいん）は、栃木県塩谷郡塩谷町佐貫にある真言宗智山派の寺院である。'),
    ('高部屋神社', null, '神奈川県', '伊勢原市', 35.4063095, 139.3204181, 'C', '神社', null),
    ('徳願寺', null, '千葉県', null, 35.6954558, 139.9219898, 'C', '寺院', '徳願寺（とくがんじ）は、千葉県市川市本行徳にある浄土宗の寺院。山号は海蔵山。'),
    ('浅間山 慈恵院', null, '東京都', null, 35.6811436, 139.4982346, 'C', '寺院', '慈恵院（じけいいん）は、東京都府中市浅間町二丁目にある臨済宗の寺院。山号は浅間山（せんげんざん）。'),
    ('光照寺', null, '東京都', null, 35.700505, 139.738053, 'C', '寺院', '光照寺（こうしょうじ）は、東京都新宿区袋町にある浄土宗の寺院。増上寺の末寺で樹王山 正覚院 光照寺という。'),
    ('宗像神社', null, '京都府', null, 35.0189415, 135.7612907, 'C', '神社', '宗像神社（むなかたじんじゃ）は、京都府京都市上京区の京都御苑内にある神社。国史見在社で、旧社格は府社。'),
    ('遠照寺', null, '長野県', null, 35.8456773, 138.1006758, 'C', '寺院', null),
    ('上野國一社八幡宮', null, '群馬県', null, 36.3407389, 138.9490196, 'C', '神社', '上野國一社八幡宮（こうずけのくにいっしゃはちまんぐう）は、群馬県高崎市八幡町にある神社である。旧社格は郷社。'),
    ('十念寺', null, '京都府', null, 35.0330405, 135.7668843, 'C', '寺院', '十念寺（じゅうねんじ）は、京都市上京区にある西山浄土宗の寺院。山号は華宮山。'),
    ('朝日神明社', null, '大阪府', null, 34.6796272, 135.4522815, 'C', '神社', '朝日神明社（あさひしんめいしゃ）は、大阪府大阪市此花区にある神社。別称として、逆櫓社（さかろのやしろ）。'),
    ('金澤八幡宮', null, '秋田県', null, 39.3735063, 140.5764664, 'C', '神社', null),
    ('北野神社', null, '東京都', '文京区', 35.7077915, 139.7467515, 'C', '神社', '北野神社（きたのじんじゃ）は、東京都文京区春日一丁目にある神社である。通称の牛天神（うしてんじん）としても知られる。'),
    ('本蓮寺', null, '岡山県', null, 34.616791, 134.1639587, 'C', '寺院', '本蓮寺（ほんれんじ）は、岡山県瀬戸内市牛窓町にある仏教寺院。山号は経王山、大本山本興寺末。'),
    ('春日神社', null, '東京都', null, 35.7479075, 139.6434785, 'C', '神社', '春日神社（かすがじんじゃ）は、東京都練馬区春日町にある神社。所在地の町名「春日町」は、当社に由来する。'),
    ('氷川神社', null, '東京都', null, 35.7437043, 139.7112088, 'C', '神社', null),
    ('村國真墨田神社', null, '岐阜県', null, 35.398814, 136.9417784, 'C', '神社', '村国真墨田神社（むらくにますみだじんじゃ、旧字体: 村國眞墨󠄀田神󠄀社󠄁）は、岐阜県各務原市にある神社。式内社であり、各務原市鵜沼地区の産土神とされている。'),
    ('切目神社', null, '和歌山県', null, 33.8028104, 135.2316302, 'C', '神社', '切目王子（きりめおうじ）は和歌山県日高郡印南町にある神社。九十九王子の一つで、五体王子の一社（『紀伊続風土記』）。'),
    ('諏訪神社', null, '三重県', null, 34.9681887, 136.6224792, 'C', '神社', null),
    ('一向寺', null, '栃木県', null, 36.5542572, 139.874326, 'C', '寺院', '一向寺（いっこうじ）は、栃木県宇都宮市西原二丁目にある時宗一向派の寺院である。山号は清照山。'),
    ('遠光寺', null, '山梨県', null, 35.6478414, 138.5683521, 'C', '寺院', null),
    ('重蔵神社', null, '石川県', '石川県輪島市河井町', 37.3945985, 136.9063005, 'C', '神社', null),
    ('賀来神社', null, '神奈川県', '藤沢市', 35.3217576, 139.4823167, 'C', '神社', null),
    ('屯倉神社', null, '大阪府', null, 34.5888354, 135.5551241, 'C', '神社', '屯倉神社（みやけじんじゃ）は、大阪府松原市三宅中にある神社。旧社格は村社。'),
    ('大庭神社', null, '神奈川県', null, 35.360488, 139.4585014, 'C', '神社', '大庭神社（おおばじんじゃ）とは、延長5年（927年）の『延喜式神名帳』に記載された相模国の延喜式内社十三社の内の一社（小社）であるが、二つの論社（比定社）が存在する。'),
    ('正覚寺', null, '東京都', null, 35.6412944, 139.7004073, 'C', '寺院', '正覚寺（しょうがくじ）は、東京都目黒区中目黒（もと荏原郡中目黒村）にある日蓮宗の寺院。山号は実相山。'),
    ('金澤神社', null, '石川県', null, 36.5604815, 136.6628621, 'C', '神社', null),
    ('御野縣主神社', null, '大阪府', null, 34.6346091, 135.6210405, 'C', '神社', '御野縣主神社（みのあがたぬしじんじゃ）は、大阪府八尾市にある神社。式内小社で、旧社格は村社。'),
    ('幡頭神社', null, '愛知県', '西尾市', 34.7780955, 137.0873696, 'C', '神社', '幡頭神社（はずじんじゃ）は、愛知県西尾市吉良町宮崎にある神社。式内社で、旧社格は県社。'),
    ('平林寺', null, '兵庫県', null, 34.7950793, 135.3511136, 'C', '寺院', '平林寺（へいりんじ）は、兵庫県宝塚市にある真言宗単立の寺院。武庫七寺の一つ。'),
    ('武並神社', null, '岐阜県', null, 35.4506353, 137.420821, 'C', '神社', '武並神社（たけなみじんじゃ）は、岐阜県恵那市に合計7社がある。ここでは恵那市大井町の武並神社を主に記述する。'),
    ('洲宮神社', null, '千葉県', '館山市', 34.9525773, 139.8384778, 'C', '神社', '洲宮神社（すのみやじんじゃ）は、千葉県館山市洲宮にある神社。式内社（大社）論社で、旧社格は県社。'),
    ('山科神社', null, '京都府', null, 34.9685829, 135.7955555, 'C', '神社', '山科神社（やましなじんじゃ）は、京都府京都市山科区西野山岩ヶ谷町にある神社。式内社（名神大社）で、旧社格は村社。'),
    ('宇受賀命神社', null, '島根県', null, 36.11622, 133.1089647, 'C', '神社', '宇受賀命神社（うづかみことじんじゃ）は、島根県隠岐郡海士町に鎮座する神社。式内社（名神大社）で旧社格は郷社。'),
    ('興禪寺', null, '東京都', null, 35.7244477, 139.7681036, 'C', '寺院', '興禅寺（こうぜんじ）は、東京都台東区にある臨済宗興聖寺派の寺院。山号は清徳山。'),
    ('愚渓寺', null, '岐阜県', null, 35.4358785, 137.1277903, 'C', '寺院', '愚渓寺（ぐけいじ）は、岐阜県可児郡御嵩町にある臨済宗妙心寺派の寺院。山号は大智山。'),
    ('武蔵野八幡宮', null, '東京都', null, 35.7076267, 139.5800416, 'C', '神社', '武蔵野八幡宮（むさしのはちまんぐう）は、東京都武蔵野市の神社。武蔵野吉祥七福神の寺社の一つである。'),
    ('廣瀬神社', null, '埼玉県', null, 35.8585872, 139.3892007, 'C', '神社', '広瀬神社（ひろせじんじゃ）は、埼玉県狭山市広瀬にある神社。式内社で、旧社格は県社。'),
    ('遍照院', null, '愛知県', null, 34.9956702, 137.0449692, 'C', '寺院', null),
    ('羊神社', null, '愛知県', null, 35.2074056, 136.926584, 'C', '神社', null),
    ('白雲神社', null, '京都府', null, 35.0215287, 135.7612357, 'C', '神社', '白雲神社（しらくもじんじゃ）は、京都市上京区京都御苑内にある神社。旧社格は無格社。'),
    ('秋津神社', null, '東京都', null, 35.7787186, 139.4925637, 'C', '神社', '秋津神社（あきつじんじゃ）は、東京都東村山市にある神社。祭神は日本武尊。'),
    ('別格20 大瀧寺', null, '徳島県', '美馬市', 34.1220183, 134.1274975, 'C', '寺院', '大瀧寺（おおたきじ）は徳島県美馬市脇町に所在する真言宗御室派準別格本山の寺院。福大山（ふくだいさん）、慈眼院（じげんいん）と号す。'),
    ('醫王寺', null, '東京都', null, 35.6219577, 139.6524613, 'C', '寺院', '医王寺（いおうじ）は、東京都世田谷区深沢六丁目にある真言宗智山派の寺院。ここでは医王寺と関係が深い深沢不動教会についても言及する。'),
    ('蒲田八幡神社', null, '東京都', '大田区', 35.5607381, 139.7224446, 'C', '神社', null),
    ('直指庵', null, '京都府', null, 35.0342319, 135.6773957, 'C', '寺院', '直指庵（じきしあん）は、京都市右京区にある浄土宗の寺院。山号は祥鳳山。'),
    ('悲田院', null, '京都府', null, 34.9794638, 135.7768514, 'C', '寺院', '悲田院（ひでんいん）は、京都市東山区にある真言宗泉涌寺派の寺院。泉涌寺の塔頭のひとつで、本尊は阿弥陀如来。'),
    ('門田稲荷神社', null, '栃木県', '足利市', 36.3239897, 139.4354848, 'C', '神社', '下野國一社八幡宮（しもつけのくにいっしゃはちまんぐう）は栃木県足利市八幡町にある神社である。源頼義・義家父子の創建とされる。'),
    ('渭伊神社', null, '静岡県', null, 34.8329048, 137.6636795, 'C', '神社', '渭伊神社（いいじんじゃ）は、静岡県浜松市浜名区引佐町（いなさちょう）井伊谷（いいのや）にある神社。式内社で、旧社格は郷社。'),
    ('佛向寺', null, '山形県', null, 38.353872, 140.3727768, 'C', '寺院', '佛向寺（ぶっこうじ）は、山形県天童市にある浄土宗の寺院。昭和17年（1942年）までは、時宗の中本寺(時宗宗憲並宗規及び時宗寺院名鑑)山号は宝樹山。'),
    ('佐井寺', null, '大阪府', null, 34.7834244, 135.5185813, 'C', '寺院', '佐井寺（さいでら）は、大阪府吹田市佐井寺にある真言宗の寺院。山田寺（さんでんじ）とも号する。'),
    ('秩父15番 母巣山 少林寺', null, '埼玉県', null, 35.9952331, 139.085269, 'C', '寺院', '少林寺（しょうりんじ）は、埼玉県秩父市にある臨済宗建長寺派の寺院で、山号は母巣山と号する。'),
    ('東南院', null, '奈良県', null, 34.365741, 135.861452, 'C', '寺院', '東南院（とうなんいん）は、奈良県吉野郡吉野町吉野山にある金峯山修験本宗の別格本山の寺院。山号は大峯山。'),
