    ('宿院頓宮', null, '大阪府', null, 34.5748129, 135.4725662, 'C', '神社', '宿院頓宮（しゅくいんとんぐう）は、大阪府堺市堺区にある頓宮・神社である。'),
    ('佐奈部神社', null, '大阪府', null, 34.8103077, 135.5768006, 'C', '神社', '佐奈部神社（さなべじんじゃ）は大阪府茨木市稲葉町に鎮座する神社。'),
    ('曹源寺', null, '群馬県', null, 36.3243281, 139.3867756, 'C', '寺院', '曹源寺（そうげんじ）は、群馬県太田市にある曹洞宗の寺院。'),
    ('日野神社', null, '兵庫県', null, 34.749006, 135.3704027, 'C', '神社', '日野神社（ひのじんじゃ）は、兵庫県西宮市日野町にある神社。主祭神は天照大神、他に豊受大神、春日大明神を祀る。'),
    ('菅生神社', null, '大阪府', null, 34.5272691, 135.561628, 'C', '神社', null),
