    ('出雲大社 沖縄分社', null, '沖縄県', null, 26.2300931, 127.7035543, 'C', '神社', '出雲大社沖縄分社（いずもたいしゃおきなわぶんしゃ）は沖縄県那覇市古島に鎮座している神社である。出雲大社の正式な分社であり、国内最南・西端の出雲大社の分社である。'),
    ('常福寺', null, '茨城県', null, 36.0744246, 140.1887367, 'C', '寺院', '常福寺（じょうふくじ）は、茨城県土浦市下高津にある新義真言宗の寺院である。土浦旧市街の南側に位置し、旧水戸街道の西側にほぼ隣接している。'),
    ('恵龍山 大聖寺', null, '岡山県', null, 35.0418141, 134.2827741, 'C', '寺院', '大聖寺（だいしょうじ）は岡山県美作市にある真言宗の寺院。山号は恵龍山（けいりゅうざん）。'),
    ('得浄明院', null, '京都府', null, 35.0077055, 135.7809105, 'C', '寺院', '得浄明院（とくじょうみょういん）は、京都府京都市東山区にある善光寺大本願の京都別院の尼寺である。山号は本覚山。'),
    ('桜岡大神宮', null, '宮城県', null, 38.2596692, 140.8619, 'C', '神社', '櫻岡大神宮（さくらがおかだいじんぐう）は、宮城県仙台市青葉区の西公園内にある神社である。旧社格は県社。'),
    ('観福寺', null, '千葉県', '香取市', 35.7882934, 140.5341272, 'C', '寺院', null),
    ('法園寺', null, '兵庫県', null, 34.7178613, 135.4129347, 'C', '寺院', null),
    ('大智寺', null, '埼玉県', null, 35.9673383, 139.4098462, 'C', '寺院', '大智寺（だいちじ）は、埼玉県坂戸市石井に所在する真言宗智山派の寺院。山号は龍護山。'),
    ('久久比神社', null, '兵庫県', null, 35.5570438, 134.8436584, 'C', '神社', '久久比神社（くくひじんじゃ）、兵庫県豊岡市下宮にある神社である。式内小社で、旧社格は村社。'),
    ('亀井院', null, '千葉県', null, 35.7387017, 139.9095191, 'C', '寺院', '亀井院（かめいいん）は、千葉県市川市真間四丁目にある日蓮宗の寺院である。境内には井戸がある。'),
    ('宇多須神社', null, '石川県', null, 36.5730488, 136.6681409, 'C', '神社', '宇多須神社（うたすじんじゃ）は、石川県金沢市にある神社。金沢五社（金沢市に江戸時代から鎮座する5神社の総称）のひとつ。'),
    ('良玄寺', null, '千葉県', null, 35.2808903, 140.2471613, 'C', '寺院', '良玄寺（りょうげんじ）は、千葉県夷隅郡大多喜町にある浄土宗の寺院。山号は金澤山。'),
    ('大泉寺', null, '静岡県', null, 35.142692, 138.7957991, 'C', '寺院', '大泉寺（だいせんじ）とは、静岡県沼津市東井出744、根方街道沿いにある、曹洞宗の寺院。山号は士詠山。'),
    ('雲龍寺', null, '東京都', null, 35.6411169, 139.3159383, 'C', '寺院', null),
    ('信楽寺', null, '神奈川県', null, 35.2587657, 139.6957847, 'C', '寺院', '信楽寺（しんぎょうじ）は神奈川県横須賀市大津にある浄土宗の仏教寺院である。山号は宮谷山で、正式名称は宮谷山至心院信楽寺。'),
    ('無量寺', null, '和歌山県', null, 33.4707287, 135.7779588, 'C', '寺院', null),
    ('熊野神社', null, '東京都', null, 35.6723917, 139.7140534, 'C', '神社', '青山熊野神社（あおやまくまのじんじゃ）は、東京都渋谷区神宮前にある神社である。神宮前・北青山の総鎮守。'),
    ('氷川神社', null, '東京都', null, 35.6529021, 139.7310569, 'C', '神社', '氷川神社（ひかわじんじゃ）は東京都港区元麻布にある神社である。'),
    ('湯神社', null, '愛媛県', '松山市', 33.8513638, 132.7870545, 'C', '神社', '湯神社（ゆじんじゃ）は、愛媛県松山市冠山にある神社。式内社で、旧社格は県社。'),
    ('桂春院', null, '京都府', null, 35.0247607, 135.722461, 'C', '寺院', '桂春院（けいしゅんいん）は、京都市右京区花園にある臨済宗の寺院。臨済宗妙心寺派大本山妙心寺の塔頭である。'),
    ('大魚神社', null, '佐賀県', null, 33.0301739, 130.1757723, 'C', '神社', '大魚神社（おおうおじんじゃ）は、佐賀県藤津郡太良町多良にある神社。有明海に面した場所にあり、複数の鳥居が海中に建てられている。'),
    ('萬福寺', null, '東京都', '大田区', 35.5901189, 139.7135427, 'C', '寺院', '萬福寺（まんぷくじ）は、東京都大田区にある曹洞宗の寺院。山号は慈眼山、開基は梶原景時と伝えられる。'),
    ('剣山神社', null, '徳島県', null, 34.0683542, 134.5374644, 'C', '神社', '剣山神社（つるぎさんじんじゃ）は、徳島県徳島市眉山町の眉山公園に鎮座する神社。眉山剣山神社（びざんつるぎやまじんじゃ）などとも称される。'),
    ('安浄寺', null, '岩手県', null, 39.3838471, 141.1135343, 'C', '寺院', '安浄寺（あんじょうじ）は、岩手県花巻市桜木町にある真宗大谷派の仏教寺院。本尊は阿弥陀如来。'),
    ('清水寺', null, '長野県', null, 36.5865521, 138.2720165, 'C', '寺院', '阿弥陀山清水寺（せいすいじ）は、長野県長野市若穂保科にある真言宗智山派の寺院。信濃三十三観音霊場第16番札所。'),
    ('鳴海八幡宮', null, '愛知県', null, 35.0744699, 136.9434195, 'C', '神社', null),
    ('松蔭寺', null, '神奈川県', null, 35.5013166, 139.6502308, 'C', '寺院', '松蔭寺（しょういんじ）は、神奈川県横浜市にある臨済宗建長寺派の寺院。山号は仙鶴山、本尊は木造釈迦如来立像。'),
    ('西雲院', null, '京都府', null, 35.0200399, 135.789552, 'C', '寺院', null),
    ('放生寺', null, '東京都', null, 35.7067352, 139.7177314, 'C', '寺院', '放生寺（ほうしょうじ）は、東京都新宿区西早稲田二丁目にある高野山真言宗準別格本山の寺院である。山号は光松山（こうしょうざん）。'),
    ('小山八幡神社', null, '東京都', null, 35.6118782, 139.6996, 'C', '神社', '小山八幡神社（こやまはちまんじんじゃ）は、東京都品川区荏原にある神社。旧小山村の鎮守。'),
    ('別宮大山祇神社', null, '愛媛県', null, 34.0687269, 132.9952125, 'C', '神社', '別宮大山祇神社（べっくおおやまづみじんじゃ）は、愛媛県今治市にある神社。伊予国一宮の大山祇神社の別宮。'),
    ('公智神社', null, '兵庫県', null, 34.8322023, 135.2369993, 'C', '神社', '公智神社（くちじんじゃ、こうちじんじゃ）は、兵庫県西宮市にある神社。延喜式神名帳に記されている式内小社で、旧社格は県社。'),
    ('正龍寺', null, '埼玉県', null, 36.1232531, 139.1824105, 'C', '寺院', '正龍寺（しょうりゅうじ）は、埼玉県大里郡寄居町にある曹洞宗の寺院。'),
    ('府八幡宮', null, '静岡県', null, 34.7198672, 137.8534369, 'C', '神社', '府八幡宮（ふはちまんぐう）は、静岡県磐田市中泉にある神社。旧社格は県社。'),
    ('大覚寺', null, '北海道', '札幌市', 43.0765034, 141.3704014, 'C', '寺院', '大覚寺（だいかくじ）は北海道札幌市東区北10条東11丁目2-10にある曹洞宗の寺院。'),
    ('大隆寺', null, '愛媛県', null, 33.2152819, 132.5763182, 'C', '寺院', '大隆寺（だいりゅうじ）は、愛媛県宇和島市に所在する寺院である。山号は金剛山。'),
    ('八坂神社', null, '大阪府', null, 34.6988323, 135.4708959, 'C', '神社', '八坂神社（やさかじんじゃ）は大阪市福島区海老江に鎮座する神社。
通称、海老の宮、海老江八坂神社。'),
    ('天真寺', null, '東京都', null, 35.6517078, 139.7291649, 'C', '寺院', '天真寺（てんしんじ）は、東京都港区にある臨済宗大徳寺派の寺院。'),
    ('萱野神社', null, '滋賀県', null, 34.9868161, 135.9245277, 'C', '神社', null),
    ('法雲寺', null, '茨城県', null, 36.1290058, 140.1457172, 'C', '寺院', '法雲寺（ほううんじ）は、茨城県土浦市にある臨済宗建長寺派の寺院。山号は大雄山。'),
    ('須賀神社', null, '栃木県', null, 36.3122835, 139.7988694, 'C', '神社', null),
    ('琴崎八幡宮', null, '山口県', null, 33.971881, 131.270459, 'C', '神社', null),
    ('八坂神社', null, '鹿児島県', null, 31.6055239, 130.5681909, 'C', '神社', '八坂神社（やさかじんじゃ）は、鹿児島県鹿児島市清水町にあるJR鹿児島駅の北東約500mの稲荷川河口北側に鎮座する神社。鹿児島五社の第二の神社である。'),
    ('補陀落山 慈眼寺 観音院', null, '鳥取県', '鳥取市', 35.4962521, 134.2417311, 'C', '寺院', null),
    ('八坂神社', null, '千葉県', '香取市', 35.889686, 140.5015808, 'C', '神社', '八坂神社（やさかじんじゃ）は、千葉県香取市佐原本宿にある神社である。佐原の大祭（祇園祭）で知られる。'),
    ('長松院', null, '滋賀県', null, 35.268942, 136.2545394, 'C', '寺院', null),
    ('文殊院', null, '東京都', null, 35.7559487, 139.7096385, 'C', '寺院', '文殊院（もんじゅいん）は、東京都板橋区にある真言宗豊山派の寺院。'),
    ('勝専寺', null, '東京都', '足立区', 35.7495119, 139.8010312, 'C', '寺院', '勝専寺（しょうせんじ）は、東京都足立区にある浄土宗の寺院。山門の色が赤いことから、別名「赤門寺」と呼ばれている。'),
    ('岩屋神社', null, '京都府', null, 34.9699991, 135.8263424, 'C', '神社', '岩屋神社（いわやじんじゃ）は、京都府京都市山科区にある神社である。近代社格制度では郷社。'),
    ('東林院', null, '徳島県', null, 34.161389, 134.5361193, 'C', '寺院', '東林院（とうりんいん）は徳島県鳴門市大麻町大谷に所在する高野山真言宗の寺院。八葉山 神宮寺 東林院と号す。'),
    ('源証寺', null, '東京都', null, 35.8075184, 139.7644898, 'C', '寺院', '源証寺（げんしょうじ）は、東京都足立区にある浄土宗系の単立寺院。'),
    ('杜本神社', null, '大阪府', null, 34.5457111, 135.6253297, 'C', '神社', '杜本神社（もりもとじんじゃ）は、大阪府にある神社。同名神社として羽曳野市・柏原市に1社ずつがあり、いずれも河内国安宿郡の式内社（名神大社）「杜本神社二座」の論社。'),
    ('豊中稲荷神社', null, '大阪府', null, 34.7908316, 135.4654618, 'C', '神社', null),
    ('千束稲荷神社', null, '東京都', null, 35.7269338, 139.7903457, 'C', '神社', '千束稲荷神社（せんぞくいなりじんじゃ）は、東京都台東区竜泉にある神社。登記上の宗教法人名称は稲荷神社（いなりじんじゃ）。'),
    ('加太春日神社', null, '和歌山県', null, 34.2752027, 135.0746458, 'C', '神社', '加太春日神社（かだかすがじんじゃ）は、和歌山県和歌山市加太にある神社。旧社格は村社。'),
    ('大宮神社', null, '和歌山県', null, 34.2541214, 135.3122874, 'C', '神社', '大宮神社（おおみやじんじゃ）は和歌山県岩出市にある神社。'),
    ('星田神社', null, '大阪府', null, 34.7653434, 135.6722481, 'C', '神社', '星田神社（ほしだじんじゃ）は、大阪府交野市星田にある神社。旧社格は村社。'),
    ('六所神社', null, '東京都', null, 35.6585234, 139.6432292, 'C', '神社', '六所神社（ろくしょじんじゃ）とは、東京都世田谷区赤堤にある神社。地名を冠して赤堤六所神社（あかつつみろくしょじんじゃ）とも通称される。'),
    ('東観音寺', null, '愛知県', null, 34.6834027, 137.4394663, 'C', '寺院', '東観音寺（とうかんのんじ）は、愛知県豊橋市にある臨済宗妙心寺派の寺院。山号は小松原山。'),
    ('鴻八幡宮', null, '岡山県', null, 34.4772148, 133.8277635, 'C', '神社', null),
    ('伝香寺', null, '奈良県', null, 34.6806285, 135.8257577, 'C', '寺院', '伝香寺（でんこうじ）は、奈良県奈良市にある律宗の寺院。山号はなし。'),
    ('高屋敷稲荷神社', null, '福島県', null, 37.4069681, 140.4481258, 'C', '神社', null),
    ('櫻井寺', null, '奈良県', null, 34.3521664, 135.6958809, 'C', '寺院', '桜井寺（さくらいじ）は、奈良県五條市にある浄土宗の寺院。山号は潤生山。'),
    ('大國玉神社', null, '茨城県', null, 36.3277129, 140.0743506, 'C', '神社', '大国玉神社（おおくにたまじんじゃ）は、茨城県桜川市にある大国主命を祭神とする神社。愛称は明神さま。'),
    ('大国寺', null, '兵庫県', null, 35.0660409, 135.1477971, 'C', '寺院', '大国寺（だいこくじ、大國寺）は 兵庫県丹波篠山市にある天台宗の寺院である。重要文化財指定の本堂や仏像を有し、「丹波の正倉院」と呼ばれる。'),
    ('相馬神社', null, '福島県', null, 37.7982324, 140.9145294, 'C', '神社', '相馬神社（そうまじんじゃ）は相馬中村城跡に奉られた福島県相馬市にある神社。旧社格は県社。'),
    ('橘本神社', null, '和歌山県', '海南市', 34.1243055, 135.1957817, 'C', '神社', '橘本神社（きつもとじんじゃ）は、和歌山県海南市にある神社である。菓祖・田道間守および熊野坐大神を祀り、菓子の神として崇敬される。'),
    ('岩槻大師彌勒密寺', null, '埼玉県', null, 35.943746, 139.6949523, 'C', '寺院', '弥勒密寺（みろくみつじ、旧字体：彌勒密寺）は、埼玉県さいたま市岩槻区本町にある真言宗智山派の寺院。'),
    ('三寳寺', null, '京都府', null, 35.0352257, 135.7012995, 'C', '寺院', '三宝寺（さんぽうじ）は、京都府京都市右京区鳴滝松本町にある日蓮宗の寺院。寺号の金映山妙護国院三寳寺は後水尾天皇より賜ったと伝わる。'),
    ('八幡神社', null, '東京都', null, 35.6046674, 139.7423128, 'C', '神社', null),
    ('綱敷天満宮', null, '兵庫県', null, 34.6444349, 135.1191974, 'C', '神社', '綱敷天満宮（つなしきてんまんぐう）は、兵庫県神戸市須磨区にある神社（天満宮）。旧社格は村社。'),
    ('養寿院', null, '埼玉県', null, 35.9238722, 139.4808687, 'C', '寺院', null),
    ('大村神社', null, '三重県', null, 34.6703803, 136.1837049, 'C', '神社', '大村神社（おおむらじんじゃ）は、三重県伊賀市阿保（あお）にある神社。式内社で、旧社格は県社。'),
    ('札幌伏見稲荷神社', null, '北海道', '札幌市', 43.0349657, 141.3253697, 'C', '神社', '札幌伏見稲荷神社（さっぽろふしみいなりじんじゃ）は、北海道札幌市中央区伏見にある神社。旧社格は郷社。'),
    ('満福寺', null, '栃木県', null, 36.2093889, 139.6987669, 'C', '寺院', '満福寺（まんぷくじ）は、栃木県下都賀郡野木町野渡にある曹洞宗の寺院。正式には、山号を西光山、院号を乾亨院、寺号を満福寺という。'),
    ('久多島神社', null, '鹿児島県', null, 31.5522453, 130.3354402, 'C', '神社', '久多島（くたじま）は、鹿児島県日置市に属し、東シナ海に所在する島（無人島）である。'),
    ('法性寺', null, '東京都', null, 35.7075973, 139.8180297, 'C', '寺院', '法性寺（ほっしょうじ）は、東京都墨田区業平五丁目にある日蓮宗の寺院。'),
    ('南湖神社', null, '福島県', null, 37.112358, 140.2188612, 'C', '神社', '南湖神社（なんこじんじゃ）は、福島県白河市にある南湖県立自然公園（南湖公園）に鎮座する神社。祭神は松平定信。'),
    ('矢作神社', null, '愛知県', null, 34.9627303, 137.1481442, 'C', '神社', '矢作神社（やはぎじんじゃ）は、愛知県岡崎市矢作町にある神社。主祭神は素盞嗚尊（すさのおのみこと）。'),
    ('桑津天神社', null, '大阪府', null, 34.6389542, 135.5300158, 'C', '神社', '桑津天神社（くわづてんじんじゃ）は、大阪市東住吉区桑津三丁目にある神社。'),
