    ('浄安寺', null, '埼玉県', null, 35.9540795, 139.7012368, 'C', '寺院', '浄安寺（じょうあんじ）は、埼玉県さいたま市岩槻区にある浄土宗の寺院。'),
    ('仏眼寺', null, '宮城県', '仙台市', 38.2475481, 140.8843587, 'C', '寺院', '仏眼寺（佛眼寺）（ぶつげんじ）は、宮城県仙台市若林区に所在する日蓮正宗の寺院。山号は法龍山（ほうりゅうざん）。'),
    ('富島神社', null, '大阪府', null, 34.713405, 135.4954166, 'C', '神社', '富島神社（とみしまじんしゃ）は、大阪府大阪市北区中津に鎮座する神社。'),
    ('小野神社', null, '神奈川県', '厚木市', 35.4324296, 139.3190489, 'C', '神社', '小野神社（おのじんじゃ）は、神奈川県厚木市小野に鎮座する神社。延長5年（927年）の『延喜式神名帳』に記載されている相模国の延喜式内社十三社の内の一社（小社）とされる。'),
    ('中嶋神社', null, '兵庫県', null, 35.5252499, 134.862579, 'C', '神社', '中嶋神社（なかしまじんじゃ）は、兵庫県豊岡市にある神社である。式内社で、旧社格は県社。'),
    ('小戸神社', null, '兵庫県', null, 34.8290358, 135.418999, 'C', '神社', '小戸神社（おおべじんじゃ）は、兵庫県川西市小戸に鎮座する神社。摂津国河辺郡の式内社。'),
    ('迫間不動', null, '岐阜県', null, 35.4312353, 136.9422761, 'C', '寺院', null),
    ('東海山 本源寺', null, '岡山県', null, 35.0622444, 133.9939552, 'C', '寺院', '本源寺（ほんげんじ）は岡山県津山市にある臨済宗妙心寺派の寺院。'),
    ('三方石観世音', null, '福井県', null, 35.5617549, 135.9145508, 'C', '寺院', '三方石観世音（三方石観音）は、福井県三方上中郡若狭町三方にある曹洞宗の観音堂。山号は大悲山、本尊は花崗岩の表面に彫られた磨崖仏の聖観世音菩薩。'),
    ('宝厳院', null, '京都府', null, 35.0141602, 135.6740106, 'C', '寺院', '宝厳院（ほうごんいん）は、京都市右京区嵯峨天竜寺芒ノ馬場町にある臨済宗天龍寺派の寺院。大本山天龍寺の塔頭。'),
    ('上徳寺', null, '京都府', null, 34.995513, 135.7640452, 'C', '寺院', '上徳寺（じょうとくじ）は、京都市下京区本塩竈町にある浄土宗の寺院。山号は塩竈山（えんそうざん）。'),
    ('丸山神明社', null, '愛知県', null, 35.1637027, 136.9462903, 'C', '神社', '丸山神明社（まるやましんめいしゃ）とは愛知県名古屋市千種区丸山町に鎮座する神社である。単に丸山神社ともいう。'),
