    ('上野天満宮', null, '愛知県', null, 35.1807544, 136.9570493, 'C', '神社', '上野天満宮（うえのてんまんぐう）は、愛知県名古屋市千種区赤坂町にある神社。（天満宮）。'),
    ('熊野神社', null, '兵庫県', null, 34.7434761, 135.3729556, 'C', '神社', null),
    ('平潟神社', null, '新潟県', null, 37.4468079, 138.8457308, 'C', '神社', '平潟神社（ひらがたじんじゃ）は新潟県長岡市にある諏訪神社。境内には長岡空襲の犠牲者を慰霊する「長岡市戦災殉難者慰霊塔」もあった（1995年（平成7年）に隣接する平潟公園に移設）。'),
    ('法雲山 妙願寺', null, '岡山県', '津山市', 35.0589514, 133.9986792, 'C', '寺院', '妙願寺（みょうがんじ）は、岡山県津山市戸川町にある浄土真宗本願寺派の寺院。通称は「鶴山御坊」。'),
    ('二柱神社', null, '宮城県', null, 38.319014, 140.8858854, 'C', '神社', '二柱神社（ふたはしらじんじゃ）は、宮城県仙台市泉区市名坂にある神社。神社の名称は、2柱の神を祀ることに由来する。'),
    ('津門神社', null, '兵庫県', null, 34.7354401, 135.349223, 'C', '神社', '津門神社（つとじんじゃ）は、西宮市にある神社（注：全国各地に同名の神社がある）。'),
    ('南新宮社', null, '愛知県', null, 35.1234969, 136.9095652, 'C', '神社', '南新宮社（みなみしんぐうしゃ）は、愛知県名古屋市熱田区にある神社である。熱田神宮の境内摂社のひとつ。'),
    ('東岳寺 (足立区)', null, '東京都', null, 35.7977883, 139.7885809, 'C', '寺院', '東岳寺（とうがくじ）は、東京都足立区にある曹洞宗系の単立寺院。'),
    ('五劫院', null, '奈良県', null, 34.694545, 135.8381476, 'C', '寺院', '五劫院（ごこういん）は、奈良県奈良市北御門町にある華厳宗の寺院。東大寺末。'),
    ('東圓寺', null, '埼玉県', null, 35.8107376, 139.5962447, 'C', '寺院', '東圓寺（とうえんじ）は、埼玉県朝霞市にある真言宗智山派の寺院。'),
    ('正法寺', null, '東京都', null, 35.7202002, 139.8015604, 'C', '寺院', '正法寺（しょうほうじ、または、しょうぼうじ）は、東京都台東区東浅草にある日蓮宗の寺院。山号は誠向山。'),
    ('安国寺', null, '栃木県', null, 36.4015847, 139.8764166, 'C', '寺院', '安国寺（あんこくじ）は、栃木県下野市にある真言宗智山派の寺院。山号は医王山。'),
    ('萬祥山 大岳院', null, '鳥取県', '倉吉市', 35.4318898, 133.8276012, 'C', '寺院', '大岳院（だいがくいん）とは、鳥取県倉吉市にある曹洞宗の仏教寺院。本尊は釈迦牟尼佛。'),
    ('宇波西神社', null, '福井県', '若狭町', 35.5869069, 135.9064824, 'C', '神社', '宇波西神社（うわせじんじゃ）は、福井県三方上中郡若狭町気山字寺谷129-5にある神社。式内社（名神大社）。'),
    ('水天宮', null, '北海道', null, 43.1927901, 141.0042269, 'C', '神社', '水天宮（すいてんぐう）は、北海道小樽市にある神社。旧社格は郷社。'),
    ('日運寺', null, '千葉県', '南房総市', 35.0144124, 139.944748, 'C', '寺院', '日運寺（にちうんじ）は、千葉県南房総市にある寺院。寺域には昭和45年（1970年）に植樹した約2万株のアジサイが咲き、房総のあじさい寺といわれている。'),
    ('皇足穂吉田大御神宮', null, '長野県', null, 36.667282, 138.212355, 'C', '神社', null),
    ('神明神社', null, '福井県', null, 36.068561, 136.2195729, 'C', '神社', null),
    ('慈眼寺', null, '埼玉県', null, 35.8997854, 139.5929127, 'C', '寺院', '慈眼寺（じげんじ）は、埼玉県さいたま市西区にある天台宗の寺院。通称は水波田（みずはた）観音。'),
    ('宝珠院', null, '愛知県', null, 35.139776, 136.8484191, 'C', '寺院', '寶珠院（ほうじゅいん）とは愛知県名古屋市中川区中郷にある真言宗智山派の寺院。なごや七福神の大黒天をまつる。'),
    ('神津神社', null, '大阪府', null, 34.7204778, 135.4846045, 'C', '神社', '神津神社（かみつじんじゃ）は、大阪市淀川区十三東に鎮座する神社。'),
    ('柴島神社', null, '大阪府', null, 34.730891, 135.5144888, 'C', '神社', null),
    ('永明寺', null, '島根県', null, 34.4697175, 131.77001, 'C', '寺院', '永明寺（ようめいじ）は、島根県鹿足郡津和野町にある曹洞宗の寺。山号は覚皇山（かくおうざん）。'),
    ('法然寺', null, '京都府', null, 35.018265, 135.675168, 'C', '寺院', '法然寺（ほうねんじ）は、京都市右京区嵯峨天竜寺立石町にある、浄土宗の寺院。 法然上人二十五霊跡第19番札所（熊谷入道護持の御影）。'),
    ('御杖神社', null, '奈良県', null, 34.4943188, 136.1946235, 'C', '神社', '御杖神社（みつえじんじゃ）は、奈良県宇陀郡御杖村にある神社。式内小社で、旧社格は郷社。'),
    ('正覚院', null, '千葉県', null, 35.7295911, 140.1152237, 'C', '寺院', '正覚院（しょうかくいん）は、千葉県八千代市村上にある真言宗豊山派の寺院。山号は池證山。'),
    ('常福寺 (足立区)', null, '東京都', null, 35.8031923, 139.7880701, 'C', '寺院', '常福寺（じょうふくじ）は、東京都足立区にある真宗大谷派の寺院。'),
    ('白龍神社', null, '愛知県', null, 35.1667099, 136.8903131, 'C', '神社', '白龍神社（はくりゅうじんじゃ）は、愛知県名古屋市中村区にある神社である。'),
    ('住吉神社', null, '大阪府', null, 34.7093571, 135.4630252, 'C', '寺院', null),
    ('多聞寺', null, '東京都', null, 35.7384884, 139.8193072, 'C', '寺院', '多聞寺（たもんじ）は、東京都墨田区にある真言宗智山派の寺院。'),
    ('八王子神社', null, '千葉県', null, 35.7439859, 140.0626451, 'C', '神社', '八王子神社（はちおうじじんじゃ）は、千葉県船橋市古和釜町にある神社である。旧社格は村社。'),
    ('真福寺', null, '神奈川県', null, 35.5594841, 139.5598472, 'C', '寺院', null),
    ('浄法寺', null, '群馬県', null, 36.1913617, 139.0596987, 'C', '寺院', '浄法寺（じょうぼうじ）は、群馬県藤岡市にある天台宗の寺院。正式な名称は広厳山般若浄土院浄法寺。'),
    ('秩父14番 長岳山今宮坊', null, '埼玉県', null, 35.9950587, 139.0786807, 'C', '寺院', '今宮坊（いまみやぼう）は、埼玉県秩父市にある臨済宗南禅寺派の寺院で、山号は長岳山と号する。'),
    ('満願寺', null, '神奈川県', null, 35.234255, 139.6761428, 'C', '寺院', null),
    ('強巴林', null, '愛知県', null, 35.2257451, 136.99229, 'C', '寺院', '強巴林（チャンバリン）は、日本国：愛知県名古屋市守山区青葉台に所在するチベット仏教の寺院。'),
    ('妙覚寺', null, '東京都', null, 35.6904499, 139.8772905, 'C', '寺院', '妙覚寺（みょうかくじ）は、東京都江戸川区一之江六丁目にある日蓮宗の寺院である。山号は金嶋山。'),
    ('京善寺', null, '大阪府', '大阪市', 34.6386728, 135.5304732, 'C', '寺院', '京善寺（きょうぜんじ）は、大阪市東住吉区にある真言宗御室派の寺院。山号は心王山。'),
    ('北向山不動院', null, '京都府', null, 34.9521875, 135.75291, 'C', '寺院', '北向山不動院（きたむきざんふどういん）は、京都市伏見区にある天台宗系単立の寺院。山号は北向山。'),
    ('八幡竃門神社', null, '大分県', null, 33.3324043, 131.483268, 'C', '神社', '八幡竈門神社（はちまんかまどじんじゃ）は、大分県別府市大字内竈に鎮座する神社である。'),
    ('徳願寺', null, '静岡県', null, 34.9588328, 138.3520291, 'C', '寺院', '徳願寺（とくがんじ）は静岡県静岡市駿河区に所在する曹洞宗の寺院。山号・大窪山（だいあさん）。'),
    ('厳島神社', null, '福島県', null, 37.5048169, 139.9542575, 'C', '神社', '厳島神社（いつくしまじんじゃ）は福島県会津若松市の神社。かつては宗像神社といい、永徳年間に地元の豪族、石塚、石部、堂家の三家によって建てられた。'),
    ('慈眼寺', null, '神奈川県', null, 35.3498482, 139.5020564, 'C', '寺院', '慈眼寺（じげんじ、じがんじ）は、神奈川県藤沢市渡内にある曹洞宗の寺院。山号は無量山。'),
    ('村檜神社', null, '栃木県', null, 36.3696878, 139.6244553, 'C', '神社', '村檜神社（村桧神社、むらひじんじゃ）は、栃木県栃木市にある神社。旧社格は郷社。'),
    ('福島県護國神社', null, '福島県', null, 37.7673869, 140.4683214, 'C', '神社', null),
    ('敬満神社', null, '静岡県', null, 34.8174706, 138.2038305, 'C', '神社', '敬満神社（けいまんじんじゃ/きょうまんじんじゃ）は、静岡県島田市阪本にある神社。式内社（名神大社）で、旧社格は郷社。'),
    ('滋賀県護国神社', null, '滋賀県', null, 35.2748183, 136.2567484, 'C', '神社', '滋賀縣護國神社（しがけんごこくじんじゃ）は、滋賀県彦根市にある神社（護国神社）。戊辰戦争から第二次世界大戦までの滋賀県関係の戦歿者3万4千余柱を祀る。'),
    ('妙圓寺', null, '東京都', null, 35.6707793, 139.7122555, 'C', '寺院', '妙円寺（みょうえんじ）は、東京都渋谷区にある日蓮宗の寺である。山号は蓮光山。'),
    ('貫井神社', null, '東京都', null, 35.6984787, 139.4937277, 'C', '神社', null),
    ('宥勝寺', null, '埼玉県', null, 36.2160427, 139.1840547, 'C', '寺院', '宥勝寺（ゆうしょうじ）は、埼玉県本庄市栗崎にある真言宗智山派の寺院。山号は西光山。'),
    ('如意輪寺', null, '兵庫県', null, 34.877913, 134.660629, 'C', '寺院', '如意輪寺（にょいりんじ）は、兵庫県姫路市に所在する寺院である。山号は補陀落山（ふだらくさん）。'),
    ('三宿神社', null, '東京都', null, 35.6509033, 139.6742356, 'C', '神社', '三宿神社（みしゅくじんじゃ）は東京都世田谷区三宿にある神社。'),
    ('春日神社', null, '東京都', null, 35.5814264, 139.72045, 'C', '神社', '春日神社（かすがじんじゃ）とは、東京都大田区にある神社。新井宿の鎮守であり、新井宿春日神社（あらいじゅくかすがじんじゃ）、大森春日神社（おおもりかすがじんじゃ）等とも称される。'),
    ('水神社', null, '秋田県', '秋田県大仙市豊川字観音堂57番', 39.5503008, 140.5873338, 'C', '神社', '水神社（すいじんじゃ）は、秋田県大仙市にある神社。'),
    ('金富神社', null, '福岡県', null, 33.6504084, 131.0659227, 'C', '神社', null),
    ('啓運山盛隆寺', null, '岡山県', null, 34.6108617, 133.8688531, 'C', '寺院', null),
    ('薬師院', null, '岡山県', null, 34.7893294, 133.6200418, 'C', '寺院', null),
    ('人見神社', null, '千葉県', '君津市', 35.3371585, 139.8672404, 'C', '神社', '人見神社（ひとみじんじゃ）は、千葉県君津市にある神社。'),
    ('荻窪八幡神社', null, '東京都', '杉並区', 35.7106212, 139.6063292, 'C', '神社', null),
    ('安立寺', null, '神奈川県', null, 35.6118476, 139.5676104, 'C', '寺院', '安立寺（あんりゅうじ）は、神奈川県川崎市多摩区にある日蓮宗の寺院。'),
    ('東漸寺', null, '千葉県', null, 35.6819934, 140.0222173, 'C', '寺院', '東漸寺（とうぜんじ）は、千葉県習志野市にある真言宗豊山派の寺院。山号は竜宝山。'),
    ('芬陀院', null, '京都府', null, 34.9763037, 135.7720766, 'C', '寺院', '芬陀院（ふんだいん）は、京都市東山区にある臨済宗の寺院。臨済宗東福寺派大本山･東福寺の塔頭である。'),
    ('済松寺', null, '東京都', null, 35.7060223, 139.7278589, 'C', '寺院', '済松寺（さいしょうじ）は、東京都新宿区榎町にある臨済宗妙心寺派の寺院。山号は蔭凉山。'),
    ('専福寺', null, '東京都', null, 35.6716925, 139.7323703, 'C', '寺院', '専福寺（せんぷくじ）は、東京都港区にある浄土真宗本願寺派の寺院。'),
    ('松尾神社', null, '兵庫県', null, 34.822472, 135.3843549, 'C', '神社', '松尾神社（まつおじんじゃ）は兵庫県宝塚市山本にある神社である。地元では「東の宮さん」と呼ばれ、西の天満神社と並んで旧川辺郡山本村の産土神。'),
    ('西本願寺鹿児島別院', null, '鹿児島県', '鹿児島市', 31.5938813, 130.5550149, 'C', '寺院', '本願寺鹿児島別院（ほんがんじかごしまべついん）は、鹿児島県鹿児島市東千石町にある浄土真宗本願寺派の直属寺院（別院）である。'),
    ('見性寺', null, '徳島県', null, 34.1319646, 134.5228578, 'C', '寺院', null),
    ('十日恵比須神社', null, '福岡県', null, 33.6042339, 130.4186119, 'C', '神社', '十日恵比須神社（とおかえびすじんじゃ）は、福岡県福岡市博多区にある神社である。事代主命（恵比須神）・大国主命（大黒神）を祀る。'),
    ('日枝神社', null, '静岡県', null, 34.9716728, 138.92837, 'C', '神社', '日枝神社（ひえじんじゃ）は、静岡県伊豆市修善寺に鎮座する神社である。源範頼が兄・源頼朝から幽閉された修禅寺の信功院があった場所。'),
    ('北谷稲荷', null, '東京都', null, 35.6653973, 139.7003348, 'C', '神社', '北谷稲荷神社（きたやいなりじんじゃ）は、東京都渋谷区神南一丁目に鎮座する神社である。'),
    ('泉福寺', null, '埼玉県', null, 35.9815831, 139.5244857, 'C', '寺院', '泉福寺（せんぷくじ）は、埼玉県桶川市にある天台宗の寺院である。山号は東叡山。'),
    ('白髭神社', null, '埼玉県', null, 35.9413609, 139.389715, 'C', '神社', null),
    ('感応寺', null, '東京都', null, 35.6886016, 139.8786675, 'C', '寺院', '感應寺（かんのうじ）は、東京都江戸川区一之江七丁目にある日蓮宗の寺院、山号は江久山、蓮光院とも称す。'),
    ('本立寺', null, '東京都', null, 35.7269578, 139.7150327, 'C', '寺院', '本立寺（ほんりゅうじ）は、東京都豊島区にある日蓮宗の寺院。'),
    ('大福寺', null, '静岡県', null, 34.829281, 137.5496933, 'C', '寺院', '大福寺（だいふくじ）は、静岡県浜松市浜名区にある高野山真言宗の寺院。山号は瑠璃山。'),
    ('新田神社', null, '群馬県', '太田市', 36.3175612, 139.3776979, 'C', '神社', '新田神社（にったじんじゃ）は、群馬県太田市金山町にある神社。新田義貞を祭神として祀る。'),
    ('大興寺', null, '静岡県', null, 34.7311353, 138.1583136, 'C', '寺院', '大興寺（だいこうじ）は、静岡県牧之原市西萩間（にしはぎま）にある曹洞宗の寺院。山号は龍門山。'),
    ('厳島神社', null, '京都府', null, 35.0181409, 135.7620463, 'C', '神社', '厳島神社（いつくしまじんじゃ）は、京都府京都市上京区、京都御苑内にある神社。堺町御門の西側、九条池の中島に鎮座し、「池の弁天さん」と称される。'),
    ('筒井神社', null, '滋賀県', null, 35.1281305, 136.3698857, 'C', '神社', null),
    ('源立寺', null, '大阪府', null, 34.8241036, 135.4237945, 'C', '寺院', '源立寺（げんりゅうじ）は、大阪市池田市に所在する日蓮正宗の寺院だが、正信会僧侶が居住・占有している。山号は恵日山（えにちさん）。'),
    ('石堂寺', null, '千葉県', '南房総市', 35.0521308, 139.9579117, 'C', '寺院', '石堂寺（いしどうじ）は、千葉県南房総市にある、天台宗の寺院。山号は長安山。'),
    ('中山寺', null, '福井県', null, 35.4962221, 135.5007309, 'C', '寺院', '中山寺（なかやまでら）は、福井県高浜町にある真言宗御室派の寺院。山号は青葉山。'),
    ('観音寺', null, '大阪府', null, 34.4764046, 135.4368863, 'C', '寺院', null),
    ('安養寺', null, '長野県', '佐久市', 36.2661235, 138.5122537, 'C', '寺院', '安養寺（あんようじ）は長野県佐久市安原にある臨済宗妙心寺派の寺院。山号は宝林山。'),
    ('天照皇大神', null, '神奈川県', null, 35.5504333, 139.663706, 'C', '神社', '天照皇大神（あまてらすすめおおかみ/てんしょうこうたいじん）は神奈川県川崎市幸区南加瀬1丁目にある神社。'),
