    ('尾上神社', null, '兵庫県', null, 34.743744, 134.8240532, 'C', '神社', '尾上神社（おのえじんじゃ）は、兵庫県加古川市にあり住吉四所を祀っている神社。'),
    ('泊神社', null, '兵庫県', null, 34.7641689, 134.8242286, 'C', '神社', '泊神社（とまりじんじゃ）は、兵庫県加古川市に鎮座する神社である。旧社格は郷社。'),
    ('常栄山自性院', null, '東京都', null, 35.5474039, 139.7406161, 'C', '寺院', null),
    ('厚木神社', null, '神奈川県', null, 35.442984, 139.3702571, 'C', '神社', '厚木神社（あつぎじんじゃ）は、神奈川県厚木市にある神社。旧称は牛頭天王社と称し、厚木村の鎮守であった。'),
    ('膳所神社', null, '滋賀県', null, 34.9947411, 135.8904194, 'C', '神社', '膳所神社（ぜぜじんじゃ）は、滋賀県大津市にある神社。旧社格は県社。'),
    ('西迎寺', null, '東京都', null, 35.6912142, 139.7209572, 'C', '寺院', null),
    ('半木神社', null, '京都府', null, 35.0498029, 135.7616882, 'C', '神社', '半木神社（なからぎじんじゃ）は京都市左京区の京都府立植物園内に位置する神社である。'),
    ('弘仁寺', null, '奈良県', '奈良市', 34.6287045, 135.8535621, 'C', '寺院', '弘仁寺（こうにんじ）は、奈良県奈良市虚空蔵町にある高野山真言宗の寺院。山号は虚空蔵山。'),
    ('泉龍院', null, '愛知県', null, 34.8974317, 137.4704304, 'C', '寺院', null),
    ('熊野那智神社', null, '宮城県', '名取市', 38.1873445, 140.8385957, 'C', '神社', '熊野那智神社（くまのなちじんじゃ）は、宮城県名取市にある神社である。名取熊野三社のうちの一社。'),
    ('志氐神社', null, '三重県', null, 34.9907305, 136.6328735, 'C', '神社', '志氐神社（しでじんじゃ）は三重県四日市市羽津地区大宮町に立地する古墳跡地の神社。神紋は十六弁菊である。'),
    ('真龍寺', null, '大阪府', null, 34.8497435, 135.5547774, 'C', '寺院', null),
    ('高岡神社', null, '高知県', null, 33.2210213, 133.1244037, 'C', '神社', null),
    ('一之宮神社', null, '鹿児島県', null, 31.5629925, 130.546093, 'C', '神社', '一之宮神社（いちのみやじんじゃ）は鹿児島市郡元二丁目にある神社。鹿児島三社の一の宮にあたるが、「一之宮」には薩摩国一宮である枚聞神社の末社という位置づけもある。'),
    ('雨宝院', null, '京都府', null, 35.0324098, 135.7464514, 'C', '寺院', null),
    ('二子神社', null, '神奈川県', null, 35.6086369, 139.6215365, 'C', '神社', '二子神社（ふたこじんじゃ）は、神奈川県川崎市高津区二子一丁目にある神社。元は神明社と称していたが、明治時代に大六天と稲荷を合祀し、村名をとって二子神社と改称した。'),
    ('中氷川神社', null, '埼玉県', null, 35.7895582, 139.397982, 'C', '神社', '中氷川神社（なかひかわじんじゃ）は、埼玉県所沢市三ケ島にある、氷川信仰の神社である。三ケ島（みかじま）村の鎮守で、旧村社。'),
    ('廣済寺', null, '兵庫県', null, 34.7469022, 135.4314076, 'C', '寺院', '広済寺（こうさいじ）は、兵庫県尼崎市にある日蓮宗の寺院。山号は久々知山。'),
    ('少林寺', null, '福岡県', '福岡市', 33.592932, 130.3954341, 'C', '寺院', '少林寺（しょうりんじ）は福岡県福岡市にある浄土宗の寺院。山号は大凉山（だいりょうざん）。'),
    ('鹽竈神社', null, '東京都', null, 35.6631541, 139.7545257, 'C', '神社', null),
    ('水口神社', null, '滋賀県', '甲賀市', 34.9676597, 136.1674028, 'C', '神社', '水口神社（みなくちじんじゃ）は、滋賀県甲賀市水口町宮の前にある神社。式内社で、旧社格は県社。'),
    ('駒留八幡神社', null, '東京都', null, 35.641123, 139.660535, 'C', '神社', null),
    ('熊野新宮社', null, '宮城県', null, 38.2030251, 140.8467762, 'C', '神社', '熊野神社（くまのじんじゃ）は、宮城県名取市にある神社である。名取熊野三社のうちの一社。'),
    ('城岡神社', null, '静岡県', null, 35.1007132, 138.8595763, 'C', '神社', '城岡神社（しろおかじんじゃ）は、静岡県沼津市大手町に所在する神社。
かつて当地に所在した沼津城（の二の丸）の名残となる神社である。'),
    ('南方神社', null, '鹿児島県', null, 31.6097229, 130.5692692, 'C', '神社', '南方神社（みなみかたじんじゃ）は鹿児島県鹿児島市清水町に鎮座する神社。鹿児島五社の第一（筆頭）である。'),
    ('秀麓斎', null, '宮城県', null, 38.1905155, 140.8469822, 'C', '寺院', null),
