    ('八幡神社', null, '千葉県', null, 35.7614145, 139.9928174, 'C', '神社', null),
    ('天祖神社', null, '東京都', null, 35.6534036, 139.7405716, 'C', '神社', '元神明宮（もとしんめいぐう）は、東京都港区三田一丁目に鎮座する神社である。'),
    ('白石神社', null, '北海道', null, 43.040252, 141.4282887, 'C', '神社', null),
    ('秩父03番 岩本山常泉寺', null, '埼玉県', null, 36.0123002, 139.1069149, 'C', '寺院', '常泉寺（じょうせんじ）は埼玉県秩父市にある曹洞宗の寺院で、山号は岩本山と号する。秩父札所の第三番であり、また、秩父市の史跡に指定されている。'),
    ('足助八幡宮', null, '愛知県', null, 35.1342007, 137.3107995, 'C', '神社', null),
    ('愛染院', null, '東京都', '新宿区', 35.6855585, 139.7243823, 'C', '寺院', '愛染院（あいぜんいん）は、東京都新宿区にある真言宗豊山派の寺院。'),
    ('瓦屋禅寺', null, '滋賀県', null, 35.1247585, 136.1836998, 'C', '寺院', '瓦屋寺（かわらやじ）は、滋賀県東近江市建部瓦屋寺町にある臨済宗妙心寺派の寺院。山号は石崎山。'),
    ('弘前天満宮', null, '青森県', '弘前市', 40.6015204, 140.4595678, 'C', '神社', '天満宮（てんまんぐう）は青森県弘前市西茂森、西方岩木山に相対し眼下に先達ヶ渕を見下ろす景勝地に鎮座する神社（天満宮）。地名を冠して弘前天満宮（ひろさきてんまんぐう）とも称される。'),
    ('荏名神社', null, '岐阜県', null, 36.1351091, 137.2709983, 'C', '神社', null),
    ('国土安穏寺', null, '東京都', null, 35.7817588, 139.7951087, 'C', '寺院', '国土安穏寺（こくどあんのんじ）は、東京都足立区島根にある日蓮宗の寺院。山号は天下長久山。'),
    ('睦神社', null, '埼玉県', null, 35.847068, 139.6537346, 'C', '神社', '睦神社（むつみじんじゃ） は、埼玉県さいたま市南区にある神社。総本社は富士山本宮浅間大社。'),
    ('常光 圓満寺', null, '大阪府', null, 34.7600055, 135.5218724, 'C', '寺院', '常光円満寺（じょうこうえんまんじ）は、大阪府吹田市元町にある高野山真言宗の寺院。山号は慧日山。'),
    ('光厳寺', null, '群馬県', null, 36.4076333, 139.0379858, 'C', '寺院', '光巌寺（こうがんじ）は、群馬県前橋市にある天台宗の寺院。正式名は秋元山 江月院 光巌寺（あきもとさん こうげついん こうがんじ）、本尊は釈迦如来。'),
    ('妙法寺', null, '静岡県', '富士市', 35.1405367, 138.712735, 'C', '寺院', '妙法寺（みょうほうじ）は、静岡県富士市にある日蓮宗の寺院。旧本山は身延山久遠寺(身延門流)、鏡師法縁(善学会)。'),
    ('東大社', null, '千葉県', null, 35.805916, 140.6861695, 'C', '神社', '東大社（とうだいしゃ）は、千葉県香取郡東庄町（下総国香取郡）にある神社。旧社格は県社。'),
    ('善應寺', null, '群馬県', null, 36.3263749, 139.1909404, 'C', '寺院', '善應寺（ぜんのうじ）は、群馬県伊勢崎市にある天台宗の寺院である。山号は施無畏山。'),
    ('玄賓庵', null, '奈良県', null, 34.536686, 135.855063, 'C', '寺院', '玄賓庵（げんぴあん）は奈良県桜井市茅原にあり、三輪山麓に建つ真言宗醍醐派の寺院である。'),
    ('普賢寺', null, '山口県', null, 33.9216221, 131.9681576, 'C', '寺院', '普賢寺（ふげんじ）は、山口県光市室積8-6-1にある臨済宗建仁寺派の寺院。
普賢寺に安置してある普賢菩薩は延命の仏、海の守護仏として信仰を集めている。'),
    ('樫原三ノ宮神社', null, '京都府', null, 34.9716286, 135.69046, 'C', '神社', '三ノ宮神社（さんのみやじんじゃ）は、京都市西京区樫原杉原町にある神社である。社格は旧村社。'),
    ('安国禅寺（臨済宗）', null, '長野県', null, 35.9886929, 138.1408839, 'C', '寺院', '安国寺（あんこくじ）または安国禅寺は、長野県茅野市にある臨済宗妙心寺派の寺院。山号は泰平山。'),
    ('須賀神社', null, '佐賀県', null, 33.3027199, 130.2050481, 'C', '神社', null),
    ('子鍬倉神社', null, '福島県', null, 37.0564969, 140.885876, 'C', '神社', '子鍬倉神社（こくわくらじんじゃ）は、福島県いわき市平字揚土にある神社。式内小社で、旧社格は県社。'),
    ('松江護國神社', null, '島根県', null, 35.476703, 133.0496192, 'C', '神社', '松江護國神社（まつえごこくじんじゃ）は、島根県松江市の松江城址にある神社（護国神社）である。'),
    ('福善寺', null, '広島県', null, 34.4122326, 133.2029347, 'C', '寺院', null),
    ('鶴峯八幡神社', null, '千葉県', '富津市', 35.2529886, 139.8692635, 'C', '神社', null),
    ('来迎寺', null, '兵庫県', null, 34.6684044, 135.1755667, 'C', '寺院', '来迎寺（らいごうじ）は兵庫県神戸市兵庫区島上町にある浄土宗西山派の仏教寺院。'),
    ('妙覚寺 (稲城市)', null, '東京都', null, 35.6324179, 139.5142702, 'C', '寺院', '妙覚寺（みょうかくじ）は、東京都稲城市にある臨済宗建長寺派の寺院。山号は雲騰山。'),
    ('奥石神社', null, '滋賀県', null, 35.1300548, 136.1619531, 'C', '神社', '奥石神社（おいそじんじゃ）は、滋賀県近江八幡市安土町東老蘇にある神社。式内社で、旧社格は県社。'),
    ('青峯山 正福寺', null, '三重県', null, 34.4103738, 136.826213, 'C', '寺院', '正福寺（しょうふくじ）は、三重県鳥羽市松尾町にある、高野山真言宗の仏教寺院。山号は青峯山（あおのみねさん）で、同名の山（海抜336メートル）の頂上付近にある。'),
    ('多武峯内藤神社', null, '東京都', null, 35.6850093, 139.7152927, 'C', '神社', '多武峯内藤神社（とうのみねないとうじんじゃ）は、東京都新宿区の神社。'),
    ('尾長天満宮', null, '広島県', null, 34.4043646, 132.4800107, 'C', '神社', '尾長天満宮（おながてんまんぐう）は、広島県広島市東区山根町にある神社。'),
    ('別格19 寶幢山 香西寺', null, '香川県', '高松市', 34.347619, 133.9939302, 'C', '寺院', null),
    ('別格9番 文殊院', null, '愛媛県', '松山市', 33.764466, 132.8108093, 'C', '寺院', '文殊院（もんじゅいん）は愛媛県松山市に所在する真言宗醍醐派の寺院。大法山（だいほうざん）、文殊院（もんじゅいん）、徳盛寺（とくじょうじ）と号す。'),
    ('秩父33番 延命山 菊水寺', null, '埼玉県', null, 36.0309044, 139.0423706, 'C', '寺院', null),
    ('大光寺', null, '長崎県', null, 32.7434255, 129.8827806, 'C', '寺院', '大光寺（だいこうじ）は、長崎市にある浄土真宗本願寺派の寺院。本尊は阿弥陀如来。'),
    ('伏木神社', null, '富山県', null, 36.7957747, 137.0553287, 'C', '神社', '伏木神社（ふしきじんじゃ）は、富山県高岡市伏木にある神社である。毎年5月の第3土曜日とその前日である金曜日、2日間にわたって斎行される例祭「伏木曳山祭」（別名「けんか山」）で有名。'),
    ('浄土寺', null, '東京都', null, 35.6742155, 139.7354661, 'C', '寺院', null),
    ('真照寺', null, '神奈川県', null, 35.4150093, 139.6211639, 'C', '寺院', '真照寺（しんしょうじ）は、神奈川県横浜市磯子区磯子にある高野山真言宗の寺院。山号は禅馬山。'),
    ('常光院', null, '京都府', null, 35.0183803, 135.7878477, 'C', '寺院', '常光院（じょうこういん）は、京都市左京区黒谷町にある浄土宗の寺院。大本山金戒光明寺の塔頭。'),
    ('普門山弘安寺', null, '福島県', null, 37.5024073, 139.8228302, 'C', '寺院', '弘安寺（こうあんじ）は、福島県大沼郡会津美里町にある曹洞宗の寺院。山号は普門山。'),
    ('彌栄神社', null, '島根県', null, 34.4658465, 131.7715412, 'C', '神社', '弥栄神社（やさかじんじゃ）は、島根県鹿足郡津和野町後田にある神社である。'),
    ('第六天神社', null, '東京都', null, 35.6789059, 139.6121402, 'C', '神社', null),
    ('布良崎神社', null, '千葉県', '館山市', 34.9173741, 139.8263857, 'C', '神社', '布良崎神社（めらさきじんじゃ）は、千葉県館山市布良にある神社。旧社格は郷社。'),
    ('天神社', null, '奈良県', null, 34.5158532, 135.7465496, 'C', '神社', '天神社（てんじんしゃ）は、奈良県大和高田市三和町にある神社。高田天神社とも呼ばれる。'),
    ('綾部神社', null, '佐賀県', null, 33.3605868, 130.4411269, 'C', '神社', null),
    ('智山派宝幢院', null, '東京都', null, 35.5481445, 139.7064601, 'C', '寺院', '宝幢院（ほうどういん）は、東京都大田区西六郷にある真言宗智山派の寺院。'),
    ('生子神社（泣き相撲）', null, '栃木県', null, 36.5383658, 139.7377175, 'C', '神社', '生子神社（いきこじんじゃ）は栃木県鹿沼市樅山町（もみやままち）の西部丘陵部の縁辺に鎮座する神社。旧社格は村社。'),
    ('大陽寺', null, '埼玉県', null, 35.9081437, 138.9711833, 'C', '寺院', '大陽寺（たいようじ）は、埼玉県秩父市にある臨済宗建長寺派の寺院。なお、字は「太陽寺」ではなく「大陽寺」である。'),
    ('斎年寺', null, '愛知県', null, 34.9326833, 136.8251099, 'C', '寺院', '斉年寺（さいねんじ）は、愛知県常滑市大野町にある曹洞宗の寺院。山号は萬松山。'),
    ('長生寺', null, '山梨県', null, 35.5661139, 138.902932, 'C', '寺院', null),
    ('廣畑天満宮', null, '兵庫県', null, 34.8071626, 134.6338329, 'C', '神社', '廣畑天満宮（ひろはたてんまんぐう、広畑天満宮）は、兵庫県姫路市広畑区北野町に鎮座する神社。旧社格は村社。'),
    ('大正寺', null, '東京都', null, 35.655316, 139.5456981, 'C', '寺院', '大正寺（たいしょうじ）は、東京都調布市にある新義真言宗の寺院。'),
    ('蒲生神社', null, '栃木県', null, 36.5683107, 139.885316, 'C', '神社', null),
    ('蓮華寺', null, '大阪府', null, 34.7014996, 135.5055114, 'C', '寺院', null),
    ('西宮成田山圓満寺', null, '兵庫県', null, 34.7345857, 135.3340412, 'C', '寺院', '円満寺（えんまんじ）は兵庫県西宮市社家町一丁目にある仏教寺院。 高野山真言宗別格本山、山号は医王山。'),
    ('秋田諏訪宮', null, '秋田県', null, 39.4237545, 140.5430506, 'C', '神社', null),
    ('琴平神社', null, '神奈川県', null, 35.5819766, 139.5178591, 'C', '神社', '琴平神社（ことひらじんじゃ）は神奈川県川崎市麻生区にある神社である。'),
    ('摩耶寺', null, '東京都', null, 35.6117866, 139.7003629, 'C', '寺院', '摩耶寺（まやじ）は、東京都品川区荏原7丁目にある寺院。摩耶夫人像を祀っていることで知られる。'),
    ('亘理神社', null, '宮城県', '亘理町', 38.0337724, 140.8507891, 'C', '神社', '亘理神社（わたりじんじゃ）は、宮城県亘理町にある神社である。別名「亘理招魂社」、「おだて」とも。'),
    ('蓮華寺', null, '青森県', null, 40.8240813, 140.7493736, 'C', '寺院', null),
    ('氷川神社', null, '神奈川県', null, 35.581667, 139.3612804, 'C', '神社', '氷川神社（ひかわじんじゃ）は神奈川県相模原市中央区にある神社。地名を冠して相模原氷川神社（さがみはらひかわじんじゃ）とも。'),
    ('八雲神社', null, '東京都', null, 35.7860998, 139.7249443, 'C', '神社', '八雲神社（やくもじんじゃ）は東京都北区の神社。地名を冠して岩淵八雲神社（いわぶちやくもじんじゃ）とも称される。'),
    ('寶袋寺', null, '神奈川県', null, 35.525342, 139.5213083, 'C', '寺院', '寶帒寺（ほうたいじ、寶袋寺、宝袋寺）は、神奈川県横浜市緑区にある曹洞宗の仏教寺院である。山号は八幡山。'),
    ('若江鏡神社', null, '大阪府', null, 34.6529285, 135.6040918, 'C', '神社', null),
    ('秋葉神社', null, '長野県', null, 36.6534271, 138.1910939, 'C', '神社', null),
    ('小物忌神社', null, '山形県', null, 39.1957641, 139.5536642, 'C', '神社', '小物忌神社（おものいみじんじゃ）は、山形県酒田市の離島、飛島にある神社である。旧社格は郷社。'),
    ('大豊神社', null, '京都府', null, 35.0182325, 135.7962164, 'C', '神社', '大豊神社（おおとよじんじゃ）は、京都市左京区鹿ケ谷宮ノ前町にある神社。狛犬ではなく鼠の像があることで有名である。'),
    ('久居八幡宮', null, '三重県', null, 34.6753807, 136.4730454, 'C', '神社', '久居八幡宮（ひさいはちまんぐう）は、三重県津市久居二ノ町にある神社。本殿の建築様式は神明造、社殿は破風(唐破風)向拝寄棟造。'),
    ('胸肩神社', null, '青森県', null, 40.5945684, 140.4780725, 'C', '神社', null),
    ('法華寺', null, '愛媛県', null, 34.0156627, 133.0332092, 'C', '寺院', '法華寺（ほっけいじ）は、愛媛県今治市桜井に所在する真言律宗の寺院である。本尊は十一面観音菩薩。'),
    ('大井俣窪八幡神社', null, '山梨県', null, 35.7047379, 138.6900153, 'C', '神社', '大井俣窪八幡神社（おおいまたくぼはちまんじんじゃ）は、山梨県山梨市にある神社。通称窪八幡神社。'),
    ('大宮大原神社', null, '千葉県', null, 35.6868426, 140.0639762, 'C', '神社', '大原大宮神社（おおはらおおみやじんじゃ）は、千葉県習志野市実籾にある神社。旧社格は村社。'),
    ('南泉寺', null, '東京都', null, 35.7290683, 139.7662515, 'C', '寺院', '南泉寺（なんせんじ）は、東京都荒川区にある臨済宗妙心寺派の寺院。'),
    ('矢田寺', null, '京都府', null, 35.0089073, 135.7672571, 'C', '寺院', null),
    ('正蓮寺', null, '大阪府', null, 34.6855659, 135.4484759, 'C', '寺院', '正蓮寺（しょうれんじ）は大阪府大阪市此花区伝法にある日蓮宗の仏教寺院。旧本山は大本山本圀寺（六条門流）。'),
    ('淀川神社', null, '大阪府', null, 34.7182433, 135.521205, 'C', '神社', '淀川神社（よどがわじんじゃ）は、大阪市都島区毛馬町にある神社。'),
    ('多珂神社', null, '福島県', null, 37.6005356, 140.9926314, 'C', '神社', '多珂神社（たかじんじゃ）は、福島県南相馬市原町区にある神社。式内社（名神大社）論社で、旧社格は県社。'),
    ('大久寺', null, '東京都', null, 35.735918, 139.7549082, 'C', '寺院', '大久寺（だいきゅうじ）は、東京都北区にある法華宗陣門流の寺院。'),
    ('三八城神社', null, '青森県', null, 40.5139533, 141.4878045, 'C', '神社', '三八城神社（みやぎじんじゃ）は、青森県八戸市内丸にある三八城公園内にある神社。江戸時代後期から明治時代初期に流行した藩祖を祀った神社のひとつ。'),
    ('石坐神社', null, '滋賀県', null, 35.0003864, 135.8880128, 'C', '神社', '石坐神社（いわいじんじゃ）は、滋賀県大津市にある神社。式内社で、旧社格は村社。'),
    ('青龍山 勝国寺', null, '東京都', null, 35.6479578, 139.6524011, 'C', '寺院', '勝国寺（しょうこくじ）は、東京都世田谷区にある新義真言宗の寺院。所在地が世田谷城の裏鬼門に位置しており、鬼門除けのために薬師如来を安置して祀ったのが起りとされる。'),
    ('安養院', null, '埼玉県', null, 36.2420586, 139.1833283, 'C', '寺院', '安養院（あんよういん）は、埼玉県本庄市にある曹洞宗の寺院。山号は若泉山。'),
    ('篠路神社', null, '北海道', '札幌市', 43.1462251, 141.3649652, 'C', '神社', null),
    ('倭文神社', null, '奈良県', null, 34.6568016, 135.8045824, 'C', '神社', '倭文神社（しずりじんじゃ）は、奈良県奈良市西九条町二丁目にある神社。'),
    ('卯子酉神社', null, '岩手県', null, 40.0093402, 141.8521764, 'C', '神社', null),
    ('功徳林寺', null, '東京都', null, 35.7249979, 139.7688748, 'C', '寺院', '功徳林寺（くどくりんじ）は、東京都台東区にある浄土宗の寺院。'),
    ('念仏寺', null, '奈良県', null, 34.6836169, 135.824707, 'C', '寺院', '念佛寺（ねんぶつじ）は、奈良県奈良市漢国町7番地にある浄土宗の寺院である。山号は降魔山。'),
    ('安養寺', null, '岡山県', null, 34.6359524, 133.7589735, 'C', '寺院', '安養寺（あんようじ）は、岡山県倉敷市にある高野山真言宗の寺院である。'),
    ('長久寺', null, '大阪府', null, 34.6715584, 135.5161996, 'C', '寺院', null),
    ('蓮光寺', null, '東京都', null, 35.7253494, 139.7554121, 'C', '寺院', null),
    ('大神山神社', null, '東京都', '小笠原村', 27.0965518, 142.1941532, 'C', '神社', '大神山神社（おおがみやまじんじゃ）は、東京都小笠原村父島にある神社。
父島中心部の大村集落裏手にある大神山の山腹に位置し、大神山公園（大神山地区）に隣接する。'),
    ('海蔵寺', null, '東京都', null, 35.6137593, 139.7407019, 'C', '寺院', '海蔵寺（かいぞうじ）は、東京都品川区にある時宗の寺院。'),
    ('春光院', null, '京都府', null, 35.024193, 135.7195354, 'C', '寺院', '春光院（しゅんこういん）は、京都市右京区花園の臨済宗大本山妙心寺の塔頭寺院で、大庫裏の北に位置する。'),
    ('妖怪神社', null, '鳥取県', null, 35.5458594, 133.2257888, 'C', '神社', '妖怪神社（ようかいじんじゃ）とは、鳥取県境港市の水木しげるロードにある神社。運営会社は境港市大正町のアイズ。'),
    ('石神社', null, '東京都', null, 35.795948, 139.2254612, 'C', '神社', '石神社（いしがみしゃ）は東京都青梅市二俣尾にある神社である。'),
    ('稱念寺', null, '奈良県', '橿原市今井町', 34.5060757, 135.7856068, 'C', '寺院', '称念寺（稱念寺・しょうねんじ）は、奈良県橿原市今井町にある浄土真宗本願寺派の寺院。山号は今井山。'),
    ('壱岐神社', null, '長崎県', null, 33.8110902, 129.7626475, 'C', '神社', '壱岐神社（いきじんじゃ）は、長崎県壱岐市に鎮座する神社である。'),
    ('仲仙寺', null, '長野県', null, 35.8882985, 137.9148591, 'C', '寺院', '仲仙寺（ちゅうせんじ）は、長野県伊那市にある天台宗の寺院。山号は羽広山。'),
    ('大泉寺', null, '東京都', null, 35.5992615, 139.4112809, 'C', '寺院', '大泉寺（だいせんじ）は、東京都町田市にある曹洞宗の寺院。'),
    ('妙延寺', null, '東京都', null, 35.7515682, 139.5885461, 'C', '寺院', '妙延寺（みょうえんじ）は、東京都練馬区東大泉3丁目にある日蓮宗の寺院。旧本山は大本山法華経寺、達師法縁。'),
    ('秩父07番 青苔山 法長寺', null, '埼玉県', null, 35.9838863, 139.1078763, 'C', '寺院', '法長寺（ほうちょうじ）は、埼玉県秩父郡横瀬町にある曹洞宗の寺院で、山号は青苔山と号する。秩父札所の第七番であり、横瀬町の史跡に指定されている。'),
    ('宝生寺', null, '東京都', null, 35.6850243, 139.2704949, 'C', '寺院', '宝生寺（ほうしょうじ、旧字体：寶生寺）は、東京都八王子市にある真言宗智山派の寺院。'),
    ('薬王寺', null, '東京都', null, 35.8115434, 139.3094564, 'C', '寺院', null),
    ('厭離庵', null, '京都府', null, 35.0228446, 135.6708608, 'C', '寺院', '厭離庵（えんりあん）は、京都府京都市右京区にある臨済宗天龍寺派の寺院（尼寺）。山号は如意山。'),
    ('松井神社', null, '熊本県', null, 32.5093052, 130.5987846, 'C', '神社', '松井神社（まついじんじゃ）は、熊本県八代市北の丸町に鎮座する神社である。旧社格は郷社。'),
    ('縣神社', null, '千葉県', null, 35.5424959, 140.2981211, 'C', '神社', null),
    ('願成寺', null, '岩手県', null, 38.9203167, 141.1306509, 'C', '寺院', null),
    ('本覚寺', null, '東京都', null, 35.7132424, 139.7865172, 'C', '寺院', '本覚寺（ほんがくじ）は、東京都台東区松が谷にある日蓮宗の寺院。山号は龍鳴山。'),
    ('光明寺', null, '東京都', null, 35.6624221, 139.7454417, 'C', '寺院', '光明寺（こうみょうじ）は、東京都港区にある浄土真宗本願寺派の寺院。梅の花で有名。'),
    ('海徳寺', null, '東京都', null, 35.6160487, 139.7428905, 'C', '寺院', '海徳寺（かいとくじ）は、東京都品川区南品川にある日蓮宗の寺院。自覚山松陽院。'),
    ('安楽寺', null, '神奈川県', '寒川町', 35.3713658, 139.3879025, 'C', '寺院', '安楽時（あんらくじ）は神奈川県高座郡寒川町にある高野山真言宗の寺院。元中本寺。'),
    ('阿太加夜神社', null, '島根県', null, 35.4329949, 133.126233, 'C', '神社', null),
    ('金剛寺', null, '東京都', null, 35.7519978, 139.7299245, 'C', '寺院', null),
    ('威徳寺', null, '東京都', null, 35.6763252, 139.7350992, 'C', '寺院', '威徳寺（いとくじ）は、東京都港区にある真言宗智山派の寺院。'),
    ('岡山県護国神社', null, '岡山県', null, 34.6573346, 133.9551511, 'C', '神社', '岡山県護国神社（おかやまけんごこくじんじゃ）とは岡山県岡山市中区奥市にある護国神社である。旧社格は内務大臣指定護国神社で、戦後別表神社となった。'),
    ('浮羽稲荷', null, '福岡県', null, 33.3229674, 130.791678, 'C', '神社', '浮羽稲荷神社（うきはいなりじんじゃ）は、福岡県うきは市浮羽町流川1513-9に鎮座する神社である。'),
    ('小国両神社', null, '熊本県', '小国町', 33.1200294, 131.0732608, 'C', '神社', '小国両神社（おぐにりょうじんじゃ）は、熊本県阿蘇郡小国町宮原に鎮座する神社。'),
    ('不動堂明王院', null, '京都府', null, 34.9867692, 135.7537044, 'C', '寺院', '不動堂明王院（ふどんどうみょうおういん）は、京都府京都市下京区にある寺院である。'),
    ('春日神社', null, '大阪府', null, 34.8313479, 135.511476, 'C', '神社', '春日神社（かすがじんじゃ）は大阪府箕面市小野原西に鎮座する神社。'),
    ('居神神社', null, '神奈川県', '小田原市', 35.246798, 139.1481812, 'C', '神社', '居神神社（いがみじんじゃ）は、神奈川県小田原市の旧小田原宿、板橋口（上方口）近くに鎮座する三浦荒次郎義意公を主祭神に祀る神社。'),
    ('水観寺', null, '滋賀県', null, 35.011477, 135.8545257, 'C', '寺院', '水観寺（すいかんじ）は、滋賀県大津市園城寺町にある天台寺門宗の寺院。総本山園城寺の別所。'),
    ('塩尾寺', null, '兵庫県', null, 34.805753, 135.3260607, 'C', '寺院', '塩尾寺(えんぺいじ)は、兵庫県宝塚市にある浄土宗の寺院。山号は潮泉山 (ちょうせんざん)。'),
