    ('応其寺', null, '和歌山県', null, 34.3166212, 135.6133048, 'C', '寺院', '応其寺（應其寺、おうごじ）は、和歌山県橋本市橋本にある高野山真言宗の寺院。山号を中興山、本尊は救世観世音菩薩、開基は同地を開発した僧侶、木食応其である。'),
    ('浄林寺', null, '長野県', null, 36.2337313, 137.9655596, 'C', '寺院', '浄林寺（じょうりんじ）は、長野県松本市中央にある浄土宗の寺院。山号・院号は清水山華厳院。'),
    ('報徳二宮神社', null, '栃木県', null, 36.7256592, 139.6894921, 'C', '神社', '報徳二宮神社（ほうとくにのみやじんじゃ）は、栃木県日光市にある神社である。'),
    ('倭文神社', null, '鳥取県', null, 35.440447, 134.2006023, 'C', '神社', '倭文神社（しとりじんじゃ）は、鳥取県鳥取市倭文にある神社。式内社で、旧社格は郷社。'),
    ('五十稲荷神社', null, '東京都', null, 35.6942059, 139.7620976, 'C', '神社', '栄寿稲荷神社（えいじゅいなりじんじゃ）は、東京都千代田区神田小川町にある神社である。通称、五十稲荷神社（ごとおいなりじんじゃ）。'),
    ('龍護寺', null, '岐阜県', null, 35.3063751, 137.3923479, 'C', '寺院', null),
    ('東覚寺', null, '東京都', null, 35.7354782, 139.7585831, 'C', '寺院', '東覚寺（とうがくじ）は、東京都北区田端2丁目にある真言宗豊山派の寺院。'),
    ('暁光山 正覺寺', null, '奈良県', null, 34.6781975, 135.8279868, 'C', '寺院', '正覚寺（しょうがくじ）は、奈良県奈良市南中町にある、浄土真宗本願寺派の寺院である。閣号　暁光閣、山号　暁光山　正覺寺である。'),
    ('久保市乙剣宮', null, '石川県', null, 36.5718719, 136.662994, 'C', '神社', '久保市乙剣宮（くぼいちおとつるぎぐう）は、石川県金沢市下新町6番21号にある神社。祭神は、素戔嗚尊。'),
    ('法乗院 (江東区)', null, '東京都', null, 35.6755766, 139.7966866, 'C', '寺院', '法乗院（ほうじょういん）は、東京都江東区深川二丁目にある真言宗豊山派の寺院。'),
    ('龍禅寺', null, '茨城県', null, 35.922792, 140.0232596, 'C', '寺院', null),
    ('富士嶽神社', null, '群馬県', null, 36.2392844, 139.5206113, 'C', '神社', '富士嶽神社（ふじたけじんじゃ）は、群馬県館林市の神社。'),
    ('大戸神社', null, '千葉県', null, 35.8841439, 140.4624702, 'C', '神社', '大戸神社（おおとじんじゃ）は、千葉県香取市大戸にある神社。香取神宮摂社で、旧社格は県社。'),
    ('大覚寺', null, '兵庫県', null, 34.7181232, 135.412532, 'C', '寺院', '大覚寺（だいかくじ）は、兵庫県尼崎市寺町にある律宗の寺院。山号は月峯山、本尊は千手十一面観音。'),
    ('圓福寺', null, '広島県', null, 34.3816302, 133.383276, 'C', '寺院', '円福寺（えんぷくじ）は、広島県福山市鞆町鞆にある真言宗大覚寺派の寺院。山号は南林山。'),
    ('本居宣長ノ宮', null, '三重県', null, 34.5741104, 136.5249045, 'C', '神社', '本居宣長ノ宮（もとおりのりながのみや）は、三重県松阪市殿町にある神社。本居宣長を国学神として祀る。'),
    ('八宮神社', null, '兵庫県', null, 34.6847, 135.1752846, 'C', '神社', '八宮神社（はちのみやじんじゃ）は神戸市中央区楠町に鎮座し、生田裔神八社の六宮神社と八宮神社とが合祀された神社。'),
    ('白山宮', null, '富山県', '南砺市', 36.4112167, 136.9306337, 'C', '神社', '上梨白山宮（かみなしはくさんぐう）は、富山県南砺市（旧平村）上梨にある神社。
