    ('豊平神社', null, '北海道', '札幌市', 43.0443884, 141.3807015, 'C', '神社', null),
    ('天徳院', null, '和歌山県', null, 34.2120395, 135.5840161, 'C', '寺院', '天徳院（てんとくいん）は、和歌山県伊都郡の高野山にある寺。金剛峯寺の南、高野山大学の西に位置する。'),
    ('観音寺', null, '東京都', null, 35.7255741, 139.7680796, 'C', '寺院', null),
    ('法光寺', null, '東京都', null, 35.7294483, 139.7664826, 'C', '寺院', '法光寺（ほうこうじ）は、東京都荒川区西日暮里三丁目（日暮里富士見坂下）にある法華宗陣門流の寺院。山号は日照山。'),
    ('朝山神社', null, '島根県', null, 35.3192453, 132.7727844, 'C', '神社', '朝山神社（あさやまじんじゃ）は島根県出雲市朝山町にある神社である。
『出雲国風土記』所載の宇比多伎山に比定される山の上に鎮座しており、神社の周囲は「朝山森林公園」となっている。'),
    ('今宮神社', null, '東京都', null, 35.7125214, 139.7313726, 'C', '神社', '今宮神社（いまみやじんじゃ）は、東京都文京区音羽にある神社。地名を冠して、音羽今宮神社（おとわいまみやじんじゃ）とも。'),
    ('安養寺', null, '東京都', null, 35.7075123, 139.5804858, 'C', '寺院', '安養寺（あんようじ）は、東京都武蔵野市にある真言宗豊山派の寺院。武蔵野吉祥七福神の寺社の一つである。'),
    ('長久寺', null, '愛知県', null, 35.1854314, 136.9190131, 'C', '寺院', null),
    ('法界山 大蓮寺', null, '鳥取県', '倉吉市', 35.432434, 133.823217, 'C', '寺院', '大蓮寺（だいれんじ）は鳥取県倉吉市の打吹玉川地区にある浄土宗の仏教寺院。豪商淀屋清兵衛歴代の墓や武将脇屋義助所縁の寺として知られる。'),
    ('七座神社', null, '秋田県', null, 40.2019799, 140.2571301, 'C', '神社', '七座神社（ななくらじんじゃ）とは、秋田県能代市二ツ井町小繋にある神社である。「ななざじんじゃ」とは、読まない。'),
    ('神宮寺', null, '三重県', null, 34.8374237, 136.5567741, 'C', '寺院', null),
    ('榛名神社', null, '群馬県', null, 36.6486549, 139.0352838, 'C', '神社', '榛名神社（はるなじんじゃ）は、群馬県沼田市榛名町にある神社。旧社格は県社。'),
    ('久我山稲荷神社', null, '東京都', null, 35.6883238, 139.5965264, 'C', '神社', '久我山稲荷神社（くがやまいなりじんじゃ）は、東京都杉並区久我山にある神社。登記上の宗教法人名称は稲荷神社（いなりじんじゃ）。'),
    ('安養寺', null, '東京都', null, 35.702514, 139.738195, 'C', '寺院', '安養寺（あんようじ）は、東京都新宿区にある天台宗の寺院。'),
