    ('多田寺', null, '福井県', null, 35.4783008, 135.7689727, 'D', '寺院', '多田寺（ただじ）は、福井県小浜市多田にある高野山真言宗の寺院。山号は石照山。'),
    ('旭山神社', null, '広島県', null, 34.3976514, 132.4248348, 'D', '神社', '旭山神社（あさひやまじんじゃ）は、広島県広島市西区己斐（こい）にある神社。地元では「鯉の神社」と親しまれている。'),
    ('岡村天満宮', null, '神奈川県', null, 35.4159827, 139.6131179, 'D', '神社', '岡村天満宮（おかむらてんまんぐう）は、神奈川県横浜市磯子区岡村にある天満宮である。'),
    ('六所神社', null, '東京都', null, 35.569345, 139.6831562, 'D', '神社', '六所神社（ろくしょじんじゃ）は東京都大田区の神社。地名を冠して下丸子六所神社（しもまるころくしょじんじゃ）とも称される。'),
    ('太平寺', null, '大阪府', null, 34.659298, 135.513845, 'D', '寺院', '太平寺（たいへいじ）は、大阪市天王寺区にある曹洞宗の寺院。山号は護國山。'),
    ('一心寺', null, '東京都', null, 35.6193279, 139.7430536, 'D', '寺院', '一心寺（いっしんじ）は、東京都品川区にある真言宗智山派の寺院。'),
    ('三福寺', null, '宮崎県', null, 32.5828767, 131.6657124, 'D', '寺院', '三福寺（さんふくじ）は、宮崎県延岡市にある浄土宗の寺院。山号は九品山。'),
    ('玄性寺', null, '栃木県', null, 36.8019444, 140.0575519, 'D', '寺院', '玄性寺（げんしょうじ）は、栃木県大田原市にある曹洞宗の寺院である。山号は須峯山。'),
    ('松崎神社', null, '千葉県', null, 35.7718509, 140.5317232, 'D', '神社', '松崎神社（まつさきじんじゃ）は、千葉県香取郡多古町（下総国香取郡）にある神社。旧社格は郷社。'),
    ('臨海寺', null, '沖縄県', null, 26.2385624, 127.6822771, 'D', '寺院', null),
