    ('正福寺', null, '埼玉県', null, 35.8892061, 139.6487052, 'D', '寺院', '正福寺（しょうふくじ）は、埼玉県さいたま市浦和区にある天台宗の寺院。'),
    ('極楽寺', null, '愛知県', null, 35.1616566, 136.9015705, 'D', '寺院', '極楽寺（ごくらくじ）は愛知県名古屋市にある単立の寺院。山号は教報山、本尊は阿弥陀如来坐像で恵心僧都の作と伝わる。'),
    ('冨吉建速神社・八剱社', null, '愛知県', null, 35.147455, 136.7873739, 'D', '神社', '冨吉建速神社・八劔社（とみよしたけはやじんじゃ・はちけんしゃ）は、愛知県海部郡蟹江町大字須成にある2つの神社。2社を合わせて須成神社（すなりじんじゃ）とも呼ばれる。'),
    ('林光寺', null, '埼玉県', null, 35.8923769, 139.596197, 'D', '寺院', null),
    ('加茂神社', null, '富山県', null, 36.7421525, 137.1419584, 'D', '神社', '加茂神社（かもじんじゃ）は、富山県射水市にある神社である。賀茂御祖神社領倉垣荘の惣社で、旧社格は郷社。'),
    ('大念寺', null, '京都府', null, 34.8944128, 135.6803556, 'D', '寺院', '大念寺（だいねんじ）は京都府乙訓郡大山崎町にある浄土宗の仏教寺院。山号は見仏山。'),
    ('祐綏神社', null, '山口県', null, 34.0616142, 131.8145262, 'D', '神社', '祐綏神社（ゆうすいじんじゃ）は、山口県周南市にある神社。祭神は徳山藩初代藩主･毛利就隆と9代藩主･毛利元蕃。'),
    ('天皇寺', null, '宮城県', null, 38.4406494, 140.8851823, 'D', '寺院', '天皇寺（てんのうじ）は、宮城県黒川郡大和町にある臨済宗妙心寺派の寺院。'),
    ('妙光寺', null, '東京都', null, 35.676263, 139.8738097, 'D', '寺院', '妙光寺（みょうこうじ）は、東京都江戸川区にある日蓮宗の寺院。'),
    ('明福寺', null, '東京都', null, 35.6853939, 139.8952444, 'D', '寺院', '明福寺（めいふくじ）（みょうふくじ）は、東京都江戸川区にある浄土宗の寺院。'),
    ('東雲寺', null, '愛知県', null, 35.2131202, 136.8789964, 'D', '寺院', '東雲寺（とううんじ）は、愛知県名古屋市西区中小田井にある臨済宗の寺院。山号は龍光山（りゅうこうざん）。'),
    ('富士浅間神社', null, '愛知県', null, 35.0864671, 137.046419, 'D', '神社', '富士浅間神社（ふじせんげんじんじゃ）は、愛知県愛知郡東郷町にある神社。『延喜式神名帳』の尾張国愛智郡「伊副神社」に比定する説があるが、異論も多い。'),
    ('隅田稲荷神社', null, '東京都', null, 35.7316072, 139.8241899, 'D', '神社', null),
    ('湯里住吉神社', null, '大阪府', null, 34.6126918, 135.5352113, 'D', '神社', '湯里住吉神社（ゆざとすみよしじんじゃ）は、大阪府大阪市東住吉区湯里にある神社。旧社格は村社。'),
    ('満福寺', null, '宮城県', '仙台市', 38.2499768, 140.8865379, 'D', '寺院', '満福寺（まんぷくじ）は、宮城県仙台市若林区荒町にある真言宗智山派の仏教寺院である。荒町商店街の東部に所在する。'),
    ('西應寺', null, '東京都', null, 35.6838162, 139.7229183, 'D', '寺院', null),
    ('荻窪白山神社', null, '東京都', null, 35.7054959, 139.6160504, 'D', '神社', null),
    ('御嶽神社', null, '千葉県', null, 35.702361, 140.0333412, 'D', '神社', '御獄神社 （みたけじんじゃ）は、千葉県船橋市前原東にある神社である。旧社格は村社。'),
    ('別所琴平神社', null, '熊本県', null, 32.7860135, 130.7052401, 'D', '神社', '別所琴平神社（べっしょことひらじんじゃ）は、熊本県熊本市中央区に鎮座する神社である。通称は別所のこんぴらさん。'),
    ('今宮神社', null, '京都府', null, 35.0204234, 135.7184684, 'D', '神社', '今宮神社（いまみやじんじゃ）は、京都府京都市右京区花園にある神社（御霊社）。かつては祇花園社（ぎけおんしゃ、ぎはなぞのしゃ）、花園社（はなぞのしゃ）とも呼ばれた。'),
    ('安布知神社', null, '長野県', '阿智村', 35.4475923, 137.745303, 'D', '神社', '安布知神社（あふちじんじゃ）は、長野県下伊那郡阿智村駒場にある神社。旧社格は郷社。'),
    ('気多神社', null, '兵庫県', null, 35.4783482, 134.7932976, 'D', '神社', '気多神社（けたじんじゃ）は、兵庫県豊岡市日高町上郷にある神社。式内社、但馬国総社で、旧社格は郷社。'),
    ('延浄寺', null, '東京都', null, 35.6634218, 139.5705916, 'D', '寺院', '延浄寺（えんじょうじ）は、東京都調布市にある浄土真宗本願寺派の寺院。'),
    ('氷川神社', null, '東京都', null, 35.7853801, 139.6400122, 'D', '神社', '氷川神社（ひかわじんじゃ）は東京都板橋区の神社。地名を冠して赤塚氷川神社（あかつかひかわじんじゃ）とも称される。'),
    ('神明社', null, '東京都', null, 35.6503471, 139.6073408, 'D', '神社', null),
    ('乗福寺', null, '神奈川県', null, 35.4121937, 139.4257492, 'D', '寺院', '乗福寺（じょうふくじ）は、神奈川県藤沢市にある曹洞宗の寺院。山号は万年山。'),
    ('善仁寺', null, '東京都', null, 35.7112134, 139.7373145, 'D', '寺院', '善仁寺（ぜんにんじ）は、東京都文京区にある浄土真宗本願寺派の寺院。'),
    ('西光寺', null, '東京都', null, 35.7344396, 139.8340088, 'D', '寺院', null),
    ('大泉院', null, '埼玉県', null, 35.8703577, 139.6028545, 'D', '寺院', '大泉院（だいせんいん）は、埼玉県さいたま市桜区にある曹洞宗の寺院。'),
    ('延命寺', null, '東京都', null, 35.7315668, 139.4977646, 'D', '寺院', '延命寺（えんめいじ）は、東京都小平市にある真言宗豊山派の寺院。'),
    ('勝興寺', null, '東京都', null, 35.6845765, 139.7227867, 'D', '寺院', '勝興寺（しょうこうじ）は、東京都新宿区にある曹洞宗の寺院。'),
    ('深光寺', null, '東京都', null, 35.7157871, 139.7374102, 'D', '寺院', '深光寺（じんこうじ）は、東京都文京区にある浄土宗の寺院。'),
    ('久度神社', null, '奈良県', null, 34.5992618, 135.6979315, 'D', '神社', '久度神社（くどじんじゃ）は、奈良県北葛城郡王寺町にある神社。式内社で旧社格は、村社。'),
    ('比賣神社', null, '奈良県', null, 34.6754438, 135.8463579, 'D', '神社', '比賣神社（ひめがみしゃ）は、奈良県奈良市高畑町にある神社。比賣塚と呼ばれる小さな古墳の上に建てられている。'),
    ('妙行寺', null, '愛知県', null, 35.1736073, 136.8560107, 'D', '寺院', null),
    ('龍泉寺', null, '東京都', null, 35.7233902, 139.7461667, 'D', '寺院', null),
    ('天祖諏訪神社', null, '東京都', null, 35.5973781, 139.7390016, 'D', '神社', '天祖・諏訪神社（てんそすわじんじゃ）は、東京都品川区南大井にある神社。'),
    ('胤重寺', null, '千葉県', '千葉市', 35.6037658, 140.1260201, 'D', '寺院', null),
    ('医王寺', null, '東京都', null, 35.6740277, 139.6119292, 'D', '寺院', '医王寺（いおうじ）は、東京都杉並区にある真言宗智山派の寺院。'),
    ('光明寺', null, '東京都', null, 35.7103468, 139.7856142, 'D', '寺院', '光明寺（こうみょうじ）は、東京都台東区にある浄土宗の寺院。'),
    ('羅漢寺', null, '東京都', null, 35.6895961, 139.8266777, 'D', '寺院', null),
    ('長福寺', null, '愛知県', null, 35.1580799, 136.9001542, 'D', '寺院', null),
    ('妙源寺', null, '東京都', null, 35.7460827, 139.8316532, 'D', '寺院', '妙源寺（みょうげんじ）は、東京都葛飾区堀切にある日蓮宗の寺院。山号は正覚山。'),
    ('伊去波夜和氣命神社', null, '宮城県', null, 38.4155704, 141.3630511, 'D', '神社', '伊去波夜和氣命神社（いこはやわけ（わき）のみことじんじゃ）は、宮城県石巻市にある神社である。
延喜式式内社のうちの一座である。'),
    ('本願寺新潟別院', null, '新潟県', null, 37.5405823, 138.8149863, 'D', '寺院', '本願寺新潟別院（ほんがんじにいがたべついん）は新潟県長岡市与板町にある浄土真宗本願寺派（西本願寺）の直属寺院（別院）である。'),
    ('香積寺', null, '宮城県', null, 38.5623643, 141.25792, 'D', '寺院', null),
    ('柏原八幡宮', null, '兵庫県', null, 35.1309253, 135.0794184, 'D', '寺院', '柏原八幡宮（かいばらはちまんぐう）は、兵庫県丹波市柏原町柏原（かいばら）にある神社。旧社格は県社。'),
    ('福住厳島神社', null, '北海道', '札幌市', 43.0155452, 141.3974083, 'D', '神社', '福住厳島神社（ふくずみいつくしまじんじゃ）は、北海道札幌市豊平区福住にある神社である。旧社格は無格社。'),
    ('真照寺', null, '東京都', null, 35.7218459, 139.2682114, 'D', '寺院', '真照寺（しんしょうじ）は、東京都あきる野市にある真言宗豊山派の寺院。'),
    ('城官寺', null, '東京都', null, 35.7449788, 139.7466584, 'D', '寺院', '城官寺（じょうかんじ）は、東京都北区上中里1丁目にある真言宗豊山派の寺院。'),
    ('天龍寺', null, '東京都', null, 35.614492, 139.7399617, 'D', '寺院', '天龍寺（てんりゅうじ）は、東京都品川区にある曹洞宗の寺院。'),
    ('天祖神社', null, '東京都', null, 35.7065574, 139.8209451, 'D', '神社', '天祖神社（てんそじんじゃ）は東京都江東区の神社。江東天祖神社（こうとうてんそじんじゃ）とも。'),
    ('倍賀春日神社', null, '大阪府', null, 34.8243552, 135.564646, 'D', '神社', '倍賀春日神社（へかかすがじんじゃ）は、大阪府茨木市にある春日神社九社の一つ。'),
    ('漢陽寺', null, '山口県', null, 34.2355661, 131.8150624, 'D', '寺院', '漢陽寺（かんようじ）は、山口県周南市鹿野上にある臨済宗南禅寺派の寺院。大本山南禅寺派別格地鹿苑山漢陽寺が、正式名称である[1]。'),
    ('嶋田神社', null, '奈良県', null, 34.6475524, 135.8455827, 'D', '神社', '嶋田神社（しまだじんじゃ）は、奈良県奈良市八島町にある神社。式内小社、旧社格は村社、神饌幣帛料供進社。'),
    ('伊居太神社', null, '兵庫県', null, 34.7472796, 135.4338017, 'D', '神社', '伊居太神社（いこたじんじゃ）は、兵庫県尼崎市下坂部にある神社。
摂津国河辺郡の式内社の伊居太神社の論社の1つ（もう1つは池田市の伊居太神社（いけだじんじゃ））。'),
    ('宝勝寺', null, '愛知県', null, 35.1972294, 136.9493819, 'D', '寺院', '宝勝寺（ほうしょうじ）とは、愛知県名古屋市守山区市場にある曹洞宗の寺院である。山号を玉峯山と称する。'),
    ('霊松院', null, '岐阜県', null, 35.4698345, 136.7810596, 'D', '寺院', null),
    ('一岡神社', null, '大阪府', null, 34.3758112, 135.2890034, 'D', '神社', '一岡神社（いちおかじんじゃ）は、大阪府泉南市にある神社。一丘神社とも書く。'),
    ('王日神社', null, '長野県', null, 36.7450065, 138.3780475, 'D', '神社', null),
    ('川面神社', null, '兵庫県', null, 34.8088627, 135.3507292, 'D', '神社', '川面神社（かわもじんじゃ）は、兵庫県宝塚市にある神社。旧武庫郡川面村の産土神。'),
    ('印鑰神社', null, '熊本県', null, 32.5674239, 130.6611979, 'D', '神社', '印鑰神社（いんにゃくじんじゃ）は、熊本県八代市鏡町鏡村にある神社である。旧社格は村社。'),
    ('八幡神社', null, '東京都', null, 35.6752302, 139.6304234, 'D', '神社', '下高井戸浜田山八幡神社（しもたかいどはまだやまはちまんじんじゃ）は、東京都杉並区下高井戸にある神社。登記上の宗教法人名称は八幡神社（はちまんじんじゃ）。'),
    ('常林寺', null, '東京都', null, 35.6443034, 139.739385, 'D', '寺院', '常林寺（じょうりんじ）は、東京都港区にある曹洞宗の寺院。新庄藩主戸沢家と結城藩主水野家の江戸に於ける菩提寺であった。'),
    ('南部神社', null, '岩手県', null, 39.3273736, 141.5277152, 'D', '神社', '南部神社（なんぶじんじゃ）は岩手県遠野市にある神社。鍋倉公園の入り口にある。'),
    ('久遠寺', null, '神奈川県', null, 35.4423913, 139.6148142, 'D', '寺院', '久遠寺（くおんじ）は、横浜市南区に所在する日蓮正宗の寺院。山号は霊松山（れいしょうさん）。'),
    ('円政寺', null, '山口県', null, 34.4113587, 131.3940402, 'D', '寺院', '円政寺（えんせいじ）は、山口県萩市南古萩町（萩城下町）にある真言宗御室派の寺院。建長6年（1254年）に現在の山口市円政寺町に創建され、明治3年（1870年）に現在地に移転した。'),
    ('大胡神社', null, '群馬県', null, 36.4217221, 139.1592537, 'D', '神社', '大胡神社（おおごじんじゃ）は群馬県前橋市河原浜町にある神社。旧社格は郷社。'),
    ('福泉寺', null, '東京都', null, 35.7536564, 139.5665374, 'D', '寺院', '福泉寺（ふくせんじ）は東京都西東京市下保谷にある日蓮宗の寺、山号は保谷山、院号は妙解院と号する。保谷駅北口ロータリーを発しこの寺院の前を通る道路は、「福泉寺通り」と呼ばれる。'),
    ('西徃寺', null, '埼玉県', null, 35.8122396, 139.8124007, 'D', '寺院', null),
    ('大倭神社', null, '埼玉県', null, 35.9150127, 139.5918655, 'D', '神社', '大倭神社（おおやまとじんじゃ）は、埼玉県さいたま市西区の神社。'),
    ('源昌寺', null, '東京都', null, 35.6387759, 139.7323079, 'D', '寺院', '源昌寺（げんしょうじ）とは東京都港区高輪1-23-28にある曹洞宗の寺院。'),
    ('圓勝寺', null, '東京都', null, 35.739641, 139.7525073, 'D', '寺院', '円勝寺（えんしょうじ）は、東京都北区にある浄土宗の寺院。'),
    ('慶珊寺', null, '神奈川県', null, 35.372018, 139.6345796, 'D', '寺院', '慶珊寺（けいさんじ）は、神奈川県横浜市金沢区富岡東に存在する真言宗御室派の寺。
寛永元年（1624年）に領主の豊島明重が両親の菩提を弔うため建立した寺。'),
    ('明泉寺 (大日寺)', null, '兵庫県', null, 34.6814278, 135.1440131, 'D', '寺院', '明泉寺（みょうせんじ）は兵庫県神戸市長田区明泉寺町にある臨済宗の仏教寺院。寺名よりも大日寺、大日さんで知られている。'),
    ('白鳥神社', null, '岐阜県', null, 35.8888612, 136.8580971, 'D', '神社', null),
    ('阿弥陀寺', null, '神奈川県', null, 35.3669311, 139.5973263, 'D', '寺院', null),
    ('本願寺函館別院', null, '北海道', null, 41.7638572, 140.7227269, 'D', '寺院', '本願寺函館別院（ほんがんじはこだてべついん）は、北海道函館市にある浄土真宗本願寺派の寺院である。'),
    ('西圓寺', null, '岐阜県', null, 35.3986547, 136.5893684, 'D', '寺院', null),
    ('祇園寺', null, '東京都', null, 35.6592891, 139.5556918, 'D', '寺院', '祇園寺（ぎおんじ）は、東京都調布市にある天台宗の寺院。山号は虎狛山。'),
    ('足立神社', null, '埼玉県', null, 35.8974857, 139.5895903, 'D', '神社', null),
