    ('天湯川田神社', null, '大阪府', null, 34.5737512, 135.6327283, 'D', '神社', '天湯川田神社（あまゆかわたじんじゃ）は、大阪府柏原市高井田にある神社。式内社で、旧社格は村社。'),
    ('大聖寺', null, '福島県', null, 37.4976264, 141.0146205, 'D', '寺院', '大聖寺（だいしょうじ）は、福島県双葉郡浪江町にある真言宗室生寺派の寺院。'),
    ('錦山天満宮', null, '北海道', '江別市', 43.0962884, 141.5197018, 'D', '神社', null),
