    ('玉林院', null, '長野県', null, 35.7861046, 137.6962249, 'D', '寺院', '玉林院（ぎょくりんいん）は 長野県木曽郡上松町にある臨済宗妙心寺派の寺院。山号は聖岩山。'),
    ('曹洞宗 宗清禅寺', null, '東京都', null, 35.708559, 139.677313, 'D', '寺院', '宗清寺（そうせいじ）は、東京都中野区にある曹洞宗の寺院。'),
    ('真福寺', null, '東京都', null, 35.6861184, 139.5840768, 'D', '寺院', '真福寺（しんぷくじ）は、東京都三鷹市牟礼にある日蓮宗の寺院。山号は高栄山。'),
    ('延命寺', null, '宮城県', null, 38.0078531, 140.6244856, 'D', '寺院', '延命寺（えんめいじ）は、宮城県白石市にある真言宗智山派の寺院。新西國霊場刈田札所第三十三番。'),
    ('西善寺', null, '東京都', null, 35.7195631, 139.7565425, 'D', '寺院', null),
    ('絹巻神社', null, '兵庫県', null, 35.6406314, 134.8284414, 'D', '神社', '絹巻神社（きぬまきじんじゃ）は、兵庫県豊岡市にある神社。式内社（名神大社）海神社と比定される。'),
    ('泊船軒', null, '東京都', null, 35.7421537, 139.7822586, 'D', '寺院', '泊船軒（はくせんけん）は、東京都荒川区にある臨済宗妙心寺派の寺院。'),
    ('高木神社', null, '東京都', null, 35.7654592, 139.8398903, 'D', '神社', null),
    ('應典院', null, '大阪府', null, 34.6654373, 135.5114275, 'D', '寺院', '應典院（おうてんいん）は、大阪府大阪市天王寺区にある浄土宗知恩院末の寺院。創建当初は、大蓮寺の第3世に当たる誓誉在慶の隠棲所として開基された塔頭であった。'),
    ('八幡神社', null, '大阪府', null, 34.391895, 135.590528, 'D', '神社', '八幡神社（はちまんじんじゃ）は、大阪府河内長野市にある神社。旧社格は村社。'),
    ('秩父20 法王山 岩之上堂', null, '埼玉県', null, 36.0174232, 139.0844927, 'D', '寺院', '岩之上堂（いわのうえどう）は、埼玉県秩父市にある臨済宗南禅寺派の寺院で、山号は法王山と号する。'),
    ('浄輪寺', null, '東京都', null, 35.7027266, 139.7274307, 'D', '寺院', '浄輪寺（じょうりんじ）は、東京都新宿区弁天町にある日蓮宗の寺院。旧本山は池上本門寺。'),
    ('萩生寺', null, '愛媛県', null, 33.9261575, 133.2740747, 'D', '寺院', null),
    ('杉山神社', null, '神奈川県', null, 35.4711682, 139.5700803, 'D', '神社', '杉山神社（すぎやまじんじゃ）は神奈川県横浜市保土ケ谷区川島町にある神社。川島町の鎮守で、横浜市内唯一かつ旧武蔵国の式内社である「杉山神社」の論社の一つとされる。'),
    ('宝珠院', null, '大阪府', null, 34.7000107, 135.5145106, 'D', '寺院', '宝珠院（ほうしゅいん）は、大阪府大阪市北区与力町にある真言宗御室派の仏教寺院。寺伝により「ほうじゅ」と濁らないで読む。'),
    ('十番稲荷神社', null, '東京都', null, 35.6570211, 139.7350897, 'D', '神社', '十番稲荷神社（じゅうばんいなりじんじゃ）は、東京都港区麻布十番にある神社。'),
    ('大宮神社', null, '千葉県', null, 35.7115775, 140.0266347, 'D', '神社', '大宮神社（おおみやじんじゃ）は、千葉県船橋市にある神社。旧社格は村社。'),
    ('瑞巌寺', null, '徳島県', null, 34.0679373, 134.5443939, 'D', '寺院', '瑞巌寺（ずいがんじ）は、徳島県徳島市にある臨済宗妙心寺派の寺院。山号は鳳翔山。'),
    ('即清寺', null, '東京都', '青梅市', 35.7935104, 139.2137073, 'D', '寺院', '即清寺（そくせいじ）は、東京都青梅市柚木町（多摩郡杣保永川郷由木村）にある真言宗豊山派の寺院。'),
    ('高天神社', null, '静岡県', null, 34.6980994, 138.0340793, 'D', '神社', null),
    ('日枝社', null, '埼玉県', null, 35.8670154, 139.6042806, 'D', '神社', '日枝社（ひえしゃ）は、埼玉県さいたま市桜区の神社。'),
    ('微妙寺', null, '滋賀県', null, 35.0110264, 135.8531026, 'D', '寺院', '微妙寺（びみょうじ）は、滋賀県大津市園城寺町にある天台寺門宗の寺院。総本山園城寺の別所。'),
    ('正崇寺', null, '滋賀県', null, 35.0140038, 136.2484169, 'D', '寺院', '正崇寺（しょうそうじ）は、滋賀県蒲生郡日野町大窪にある浄土真宗本願寺派の仏教寺院。山号は川原山（せんげんさん）。'),
