    ('念仏寺', null, '兵庫県', null, 34.7960585, 135.2486226, 'D', '寺院', '念仏寺（ねんぶつじ）は、兵庫県神戸市北区有馬町にある浄土宗の寺院。山号は摂取山。'),
    ('吉備寺', null, '岡山県', null, 34.62967, 133.6845768, 'D', '寺院', '吉備寺（きびじ）は、岡山県倉敷市真備町にある真言宗御室派の寺院。山号は鏡林山。'),
    ('東光寺', null, '岐阜県', null, 35.5198155, 136.7282583, 'D', '寺院', '東光寺（とうこうじ）は、岐阜県山県市小倉にある臨済宗妙心寺派の寺院。山号は富士山。'),
    ('柳原神社', null, '長野県', null, 36.6425363, 138.1844954, 'D', '神社', '柳原神社（やなぎはらじんじゃ）は、長野県長野市中御所一丁目にある神社（村社）。通称は笹焼神社・笹焼大明神、旧称は諏訪大明神。'),
    ('三大神社', null, '滋賀県', null, 35.0485466, 135.9375273, 'D', '神社', '三大神社（さんだいじんじゃ）は、滋賀県草津市志那町に鎮座する神社である。式内社論社である。'),
    ('本光寺 (Honkō-ji)', null, '岐阜県', null, 36.2338302, 137.1883321, 'D', '寺院', '本光寺（ほんこうじ）は、岐阜県飛騨市古川町にある浄土真宗本願寺派の寺院。山号は白豹山。'),
    ('祥雲寺', null, '東京都', '町田市', 35.5376684, 139.4583146, 'D', '寺院', '祥雲寺（しょううんじ）は、東京都町田市にある曹洞宗の寺院。'),
    ('珊瑚寺', null, '和歌山県', null, 34.2227342, 135.1754338, 'D', '寺院', '珊瑚寺（さんごじ）は、和歌山県和歌山市鷹匠町にある曹洞宗の仏教寺院である。山号は仙境山と称する。'),
    ('綱生山 当光寺', null, '東京都', null, 35.6526017, 139.7390717, 'D', '寺院', '當光寺（とうこうじ）は、東京都港区にある浄土真宗本願寺派の寺院。'),
    ('日間賀神社', null, '愛知県', null, 34.706569, 137.0115041, 'D', '神社', '日間賀神社（ひまかじんじゃ）は、愛知県知多郡南知多町大字日間賀島北地にある神社。『尾張国内神名帳』の智多郡「杞摩加天神」に比定されている。'),
    ('春日神社', null, '大阪府', null, 34.807443, 135.4642863, 'D', '神社', '春日神社（かすがじんじゃ）は、大阪府豊中市宮山町にある神社である。社殿北側のつつじの園は満開時、大勢の見物客で賑う。'),
    ('澄江寺', null, '山形県', null, 38.3780103, 140.2738477, 'D', '寺院', '澄江寺（ちょうこうじ）は山形県寒河江市にある曹洞宗の寺院。'),
    ('天満神社', null, '兵庫県', null, 34.8215113, 135.3778893, 'D', '神社', '天満神社（てんまんじんじゃ）は兵庫県宝塚市山本にある神社である。地元では「西の宮さん」と呼ばれ、東の松尾神社と並んで旧川辺郡山本村の産土神。'),
    ('神明社', null, '愛知県', null, 34.8856137, 136.8399152, 'D', '神社', '神明社（しんめいしゃ）は、愛知県常滑市栄町6丁目200にある神社。社格は旧郷社。'),
    ('妙蓮寺', null, '千葉県', null, 35.7588391, 139.9927765, 'D', '寺院', '妙蓮寺（みょうれんじ）は、千葉県鎌ケ谷市東道野辺にある日蓮宗の寺院。'),
    ('有松天満社', null, '愛知県', null, 35.0708818, 136.9682264, 'D', '神社', '有松天満社（ありまつてんましゃ）は、愛知県名古屋市緑区鳴海町にある神社。旧社格は村社。'),
    ('妙法寺', null, '岐阜県', null, 35.3682698, 137.4419468, 'D', '寺院', '妙法寺（みょうほうじ）は、岐阜県恵那市岩村町にある日蓮宗の寺院。'),
    ('称名寺', null, '茨城県', null, 36.3024106, 139.872714, 'D', '寺院', null),
    ('白坂神社', null, '大阪府', null, 34.5709472, 135.6378114, 'D', '神社', '宿奈川田神社（すくなかわたじんじゃ）は、大阪府柏原市にある神社。式内社で、旧社格は村社。'),
    ('妙円寺', null, '東京都', null, 35.6354977, 139.7218464, 'D', '寺院', '妙圓寺は、東京都港区白金台にある日蓮宗の寺院。山号は誠瀧山。'),
    ('射矢止神社', null, '和歌山県', null, 34.2622017, 135.2045686, 'D', '神社', '射矢止神社（いやとじんじゃ）は、和歌山県和歌山市六十谷（むそた）に鎮座する神社。六十谷と紀ノ川南岸有本地区の字新出、字船所の産土神。'),
