    ('慈光寺', null, '栃木県', null, 36.5653802, 139.8868536, 'D', '寺院', '慈光寺（じこうじ）は、栃木県宇都宮市にある浄土宗の寺院である。桜の名所でもあり、宇都宮市で最も早く咲くといわれる樹齢150年越えのヒガンザクラの木がある。'),
    ('下之坊', null, '静岡県', null, 35.2616916, 138.5798529, 'D', '寺院', '下之坊（しものぼう）は、静岡県富士宮市に所在する日蓮正宗の寺院。山号は大日蓮華山（だいにちれんげさん）。'),
    ('徳運寺', null, '長野県', null, 36.2213915, 138.0447212, 'D', '寺院', '徳運寺（とくうんじ）は、長野県松本市入山辺にある曹洞宗の寺院。山号は福田山。'),
    ('白山社', null, '長野県', null, 35.5253159, 137.8079422, 'D', '神社', '白山社（はくさんしゃ）は、長野県飯田市の風越山に所在する神社。旧社格は県社である。'),
    ('田原神社', null, '島根県', null, 35.4824137, 133.0521829, 'D', '神社', '田原神社（たわらじんじゃ）は島根県松江市奥谷町に鎮座する神社。元来は2社であったが江戸時代の延宝2年（1674年）に1社に合わさった。'),
    ('篠津神社', null, '滋賀県', null, 34.9906857, 135.8932302, 'D', '神社', '篠津神社（しのづじんじゃ）は、滋賀県大津市中庄に鎮座する神社である。'),
    ('親縁寺', null, '神奈川県', null, 35.3910806, 139.5291571, 'D', '寺院', null),
